  // ---- Butchering trains Logic (it leads the Refining tab) ------------------------------
  suite('butchering trains the Logic physique', function(){
    // Logic is the Refining physique; Butchering is a gathering skill shown in the Refining tab.
    ok(FF.physiqueTrainedBySkill('butchering').indexOf('logic') !== -1, 'butchering earns Logic XP');
    ok(FF.physiqueBenefitsForSkill('butchering').some(function(e){ return e[0] === 'logic'; }), 'the (?) "trained by" list shows Logic for butchering');
    ok((FF.GATHER_PHYSIQUE.butchering || []).some(function(p){ return p[0] === 'logic'; }), 'GATHER_PHYSIQUE.butchering includes a logic pair');
    // Other gathering skills do NOT grant Logic -- it stays a Refining-only physique.
    ['mining','fishing','forestry','herbalism','foraging'].forEach(function(sk){
      ok(FF.physiqueTrainedBySkill(sk).indexOf('logic') === -1, sk + ' does not train Logic');
    });
    // Processing a carcass (the butcher craft path) must actually AWARD Logic -- it used to read an
    // undefined CRAFT_PHYSIQUE.butchering table and grant no physique XP at all. And at the crafting rate.
    function logicAmt(pairs){ var p = (pairs||[]).filter(function(x){ return x[0]==='logic'; })[0]; return p ? p[1] : 0; }
    eq(logicAmt(FF.physTierPairs(FF.GATHER_PHYSIQUE.butchering, 5)),
       logicAmt(FF.physTierPairs(FF.CRAFT_PHYSIQUE.metallurgy, 5)),
       'Butchering trains Logic at the same per-tier rate as a crafting skill');
    var S = FF._state;
    var saved = { inv:S.inventory, act:S.activity, logic:S.physique.logic, str:S.physique.bodyStrength };
    try {
      S.activity = { type:null };
      S.physique.logic = 0; S.physique.bodyStrength = 0;
      S.inventory = { corpse_t5: 1 };
      FF.processCraftActivity({ type:'craft', skill:'butchering', itemId:'butcher_process_t5', progress:0 }, 3600*1000);
      ok((S.physique.logic||0) > 0, 'processing a carcass grants Logic physique XP (it granted none before this fix)');
      ok((S.physique.bodyStrength||0) > 0, '...along with its other gather physiques');
    } finally {
      S.inventory = saved.inv; S.activity = saved.act; S.physique.logic = saved.logic; S.physique.bodyStrength = saved.str;
    }
  });

  // ---- Offline faith: a running miracle keeps its rarity buff, at the cost of Faith + relics ----
  suite('offline faith activity: buff costs faith + relics, ends when dry', function(){
    var s = FF._state;
    var saved = { fa:s.faithActivity, faith:s.faith, auto:s.autoSacrificeRelics,
      xpM:s.xp.miracle, prayer:s.xp.prayer, phys:Object.assign({}, s.physique) };
    s.xp.prayer = 0;                              // Prayer Lv1 -> faithMax = 100 base + 100/level (below the 80 Faith used here regardless)
    // Zero the physiques that feed faithMax so the cap is a clean base for the arithmetic below.
    Object.keys(s.physique).forEach(function(k){ s.physique[k] = 0; });
    s.faithActivity = { type:'miracle', tier:0 };
    s.autoSacrificeRelics = false;
    var perSec = FF.FAITH_ACTIVITY_TIERS.miracle[0].faithPerSec;

    // A) Runs dry mid-window: 80 Faith, 1h window, no relics -> alive = 80 / drain-rate seconds.
    s.faith = 80;
    var pA = FF.planOfflineFaithActivity(3600*1000);
    ok(pA.died, 'a short Faith pool runs the miracle dry before the window ends');
    eq(Math.round(pA.aliveMs), Math.round(80/perSec*1000), 'alive time = Faith / drain rate');
    eq(pA.finalFaith, 0, 'Faith ends at 0 when it runs dry');
    // v0.0.86.35 (owner order): the buff's COVERAGE is the whole window once it was activated with Faith
    // to spend, even though its FUEL ran out early. The old rule (coverage == fuel) is kept as
    // fuelFraction, which is what the offline log reports and what XP still keys off.
    eq(pA.fraction, 1, 'an activated buff covers offline crafts for the whole window');
    ok(pA.fuelFraction > 0 && pA.fuelFraction < 1, 'while its FUEL still only stretches part of the window');
    eq(Math.round(pA.xp), Math.round(FF.FAITH_ACTIVITY_TIERS.miracle[0].xpPerSec * pA.aliveMs/1000),
       'XP follows the fuel burned, not the coverage, so persisting the buff mints no XP');
    eq(s.faith, 80, 'planning does not mutate live Faith (the offline pass applies it)');
    // No Faith at logout means there was no live buff to persist: coverage stays zero.
    var svF = s.faith; s.faith = 0;
    var pZ = FF.planOfflineFaithActivity(3600*1000);
    eq(pZ.fraction, 0, 'a buff with no Faith at logout covers nothing');
    s.faith = svF;

    // B) Ample Faith outlasts a short window -> buff active the whole time, Faith just drains.
    s.faith = 100;
    var pB = FF.planOfflineFaithActivity(10*1000);      // 10s
    ok(!pB.died && pB.fraction === 1, 'ample Faith keeps the buff active the whole short window');
    eq(pB.finalFaith, 100 - perSec*10, 'Faith drains by rate x time');
    // The SETTLE applies faithBurned as a delta, not finalFaith as a snapshot (v0.0.86.43). Pin the
    // burn figure in every branch, because the settle now depends on it rather than on finalFaith.
    eq(pB.faithBurned, perSec*10, 'faithBurned is the Faith the activity actually consumed');
    eq(Math.round(pA.faithBurned), 80, 'a plan that ran dry burned exactly the pool it had');
    eq(pB.relicCount, 0, 'no relics spent while Faith alone covers the window');

    // C) Auto-sacrificed relics extend a dying miracle (more alive time than with no relics).
    s.faith = 80; s.autoSacrificeRelics = true;
    var rid0 = FF.BROKEN_RELIC_ITEMS[0].id, savedRelic = s.inventory[rid0]||0, savedLock = s.lockedItems[rid0];
    s.lockedItems[rid0] = false; s.inventory[rid0] = 50;
    var pC = FF.planOfflineFaithActivity(3600*1000);
    ok(pC.relicCount > 0, 'relics are auto-sacrificed to feed the miracle');
    ok(pC.aliveMs > pA.aliveMs, 'relics extend how long the buff stays alive');

    // D) FLAGGED OFFERINGS fuel the away window too (owner order, v0.0.86.37). The per-card
    // auto-sacrifice list was live-only, so a player who marked a pile of gear got nothing from it while
    // away and the buff still starved. Relics go FIRST, then anything else marked.
    var svAuto = s.autoSacrifice;
    s.autoSacrifice = {};
    s.faith = 80; s.autoSacrificeRelics = false; s.inventory[rid0] = 0;   // no relics: isolate the item path
    var pNoItems = FF.planOfflineFaithActivity(3600*1000);
    // Stock a real stackable offering: collectSacrificeRows only lists what is OWNED and unlocked, and by
    // this point in the suite the fixture bag is empty of them.
    var fid = Object.keys(FF.STACKABLE_WEAPON_ITEMS)[0];
    var svFlagInv = s.inventory[fid], svFlagLock = s.lockedItems[fid];
    s.inventory[fid] = 500; s.lockedItems[fid] = false;
    var flagRow = FF.collectSacrificeRows().filter(function(r){ return r.id === fid; })[0];
    ok(!!flagRow, 'the seeded offering shows up as a sacrificeable row');
    ok(FF.sacRowRestore(flagRow) > 0, 'and it restores real Faith');
    s.autoSacrifice[FF.sacRowKey(flagRow)] = true;
    var pD = FF.planOfflineFaithActivity(3600*1000);
    ok(pD.itemCount > 0, 'flagged offerings are spent to feed the buff while away');
    ok(pD.faithFromItems > 0, 'and they contribute real Faith');
    ok(pD.aliveMs > pNoItems.aliveMs, 'which extends how long the buff stays alive');
    eq(s.inventory[fid], 500, 'planning is still PURE: the offerings are consumed by the offline settle, not the plan');
    // Ordering: with BOTH available, relics are drawn on first (the owner's explicit requirement).
    s.autoSacrificeRelics = true; s.inventory[rid0] = 50; s.faith = 80;
    var pE = FF.planOfflineFaithActivity(3600*1000);
    ok(pE.relicCount > 0, 'relics are still spent when both sources are available');
    ok(pE.faithFromRelics > 0, 'and their Faith is credited under the relic tally');
    ok(pE.itemCount === 0 || pE.faithFromRelics > 0, 'flagged offerings only pick up what the relics leave short');
    // An UNFLAGGED item is never touched, however much Faith it would give.
    s.autoSacrifice = {}; s.autoSacrificeRelics = false; s.inventory[rid0] = 0; s.faith = 80;
    var pF = FF.planOfflineFaithActivity(3600*1000);
    eq(pF.itemCount, 0, 'nothing unflagged is ever sacrificed');
    // THE SETTLE MUST ACTUALLY CONSUME THEM. The plan is pure, so if applyOfflineProgress forgets to
    // decrement the offerings the buff is fuelled for free and the items stay in the bag -- a minting bug
    // the plan-level assertions above cannot see (proven: deleting the decrement failed nothing until
    // this ran the real offline pass).
    var svAct2 = s.activity, svFaith2 = s.faith, svCap = s.faithActivity;
    try {
      s.activity = { type:null };
      s.faithActivity = { type:'miracle', tier:0 };
      s.faith = 5;                                  // starves at once, so offerings must be drawn on
      s.autoSacrificeRelics = false; s.autoSacrifice = {};
      s.inventory[fid] = 400; s.lockedItems[fid] = false;
      s.autoSacrifice[FF.sacRowKey(FF.collectSacrificeRows().filter(function(r){ return r.id===fid; })[0])] = true;
      FF.applyOfflineProgress(3600*1000);
      ok((s.inventory[fid]||0) < 400, 'the offline pass really consumes the flagged offerings it burned');
    } finally { s.activity = svAct2; s.faith = svFaith2; s.faithActivity = svCap; }
    s.inventory[fid] = svFlagInv; s.lockedItems[fid] = svFlagLock; s.autoSacrifice = svAuto;
    s.inventory[rid0] = savedRelic; s.lockedItems[rid0] = savedLock;

    // restore
    s.faithActivity = saved.fa; s.faith = saved.faith; s.autoSacrificeRelics = saved.auto;
    s.xp.miracle = saved.xpM; s.xp.prayer = saved.prayer; s.physique = saved.phys;
  });

  // ---- Butchering yield: each output is 0-3 (three independent rolls), not 0-1 ----
  suite('butchering yields 0-3 of each output', function(){
    var s = FF._state;
    var saved = { tier:s.gatherTools.butchering, rar:s.gatherToolRarities.butchering, hs:s.physique.handStrength, hunt:s.physique.huntsman };
    s.gatherTools.butchering = 0; s.gatherToolRarities.butchering = 'normal';
    s.physique.handStrength = 0; s.physique.huntsman = 0;   // base 40% chance, no bonuses
    eq(FF.BUTCHER_OUTPUT_ROLLS, 3, 'each output rolls up to three times');
    var origRandom = Math.random;
    try {
      Math.random = function(){ return 0; };      // every roll succeeds
      eq(FF.butcherOutputQty(s, 'handStrength'), 3, 'all three rolls succeed -> 3 of the output (the new max)');
      Math.random = function(){ return 0.999; };  // every roll fails (above the 95% cap)
      eq(FF.butcherOutputQty(s, 'handStrength'), 0, 'all three rolls fail -> 0 of the output');
    } finally { Math.random = origRandom; }
    s.gatherTools.butchering = saved.tier; s.gatherToolRarities.butchering = saved.rar;
    s.physique.handStrength = saved.hs; s.physique.huntsman = saved.hunt;
  });

  // ---- Butchering: the bonus-output mechanics (Workshop double / Brew / Mastery) multiply the yield ----
  // Reported bug: a Butchering Workshop's double-output never fired -- the butcher branch produced Meat/Hide/
  // Fat but skipped the workshop/brew/mastery rolls the generic craft branch runs. They share one _bMult; we
  // exercise it here via a Brew (deterministic to force), which proves the multiplier now reaches butchering.
  suite('butchering: a bonus-output roll doubles the whole carcass yield', function(){
    var s = FF._state;
    var saved = { inv:s.inventory, act:s.activity, brew:s.activeBrew, tier:s.gatherTools.butchering,
      rar:s.gatherToolRarities.butchering, hs:s.physique.handStrength, fm:s.physique.fineMotor, hunt:s.physique.huntsman };
    var origRandom = Math.random;
    try {
      s.activity = { type:null };
      s.gatherTools.butchering = 0; s.gatherToolRarities.butchering = 'normal';
      s.physique.handStrength = 0; s.physique.fineMotor = 0; s.physique.huntsman = 0; // base 40% -> Math.random 0 always succeeds
      // Baseline: no bonus active -> 3 of each (all three rolls succeed at Math.random 0).
      s.activeBrew = { itemId:null, name:null, icon:null, yield:0, durationMs:0, expiresAt:0 };
      s.inventory = { corpse_t5: 1 };
      Math.random = function(){ return 0; };
      FF.processCraftActivity({ type:'craft', skill:'butchering', itemId:'butcher_process_t5', progress:0 }, 3600*1000);
      eq(s.inventory['meat_t5']||0, 3, 'no bonus -> 3 Meat from one carcass');
      eq(s.inventory['butchering_t5']||0, 3, 'no bonus -> 3 Hide');
      // With an active Brew (yield 1) the same bonus path fires -> the whole yield doubles.
      s.inventory = { corpse_t5: 1 };
      s.activeBrew = { itemId:'brew_test', name:'Test Brew', icon:'', yield:1, durationMs:1e7, expiresAt:Date.now()+1e7 };
      FF.processCraftActivity({ type:'craft', skill:'butchering', itemId:'butcher_process_t5', progress:0 }, 3600*1000);
      eq(s.inventory['meat_t5']||0, 6, 'a bonus-output roll doubles the Meat (3 -> 6) -- the path the Workshop double uses');
      eq(s.inventory['butchering_t5']||0, 6, 'and doubles the Hide (3 -> 6)');
    } finally {
      Math.random = origRandom;
      s.inventory = saved.inv; s.activity = saved.act; s.activeBrew = saved.brew;
      s.gatherTools.butchering = saved.tier; s.gatherToolRarities.butchering = saved.rar;
      s.physique.handStrength = saved.hs; s.physique.fineMotor = saved.fm; s.physique.huntsman = saved.hunt;
    }
  });

  // ---- Butchering tool: success bonus that scales with tier AND rarity, like other crafting tools ----
  suite('butchering tool raises success chance (tier + rarity, like craft tools)', function(){
    var s = FF._state;
    var savedTiers = s.gatherTools.butchering, savedRar = s.gatherToolRarities.butchering, savedPhys = s.physique.handStrength;
    s.physique.handStrength = 0; // isolate the tool's contribution from physique
    // The Cleaver's gather-tool data now carries a successBonus (other gather tools do not).
    var cleaver = FF.getGatherToolTierData('butchering', 11);
    ok(typeof cleaver.successBonus === 'number' && cleaver.successBonus > 0, 'the Cleaver has a successBonus like a craft tool');
    ok(FF.getGatherToolTierData('mining', 11).successBonus == null, 'a normal gather tool (Pickaxe) has no successBonus');
    // Its success curve matches the craft-tool success curve at the same tier.
    eq(cleaver.successBonus, FF.getEquippedCraftTool('metallurgy', 11, 'normal').successBonus, 'the Cleaver uses the same per-tier success curve as craft tools');
    // Higher tier -> more butcher output chance.
    s.gatherTools.butchering = 0; s.gatherToolRarities.butchering = 'normal';
    var none = FF.butcherOutputChance(s, 'handStrength');
    s.gatherTools.butchering = 5;
    var t5 = FF.butcherOutputChance(s, 'handStrength');
    s.gatherTools.butchering = 21;
    var t21 = FF.butcherOutputChance(s, 'handStrength');
    ok(t5 > none && t21 > t5, 'a better Cleaver raises butcher output chance');
    // Higher RARITY at the SAME tier -> more output chance (this is the "like craft tools" part).
    s.gatherTools.butchering = 11;
    s.gatherToolRarities.butchering = 'normal';   var norm = FF.butcherOutputChance(s, 'handStrength');
    s.gatherToolRarities.butchering = 'fantastic'; var fant = FF.butcherOutputChance(s, 'handStrength');
    ok(fant > norm, 'a Fantastic Cleaver beats a Normal one of the same tier (rarity scales success)');
    // restore
    s.gatherTools.butchering = savedTiers; s.gatherToolRarities.butchering = savedRar; s.physique.handStrength = savedPhys;
  });

  // ---- Farming: Harvest All / Plant All bulk actions -----------------------------------
  suite('farming bulk actions', function(){
    var S = FF._state, grid = S.estate.grid, pm = FF.farmPlotMap('personal');
    // Grab three real grid cells and turn them into fields of tiers 5 / 2 / 0.
    var cells = [];
    for(var x=0; x<grid.length && cells.length<3; x++){ if(!grid[x]) continue; for(var y=0; y<grid[x].length && cells.length<3; y++){ if(grid[x][y]) cells.push([x,y]); } }
    var savedTiers = cells.map(function(c){ return grid[c[0]][c[1]].fieldTier; });
    var savedPlots = {}; Object.keys(pm).forEach(function(k){ savedPlots[k]=pm[k]; delete pm[k]; });
    var savedInv = { t5:S.inventory.seed_t5||0, t2:S.inventory.seed_t2||0, t0:S.inventory.seed_t0||0 };

    [5,2,0].forEach(function(t,i){ grid[cells[i][0]][cells[i][1]].fieldTier = t; });
    S.inventory.seed_t5 = 1; S.inventory.seed_t2 = 1; S.inventory.seed_t0 = 5;

    ok(FF.allFieldPlots().filter(function(p){ return p.scope==='personal'; }).length >= 3, 'three personal fields present');

    // Plant All: best seeds go to the best fields; dry-run count matches the real run.
    eq(FF.farmingPlantAll(true), 3, 'dry-run plants all three empty fields');
    eq(FF.farmingPlantAll(false), 3, 'plant-all fills all three');
    var byTier = {}; FF.allFieldPlots().forEach(function(p){ if(p.tier===5||p.tier===2||p.tier===0){ byTier[p.tier] = p.plot && p.plot.tierIndex; } });
    eq(byTier[5], 5, 'tier-5 field got the highest fitting seed (t5)');
    eq(byTier[2], 2, 'tier-2 field got the t2 seed (t5 doesn\'t fit)');
    eq(byTier[0], 0, 'tier-0 field got a t0 seed');
    eq(FF.farmingPlantAll(true), 0, 'nothing left to plant once every field is full');

    // Harvest All: ripen them, then one call clears every ready plot.
    FF.allFieldPlots().forEach(function(p){ if(p.plot && p.plot.cropType) p.plot.readyAt = Date.now() - 1; });
    eq(FF.farmingReadyCount(), 3, 'all three crops are ready');
    eq(FF.farmingHarvestAll(), 3, 'harvest-all clears all three');
    eq(FF.farmingReadyCount(), 0, 'no ready crops remain after harvest-all');

    // restore
    Object.keys(pm).forEach(function(k){ delete pm[k]; });
    Object.keys(savedPlots).forEach(function(k){ pm[k]=savedPlots[k]; });
    cells.forEach(function(c,i){ grid[c[0]][c[1]].fieldTier = savedTiers[i]; });
    S.inventory.seed_t5 = savedInv.t5; S.inventory.seed_t2 = savedInv.t2; S.inventory.seed_t0 = savedInv.t0;
  });

  // ---- Fertilizer: a refinement crafting skill; doubles a same-tier growing crop's harvest --------
  suite('fertilizer', function(){
    // Data: 21-tier crafting skill; each tier = 1 same-tier Fishing catch + 1 Digging soil; fish-named.
    var fk = FF.CRAFTING_SKILLS.fertilizer;
    ok(fk && fk.recipes.length === FF.TIER_COUNT, 'Fertilizer is a 21-tier crafting skill');
    var r5 = FF.ALL_CRAFT_RECIPES['fertilizer_t5'];
    ok(r5 && r5.inputs['fishing_t5']===1 && r5.inputs['digging_t5']===1, 'fertilizer_t5 = 1 fish + 1 soil, same tier');
    ok(/ Fertilizer$/.test(r5.name), 'fertilizer named "<Fish> Fertilizer"');
    ok(FF.ALL_CRAFT_RECIPES['fertilizer_t0'] && FF.ALL_CRAFT_RECIPES['fertilizer_t20'], 't0 + t20 fertilizer recipes exist');
    ok(FF.CRAFT_SKILL_IDS.indexOf('fertilizer') !== -1 && FF.CRAFTING_TAB_SKILL_IDS.indexOf('fertilizer') !== -1, 'registered + appears in the Crafting tab');
    ok(FF.CRAFT_PHYSIQUE.fertilizer && FF.FAMILIAR_DATA.fertilizer, 'has a physique table + a familiar');

    // Mechanic: fertilize a growing crop with a matching-tier Fertilizer -> it yields double.
    var S = FF._state, grid = S.estate.grid, pm = FF.farmPlotMap('personal');
    var cells = [];
    for(var x=0; x<grid.length && cells.length<2; x++){ if(!grid[x]) continue; for(var y=0; y<grid[x].length && cells.length<2; y++){ if(grid[x][y]) cells.push([x,y]); } }
    var savedTiers = cells.map(function(c){ return grid[c[0]][c[1]].fieldTier; });
    var savedPlots = {}; Object.keys(pm).forEach(function(k){ savedPlots[k]=pm[k]; delete pm[k]; });
    var savedFert = S.inventory.fertilizer_t5||0, savedCrop = S.inventory.farming_t5||0;

    grid[cells[0][0]][cells[0][1]].fieldTier = 5;
    grid[cells[1][0]][cells[1][1]].fieldTier = 5;
    var k0 = cells[0][0]+','+cells[0][1], k1 = cells[1][0]+','+cells[1][1];
    pm[k0] = { cropType:'fiber', tierIndex:5, plantedAt:Date.now(), readyAt:Date.now()+9e8 };
    pm[k1] = { cropType:'fiber', tierIndex:5, plantedAt:Date.now(), readyAt:Date.now()+9e8 };

    S.inventory.fertilizer_t5 = 0;
    ok(!FF.fertilizePlot('personal', k0), 'no fertilizer in stock -> cannot fertilize');
    eq(FF.farmingFertilizableCount(), 0, 'nothing fertilizable without stock');
    // One t5 fertilizer: only one of the two t5 crops can be doubled.
    S.inventory.fertilizer_t5 = 1;
    eq(FF.farmingFertilizableCount(), 1, 'one fertilizer -> one candidate');
    eq(FF.farmingFertilizeAll(false), 1, 'fertilize-all fertilizes exactly one');
    eq(S.inventory.fertilizer_t5, 0, 'the fertilizer was consumed');
    var fertKey = pm[k0].fertilized ? k0 : k1, plainKey = fertKey===k0 ? k1 : k0;
    ok(pm[fertKey].fertilized && !pm[plainKey].fertilized, 'exactly one plot is fertilized');

    // Ripen + harvest: fertilized plot yields 10 (base 5 doubled), the other yields the base 5.
    pm[k0].readyAt = pm[k1].readyAt = Date.now()-1;
    S.inventory.farming_t5 = 0;
    FF.harvestPlot('personal', fertKey);
    eq(S.inventory.farming_t5, 10, 'fertilized crop yields 10 (base 5 x2)');
    FF.harvestPlot('personal', plainKey);
    eq(S.inventory.farming_t5, 15, 'plain crop yields the base 5 (total 15)');

    // restore
    Object.keys(pm).forEach(function(k){ delete pm[k]; });
    Object.keys(savedPlots).forEach(function(k){ pm[k]=savedPlots[k]; });
    cells.forEach(function(c,i){ grid[c[0]][c[1]].fieldTier = savedTiers[i]; });
    S.inventory.fertilizer_t5 = savedFert; S.inventory.farming_t5 = savedCrop;
  });

  // ---- Harvesting a crop returns a seed of that crop 75% of the time -----------------------------
  suite('farming: harvest seed drop', function(){
    eq(FF.HARVEST_SEED_DROP_CHANCE, 0.75, 'seed drop chance is 75%');
    // crop (type + tier) -> its seed id, across all three crop lines; unknown -> null (no phantom seed).
    eq(FF.cropSeedId('fiber', 5), 'seed_t5', 'fiber crop -> seed_t');
    eq(FF.cropSeedId('grain', 3), 'grainseed_t3', 'grain crop -> grainseed_t');
    eq(FF.cropSeedId('herb', 7), 'herbseed_t7', 'herb crop -> herbseed_t');
    eq(FF.cropSeedId('fiber', 999), null, 'out-of-range tier -> null');
    // Herbs are UNIFIED: gathered (Herbalism) and farmed (herb crop) both yield herbalism_t<i>, so a single
    // "Chamomile" works in both Alchemy and Cooking (fixes the "have chamomile but recipe says none" report).
    eq(FF.seedInfo('herbseed_t0').crop.id, 'herbalism_t0', 'farming an herb yields the gather item (herbalism_t0), not a separate herb_t0');
    ok(!FF.ALL_SELLABLE['herb_t0'], 'the duplicate farmed-herb item (herb_t0) no longer exists');
    ok(FF.ALL_CRAFT_RECIPES['cooking_t0'].inputs['herbalism_t0'] && !FF.ALL_CRAFT_RECIPES['cooking_t0'].inputs['herb_t0'], 'a Meal consumes the unified herbalism_t herb, not herb_t');
    // Statistical: harvest a ripe t5 fiber plot many times; ~75% of harvests return a seed_t5.
    var S = FF._state, grid = S.estate.grid, pm = FF.farmPlotMap('personal');
    var cell=null; for(var x=0;x<grid.length && !cell;x++){ if(!grid[x]) continue; for(var y=0;y<grid[x].length && !cell;y++){ if(grid[x][y]) cell=[x,y]; } }
    ok(cell, 'found an estate cell to farm');
    var key = cell[0]+','+cell[1];
    var savedTier = grid[cell[0]][cell[1]].fieldTier, savedPlot = pm[key];
    var savedSeed = S.inventory.seed_t5||0, savedCrop = S.inventory.farming_t5||0;
    grid[cell[0]][cell[1]].fieldTier = 5;
    var N=600, seeds=0;
    for(var i=0;i<N;i++){
      S.inventory.seed_t5 = 0;
      pm[key] = { cropType:'fiber', tierIndex:5, plantedAt:Date.now(), readyAt:Date.now()-1 };
      FF.harvestPlot('personal', key, true);
      if((S.inventory.seed_t5||0) > 0) seeds++;
    }
    var rate = seeds/N;
    ok(rate > 0.65 && rate < 0.85, 'harvest returns a seed ~75% of the time (got '+rate.toFixed(3)+')');
    delete pm[key]; if(savedPlot) pm[key]=savedPlot;
    grid[cell[0]][cell[1]].fieldTier = savedTier;
    S.inventory.seed_t5 = savedSeed; S.inventory.farming_t5 = savedCrop;
  });

  // ---- Cancel a growing crop (frees the plot; the seed is forfeit) -----------------------------
  suite('farming: cancel a growing crop', function(){
    var pm = FF.farmPlotMap('personal');
    var savedCrop = FF._state.inventory.farming_t2 || 0, savedSeed = FF._state.inventory.seed_t2 || 0;
    pm['7,7'] = { cropType:'fiber', tierIndex:2, plantedAt:Date.now(), readyAt:Date.now()+999999 };
    ok(pm['7,7'] && pm['7,7'].cropType, 'crop is growing before cancel');
    ok(FF.cancelCropAt('personal', '7,7') === true, 'cancel reports success');
    ok(!pm['7,7'], 'the plot is empty after cancelling');
    // No refund: cancelling does not return the crop or the seed to inventory.
    eq(FF._state.inventory.farming_t2 || 0, savedCrop, 'no crop is granted by cancelling');
    eq(FF._state.inventory.seed_t2 || 0, savedSeed, 'no seed is refunded by cancelling');
    // Cancelling an empty plot is a safe no-op.
    ok(FF.cancelCropAt('personal', '8,8') === false, 'cancelling an empty plot does nothing');
  });

  // ---- Critter Cache: one of each seed type + Botany/Herbalism drop it at 5% base --------------
  suite('critter cache: all three seed types', function(){
    var S = FF._state;
    function seedTotals(){
      var f=0,g=0,h=0;
      for(var i=0;i<21;i++){ f+=S.inventory['seed_t'+i]||0; g+=S.inventory['grainseed_t'+i]||0; h+=S.inventory['herbseed_t'+i]||0; }
      return {f:f,g:g,h:h};
    }
    var before = seedTotals();
    S.inventory.critter_cache = (S.inventory.critter_cache||0) + 50;
    FF.openCritterCaches(50, true); // silent
    var after = seedTotals();
    eq(after.f - before.f, 50, 'each cache drops exactly one Fiber seed');
    eq(after.g - before.g, 50, 'each cache drops exactly one Grain seed');
    eq(after.h - before.h, 50, 'each cache drops exactly one Herb seed');
    eq(S.inventory.critter_cache || 0, 0, 'all 50 caches were consumed');
    // Grain has one fewer tier than Fiber/Herb -- caches must never mint a nonexistent 'grainseed_t20'.
    ok(!S.inventory.grainseed_t20, 'caches never grant the out-of-range grainseed_t20');
    ok(Object.keys(S.inventory).filter(function(id){ return id.indexOf('grainseed_t')===0 && S.inventory[id]>0; })
      .every(function(id){ return !!FF.ALL_SELLABLE[id]; }), 'every granted Grain seed resolves to a real named item');
    // Base drop chance is 5% (Forestry, Botany, Herbalism & Foraging share critterCacheChance).
    eq(FF.BASE_NEST_CHANCE, 0.05, 'critter cache base chance is 5%');
    // Herbalism & Foraging traded raw seed side-drops for the Critter Cache; Botany still drops raw seeds.
    ['forestry','botany','herbalism','foraging'].forEach(function(sk){ ok(FF.CRITTER_CACHE_SKILLS.indexOf(sk) !== -1, sk+' drops Critter Caches'); });
    eq(FF.SEED_DROP_SKILLS.indexOf('foraging'), -1, 'Foraging no longer drops raw seeds');
    eq(FF.SEED_DROP_SKILLS.indexOf('herbalism'), -1, 'Herbalism no longer drops raw seeds');
    ok(FF.SEED_DROP_SKILLS.indexOf('botany') !== -1, 'Botany still drops raw seeds directly');
  });

  // ---- Cache seed tier distribution: skewed low, but high tiers actually attainable ----
  suite('critter cache: seed tier distribution reaches the high tiers', function(){
    var N = FF.TIER_COUNT, b = FF.CACHE_SEED_TIER_DECAY;
    ok(b > 0.65, 'the per-tier falloff is gentler than the old 0.65 (higher tiers more frequent)');
    // Closed-form probability per tier from the decay base (matches pickWeightedFarmingTier's weights).
    var w = [], total = 0; for(var i=0;i<N;i++){ w[i] = Math.pow(b,i); total += w[i]; }
    function p(i){ return w[i]/total; }
    ok(p(N-1) > 0.012 && p(N-1) < 0.018, 't20 is tuned to about 1.5% per seed');
    var pHigh = 0; for(var j=15;j<N;j++) pHigh += p(j);
    ok(pHigh > 0.08, 't15+ is common (~11.6% per seed) — no longer effectively zero');
    ok(p(0) > p(N-1), 'still skewed toward the low tiers (t0 far more likely than t20)');
    ok(p(0) > p(5) && p(5) > p(15), 'the weighting is monotonically skewed toward lower tiers');
    // The roll only ever returns a valid tier index, and (statistically) reaches the top tier.
    var allValid = true, sawHigh = false;
    for(var k=0;k<4000;k++){ var t = FF.pickWeightedFarmingTier(); if(!(t>=0 && t<N && t===(t|0))) allValid=false; if(t>=15) sawHigh = true; }
    ok(allValid, 'the roll always returns a valid tier index');
    ok(sawHigh, 'sampling actually turns up t15+ seeds');
    // Passing a line's own tier count caps the roll -- Grain (20 tiers) must never roll t20.
    var grainMax = -1; for(var gk=0;gk<4000;gk++){ var gt = FF.pickWeightedFarmingTier(FF.GRAIN_TIER_COUNT); if(gt > grainMax) grainMax = gt; }
    ok(grainMax === FF.GRAIN_TIER_COUNT - 1, 'grain rolls span its own tiers (top index is GRAIN_TIER_COUNT-1, never 20)');
  });

  // ---- Cross-skill physiques: 20 new physiques trained by one skill, feeding another --------------
  suite('cross-skill physiques', function(){
    var NEW = ['anglersEye','prospectorsNose','huntsman','sylvanBond','quartermaster','masterwork','diligence','weaponsmithsEdge','armorersTemper','greenThumb','composter','apothecarysHand','demolitionist','runicAttunement','wardersFocus','zealotry','oblation','fieldRations','menagerist','merchantsSavvy'];
    NEW.forEach(function(id){
      var p = FF.PHYSIQUE_SKILL_MAP[id];
      ok(p && p.name && p.desc && p.levels && p.affects, id+' is a fully-described physique');
      ok(!p.element, id+' is a normal physique (not an elemental attunement)');
    });
    // XP feeds attach each physique to the skills that train it.
    function feeds(list, id){ return !!list && list.some(function(pr){ return pr[0]===id; }); }
    ok(feeds(FF.GATHER_PHYSIQUE.fishing,'anglersEye'), 'Fishing trains Angler\'s Eye');
    ok(feeds(FF.GATHER_PHYSIQUE.mining,'prospectorsNose'), 'Mining trains Prospector\'s Nose');
    ok(feeds(FF.GATHER_PHYSIQUE.butchering,'huntsman'), 'Butchering trains Huntsman');
    ok(feeds(FF.GATHER_PHYSIQUE.forestry,'sylvanBond'), 'Forestry trains Sylvan Bond');
    ok(feeds(FF.CRAFT_PHYSIQUE.alchemy,'apothecarysHand'), 'Alchemy trains Apothecary\'s Hand');
    ok(feeds(FF.CRAFT_PHYSIQUE.fertilizer,'composter'), 'Fertilizer trains Composter');
    ok(feeds(FF.CRAFT_PHYSIQUE.weaponsmithing,'weaponsmithsEdge'), 'Weaponsmithing trains Weaponsmith\'s Edge');
    ok(feeds(FF.CRAFT_PHYSIQUE.armorsmithing,'armorersTemper'), 'Armorsmithing trains Armorer\'s Temper');
    ok(feeds(FF.CRAFT_PHYSIQUE.inscription,'wardersFocus'), 'Inscription trains Warder\'s Focus');
    ok(feeds(FF.CRAFT_PHYSIQUE.gastronomy,'fieldRations'), 'Gastronomy trains Field Rations');
    ok(feeds(FF.FARMING_PHYSIQUE,'greenThumb'), 'Farming trains Green Thumb');
    // Quartermaster + Diligence feed EVERY craft. Masterwork is NOT bundled into any craft's physique list —
    // it now trains only when a craft yields rare+ equipment (see the 'masterwork physique: rare+ only' suite).
    ok(feeds(FF.CRAFT_PHYSIQUE.cooking,'quartermaster') && feeds(FF.CRAFT_PHYSIQUE.cooking,'diligence'), 'all crafts train Quartermaster + Diligence');
    ok(!feeds(FF.CRAFT_PHYSIQUE.weaponsmithing,'masterwork') && !feeds(FF.CRAFT_PHYSIQUE.cooking,'masterwork'), 'Masterwork is no longer bundled into any per-craft physique list');
    // Logic trains ONLY from Refining skills (metallurgy/tanning/...), not cooking/outfitting/construction.
    ok(feeds(FF.CRAFT_PHYSIQUE.metallurgy,'logic') && feeds(FF.CRAFT_PHYSIQUE.tanning,'logic')
       && !feeds(FF.CRAFT_PHYSIQUE.cooking,'logic') && !feeds(FF.CRAFT_PHYSIQUE.weaponsmithing,'logic') && !feeds(FF.CRAFT_PHYSIQUE.carpentry,'logic'),
       'only refining crafts train Logic');

    // Effect scaling: at Lv100 each bonus reaches its cap; helpers read live state.physique.
    var S = FF._state, saved = {}, savedFaith = S.faith;
    NEW.forEach(function(id){ saved[id] = S.physique[id]; S.physique[id] = FF.xpFloorForLevel(100); });
    ok(Math.abs(FF.anglersEyeTreasureBonus() - 0.15) < 1e-6, 'Angler\'s Eye +15% treasure at Lv100');
    ok(Math.abs(FF.merchantSellMult() - 1.15) < 1e-6, 'Merchant\'s Savvy +15% sell at Lv100');
    ok(Math.abs(FF.merchantTaxMult() - 0.50) < 1e-6, 'Merchant\'s Savvy halves Market tax at Lv100');
    ok(Math.abs(FF.weaponsmithEdgeMult() - 1.15) < 1e-6, 'Weaponsmith\'s Edge +15% damage at Lv100');
    ok(Math.abs(FF.armorerTemperMult() - 1.15) < 1e-6, 'Armorer\'s Temper +15% armour at Lv100');
    ok(Math.abs(FF.runicAttunementMult() - 1.20) < 1e-6, 'Runic Attunement +20% wand/scepter at Lv100');
    ok(Math.abs(FF.menageristPotencyMult() - 1.25) < 1e-6, 'Menagerist +25% familiar potency at Lv100');
    ok(Math.abs(FF.diligenceCraftXpMult() - 1.15) < 1e-6, 'Diligence +15% craft XP at Lv100');
    eq(FF.apothecaryExtraCharges(), 5, 'Apothecary\'s Hand +5 potion charges at Lv100');
    ok(Math.abs(FF.demolitionistMult() - 1.30) < 1e-6, 'Demolitionist +30% bomb/flash at Lv100');
    ok(Math.abs(FF.wardersFocusReflectBonus() - 0.15) < 1e-6, 'Warder\'s Focus +15% reflect at Lv100');
    ok(Math.abs(FF.greenThumbGrowthMult() - 0.85) < 1e-6, 'Green Thumb -15% growth time at Lv100');
    ok(Math.abs(FF.huntsmanOutputBonus() - 0.12) < 1e-6, 'Huntsman +12% butcher output at Lv100');
    ok(Math.abs(FF.masterworkRarityBonus('rare') - 0.05) < 1e-6, 'Masterwork +5% rare odds at Lv100 (5x base)');
    ok(Math.abs(FF.masterworkRarityBonus('supreme') - 0.005) < 1e-6, 'Masterwork +0.5% supreme odds at Lv100 (5x base)');
    ok(Math.abs(FF.masterworkRarityBonus('fantastic') - 0.00005) < 1e-9, 'Masterwork +0.005% fantastic odds at Lv100 (5x base)');
    ok(FF.masterworkRarityBonus('rare') > 0 && FF.masterworkRarityBonus('normal') === 0, 'Masterwork bonus is per-rarity (nothing for normal)');
    ok(Math.abs(FF.sylvanBondCacheBonus() - 0.05) < 1e-6, 'Sylvan Bond +5% cache at Lv100');
    ok(Math.abs(FF.physBonus('anglersEye', 0.3) - 0.3) < 1e-6, 'physBonus reaches its cap at Lv100');
    // Zealotry scales with current Faith fraction.
    S.faith = 1e9; // clamp to full-faith fraction
    ok(Math.abs(FF.zealotryDmgMult() - 1.20) < 1e-6, 'Zealotry +20% damage at full Faith (Lv100)');
    S.faith = 0;
    ok(Math.abs(FF.zealotryDmgMult() - 1) < 1e-6, 'Zealotry neutral at 0 Faith');
    // restore
    NEW.forEach(function(id){ S.physique[id] = saved[id]; });
    S.faith = savedFaith;
  });

  // ---- Rarity chance: ONE unified formula across every craft (ordinary / relic / masterwork) ----
  // Each rarity = its static base (Rare 1% / Supreme 0.1% / Fantastic 0.001% since the v0.0.96.8 cut) lifted linearly by up to
  // +5x-base each from a max-tier Faith activity, the Lv100 Masterwork physique, and the server Rarity Bonus.
  suite('rarity chance: unified bases + 5x-base caps', function(){
    var S = FF._state;
    var sv = { rar:FF._serverBuff.rarityUntil, fa:S.faithActivity, mw:S.physique.masterwork, faith:S.faith };
    try {
      S.faithActivity = { type:null, tier:0 }; FF._serverBuff.rarityUntil = 0; S.physique.masterwork = 0; S.faith = 0;
      // Static bases.
      near(FF.rareCraftChance(), 0.01, 'base Rare is 1%', 1e-9);
      near(FF.supremeCraftChance(), 0.001, 'base Supreme is 0.1%', 1e-9);
      near(FF.fantasticCraftChance(), 0.00001, 'base Fantastic is 0.001% (10x rarer since v0.0.96.8)', 1e-12);
      // Mastery (Lv100) adds 5x base to each.
      S.physique.masterwork = FF.xpFloorForLevel(100);
      near(FF.rareCraftChance(), 0.01 + 0.05, 'Lv100 Mastery adds +5% rare', 1e-9);
      near(FF.supremeCraftChance(), 0.001 + 0.005, 'Lv100 Mastery adds +0.5% supreme', 1e-9);
      near(FF.fantasticCraftChance(), 0.00001 + 0.00005, 'Lv100 Mastery adds +0.005% fantastic', 1e-12);
      S.physique.masterwork = 0;
      // Server Rarity Bonus adds 5x base to each.
      FF._serverBuff.rarityUntil = Date.now() + 60000;
      near(FF.rareCraftChance(), 0.01 + 0.05, 'server buff adds +5% rare', 1e-9);
      near(FF.supremeCraftChance(), 0.001 + 0.005, 'server buff adds +0.5% supreme', 1e-9);
      near(FF.fantasticCraftChance(), 0.00001 + 0.00005, 'server buff adds +0.005% fantastic', 1e-12);
      FF._serverBuff.rarityUntil = 0;
      // Max-tier Faith activity adds 5x base to its rarity.
      S.faith = 1e9;
      S.faithActivity = { type:'devotion', tier:20 }; near(FF.faithRarityBonus('devotion'), 0.05, 'max Devotion caps Rare bonus at +5%', 1e-9);
      S.faithActivity = { type:'blessing', tier:20 }; near(FF.faithRarityBonus('blessing'), 0.005, 'max Blessing caps Supreme bonus at +0.5%', 1e-9);
      S.faithActivity = { type:'miracle', tier:20 }; near(FF.faithRarityBonus('miracle'), 0.00005, 'max Miracle caps Fantastic bonus at +0.005%', 1e-12);
      // Relics read the SAME unified chances (were previously base + Faith only, and no Mastery/server buff).
      S.faithActivity = { type:null, tier:0 };
      var rc = FF.relicRarityChances(S);
      near(rc.rare, FF.rareCraftChance(), 'relics share the Rare chance', 1e-12);
      near(rc.supreme, FF.supremeCraftChance(), 'relics share the Supreme chance', 1e-12);
      near(rc.fantastic, FF.fantasticCraftChance(), 'relics share the Fantastic chance', 1e-12);
    } finally { FF._serverBuff.rarityUntil = sv.rar; S.faithActivity = sv.fa; S.physique.masterwork = sv.mw; S.faith = sv.faith; }
  });

  // ---- Masterwork forge rarity: now the SAME unified odds as any craft (1% / 0.1% / 0.01% base) ----
  suite('masterwork forge rarity odds', function(){
    var S = FF._state;
    var sv = { mw:S.physique.masterwork, rand:Math.random, rar:FF._serverBuff.rarityUntil, fa:S.faithActivity, faith:S.faith };
    try {
      FF._serverBuff.rarityUntil = 0; S.faithActivity = { type:null, tier:0 }; S.faith = 0; S.physique.masterwork = 0; // isolate: base only
      // Bands (base): Fantastic [0,0.00001), Supreme [0.00001,0.00101), Rare [0.00101,0.01101), Normal [0.01101,1).
      Math.random = function(){ return 0.000005; }; eq(FF.rollMastercraftRarity(), 'fantastic', 'roll < 0.00001 -> Fantastic (unified 0.001% base)');
      Math.random = function(){ return 0.0005; };  eq(FF.rollMastercraftRarity(), 'supreme',   'roll in [0.00001,0.00101) -> Supreme (0.1% base)');
      Math.random = function(){ return 0.005; };   eq(FF.rollMastercraftRarity(), 'rare',      'roll in [0.00101,0.01101) -> Rare (1% base)');
      Math.random = function(){ return 0.5; };     eq(FF.rollMastercraftRarity(), 'normal',    'roll 0.5 -> Normal');
    } finally { Math.random = sv.rand; S.physique.masterwork = sv.mw; FF._serverBuff.rarityUntil = sv.rar; S.faithActivity = sv.fa; S.faith = sv.faith; }
  });

  // ---- Resources reorg: Gathering / Refining / Cooking / Construction split + 70% gather success -----
  suite('resources reorg', function(){
    // Cooking = food & drink; Refining = the rest of the old Crafting tab; both partition it exactly.
    var COOK = FF.COOKING_SKILL_IDS, REF = FF.REFINING_SKILL_IDS, TAB = FF.CRAFTING_TAB_SKILL_IDS;
    ['roasting','cooking','baking','brewing','mixology','confectionery','dairy','gastronomy'].forEach(function(id){
      ok(COOK.indexOf(id) !== -1, id+' is a Cooking skill');
    });
    ok(REF.indexOf('metallurgy') !== -1 && REF.indexOf('tanning') !== -1 && REF.indexOf('alchemy') !== -1, 'Refining holds the material-processing crafts');
    ok(COOK.every(function(id){ return REF.indexOf(id) === -1; }), 'Cooking and Refining are disjoint');
    eq(COOK.length + REF.length, TAB.length, 'Cooking + Refining exactly partition the old Crafting tab');
    // Butchering left Gathering and leads Refining.
    ok(FF.GATHERING_TAB_SKILL_IDS.indexOf('butchering') === -1, 'Gathering no longer lists Butchering');
    ok(FF.GATHER_SKILL_IDS.indexOf('butchering') !== -1, 'Butchering is still a (gather-backed) skill');
    eq(FF.REFINING_TAB_SKILL_IDS[0], 'butchering', 'Butchering leads the Refining tab');

    // Every gathering skill now has a 70% base main-output chance (no equipped tool).
    eq(FF.BASE_GATHER_MAIN_CHANCE, 0.70, 'base gather success is 70%');
    var S = FF._state, savedTools = S.gatherTools;
    S.gatherTools = {}; // no tools -> pure base
    ['forestry','herbalism','botany','foraging','beekeeping','essence','tapping','spelunking'].forEach(function(sk){
      ok(Math.abs(FF.genericGatherMainChance(S, sk) - 0.70) < 1e-9, sk+' base success = 70%');
    });
    S.gatherTools = savedTools;

    // Skills-tab progress helper returns a 0..100 percentage.
    var p = FF.anySkillProgress('mining');
    ok(typeof p === 'number' && p >= 0 && p <= 100, 'anySkillProgress is a 0-100 percentage');
  });

  // ---- Gathering tools lend NO success rate (owner ruling, v0.0.77.15) ------------------------------
  // The tier-only bonus curve (gatherToolSuccessBonus, max +9.375%) is DELETED, not merely undisplayed: it
  // was an invisible mechanic no gather tool's item card ever claimed (their data carries speedBonus only),
  // and the owner ruled that tools speed the work without changing the odds. These pin the flatness --
  // any tool, any tier, any rarity, the chance is the base constant.
  suite('gather success is flat: tools and rarity change nothing', function(){
    ok(!('gatherToolSuccessBonus' in FF) && !('GATHER_TOOL_SUCCESS_MAX' in FF),
       'the vestigial success curve is gone from the seam entirely');
    var S = FF._state, savedT = S.gatherTools, savedR = S.gatherToolRarities;
    try {
      S.gatherTools = {}; S.gatherToolRarities = {};
      eq(FF.miningMainChance(S), 0.70, 'mining with NO tool is the flat 70% base');
      S.gatherTools.mining = 21; S.gatherToolRarities.mining = 'fantastic';
      eq(FF.miningMainChance(S), 0.70, 'a top-tier Fantastic Pickaxe changes nothing');
      S.gatherTools.digging = 21;
      eq(FF.diggingMainChance(S), 0.70, 'digging is the flat 70% base at any tool');
      S.gatherTools.fishing = 21;
      eq(FF.fishingCatchChance(S), 0.50, 'fishing is the flat 50% base at any tool');
      S.gatherTools.forestry = 21;
      eq(FF.genericGatherMainChance(S, 'forestry'), 0.70, 'forestry (generic gathers) is the flat 70% base at any tool');
      // Butchering's Cleaver is the deliberate exception: it raises OUTPUT chance like a craft tool, and a
      // better/rarer Cleaver must keep doing so -- deleting the gather curve must not have caught it.
      S.gatherTools.butchering = 21; S.gatherToolRarities.butchering = 'fantastic';
      var withCleaver = FF.butcherOutputChance(S, 'handStrength');
      S.gatherTools.butchering = 0;
      ok(withCleaver > FF.butcherOutputChance(S, 'handStrength'),
         'the Cleaver still raises butcher output chance (the by-design exception)');
    } finally {
      S.gatherTools = savedT; S.gatherToolRarities = savedR;
    }
  });

  // ---- Guild estate: leader-set demolition permission (who may remove buildings / pavement) ----------
  suite('guild demolition permission', function(){
    eq(FF.GUILD_RANK_ORDER.leader, 3, 'rank order leader(3) > officer(2) > member(1)');
    var GS = FF.guildState, GE = FF.guildEstate;
    var savedRank = GS.myRank, savedRole = GE.destroyRole;
    GE.destroyRole = 'officer';
    GS.myRank = 'member';  ok(!FF.canDestroyGuildEstate(), 'member blocked when set to Officers+');
    GS.myRank = 'officer'; ok(FF.canDestroyGuildEstate(), 'officer allowed when set to Officers+');
    GS.myRank = 'leader';  ok(FF.canDestroyGuildEstate(), 'leader is always allowed');
    GE.destroyRole = 'leader';
    GS.myRank = 'officer'; ok(!FF.canDestroyGuildEstate(), 'officer blocked when set to Leader only');
    GE.destroyRole = 'member';
    GS.myRank = 'member';  ok(FF.canDestroyGuildEstate(), 'any member allowed when set to Any member');
    GE.destroyRole = undefined; eq(FF.guildDestroyMinRole(), 'officer', 'defaults to Officers+');
    GS.myRank = savedRank; GE.destroyRole = savedRole;
  });

  // ---- Persisted supreme/fantastic craft blasts reload into global chat as system messages ----------
  suite('persistent craft blasts', function(){
    var sup = FF.chronicleCraftToSystemMsg({ id:7, username:'Nyx', body:'Supreme Iron Sword', created_at:'2026-07-10T00:00:00Z' });
    ok(sup && sup.system === true && sup.rarity === 'supreme', 'a Supreme craft row -> a system message');
    ok(sup.id === 'sys-7' && sup.username === null && /Nyx forged a Supreme Iron Sword!/.test(sup.body), 'system message carries the forger + item');
    var fan = FF.chronicleCraftToSystemMsg({ id:8, username:'Vex', body:'Fantastic Dragon Bow', created_at:'2026-07-10T00:00:00Z' });
    ok(fan && fan.rarity === 'fantastic', 'a Fantastic craft row -> a fantastic system message');
    ok(FF.chronicleCraftToSystemMsg({ id:9, username:'A', body:'Rare Copper Ring', created_at:'x' }) === null, 'Rare/normal crafts are not blasted');
    ok(FF.chronicleCraftToSystemMsg({ id:10, username:'A', body:'Iron Sword', created_at:'x' }) === null, 'a plain craft is not blasted');
  });

  // ---- Persisted server-wide IMPROVEMENT (enhance) blasts reload into chat too ----------------------
  suite('persistent improvement blasts', function(){
    // Enhance body carries the "+N" level; +15 or higher reads Fantastic, otherwise Supreme.
    eq(FF.enhanceBodyRarity('Willow Fire Wand to +12'), 'supreme', '+12 improvement -> supreme tint');
    eq(FF.enhanceBodyRarity('Dragon Bow to +15'), 'fantastic', '+15 improvement -> fantastic tint');
    eq(FF.enhanceBodyRarity('Sword to +20'), 'fantastic', '+20 improvement -> fantastic tint');
    var e = FF.chronicleEnhanceToSystemMsg({ id:42, username:'Nyx', body:'Willow Fire Wand to +12', created_at:'2026-07-10T00:00:00Z' });
    ok(e && e.system === true && e.rarity === 'supreme', 'an enhance row -> a persistent system message');
    ok(e.id === 'sys-42' && e.username === null && /Nyx enhanced their Willow Fire Wand to \+12!/.test(e.body), 'improvement blast carries the enhancer + item + level');
    ok(FF.chronicleEnhanceToSystemMsg({ id:43, username:'A', body:'', created_at:'x' }) === null, 'an empty enhance body -> no blast');
    // The kind-dispatcher routes each chronicle row to the right synthesizer.
    ok(/enhanced their/.test(FF.chronicleRowToSystemMsg({ kind:'enhance', id:1, username:'A', body:'X to +11', created_at:'x' }).body), 'row dispatcher handles enhance rows');
    ok(/forged a/.test(FF.chronicleRowToSystemMsg({ kind:'craft', id:2, username:'A', body:'Supreme Y', created_at:'x' }).body), 'row dispatcher handles craft rows');
    ok(FF.chronicleRowToSystemMsg({ kind:'level', id:3, username:'A', body:'Mining 50', created_at:'x' }) === null, 'non-blast chronicle kinds (level) produce no chat message');
    // Owner order (2026-08-05): only a MAXED (+15) enhance blasts. +11 to +14 trigger neither the
    // in-game announcement nor the Discord feed post; the +12 fixtures above stay because HISTORICAL
    // pre-rule rows still live in the chronicle and must keep rendering. The discord_feed edge
    // function mirrors the bar server-side (ENHANCE_MIN = 15), so a stale client cannot post below it.
    eq(FF.ENHANCE_ANNOUNCE_MIN, 15, 'the in-game enhance blast fires only at +15');
    eq(FF.DISCORD_ENHANCE_MIN, 15, 'the Discord enhance blast fires only at +15');
  });

  // ---- Mortal-death blasts (v0.0.97.2): chronicle body + persisted reload + chat wiring --------------
  suite('mortal death blasts', function(){
    // The shared broadcast body: self-contained after the fallen player's name, carries the slayer
    // and the Total Level, and stays well inside chronicleBroadcast's 120-char truncation so the
    // Total Level can never be the part that falls off.
    var body = FF.mortalDeathBody({ name:'Archdemon' });
    ok(/^has fallen! Slain by the Archdemon at Total Level [\d,]+\.$/.test(body), 'body names the slayer + Total Level');
    ok(body.length <= 120, 'body fits the chronicle 120-char limit (' + body.length + ' chars)');
    // The party-dungeon death path calls mortalDeath(null): no single foe struck the blow.
    ok(/Slain by the Dungeon Depths/.test(FF.mortalDeathBody(null)), 'a party-run death (null monster) is slain by the Dungeon Depths');
    // A LONG monster name still leaves the Total Level inside the truncation window.
    var longBody = FF.mortalDeathBody({ name:'Ancient Broodmother of the Sunken Necropolis Depths' });
    ok(longBody.length <= 120 && /Total Level [\d,]+\.$/.test(longBody), 'even a long slayer name keeps the Total Level inside 120 chars');
    // Persisted 'mortal_death' chronicle rows reload into global chat as fantastic system messages,
    // the same treatment supreme/fantastic crafts and +15 enhances get.
    var m = FF.chronicleMortalToSystemMsg({ id:9, username:'Nyx', body:'has fallen! Slain by the Rabbit at Total Level 42.', created_at:'2026-08-10T00:00:00Z' });
    ok(m && m.system === true && m.rarity === 'fantastic', 'a mortal_death row -> a fantastic system message');
    ok(m.id === 'sys-9' && m.username === null && /Nyx has fallen! Slain by the Rabbit at Total Level 42\./.test(m.body), 'blast carries the fallen player + slayer + Total Level');
    ok(FF.chronicleMortalToSystemMsg({ id:10, username:'A', body:'', created_at:'x' }) === null, 'an empty mortal_death body -> no blast');
    ok(/has fallen/.test(FF.chronicleRowToSystemMsg({ kind:'mortal_death', id:3, username:'A', body:'has fallen! Slain by the Rabbit at Total Level 42.', created_at:'x' }).body), 'row dispatcher handles mortal_death rows');
  });

  // ---- Top-bar tips & tricks ticker ------------------------------------------------------------------
  suite('tips ticker', function(){
    var T = FF.TICKER_TIPS;
    ok(Array.isArray(T) && T.length >= 20, 'there is a healthy list of tips (>= 20)');
    ok(T.every(function(t){ return typeof t === 'string' && t.length > 10; }), 'every tip is a non-trivial string');
    ok(T.some(function(t){ return /Multitasking/.test(t) && /craft slot/.test(t); }), 'includes the Multitasking craft-slot tip');
    ok(T.some(function(t){ return /Sand/.test(t) && /Archaeolog/.test(t); }), 'includes the Sand / Archaeology tip');
    ok(new Set(T).size === T.length, 'no duplicate tips');
    // Pre-alpha disclaimer: red, correct wording, and weighted well above any single tip.
    var d = FF.TICKER_DISCLAIMER;
    ok(/Active Development Pre-Alpha/.test(d) && /progress wipes/.test(d) && /feedback/.test(d), 'disclaimer carries the pre-alpha wording');
    ok(/color:\s*#ff6b6b/i.test(d), 'disclaimer is styled red');
    ok(FF.TICKER_DISCLAIMER_CHANCE > (1 / T.length), 'disclaimer appears far more often than any single tip');

    // ---- STALENESS. 125 tips describe mechanics, and a rework silently turns some of them into lies. Five
    // were wrong at the same time and nothing was watching. These assertions pin the claims that went stale,
    // so the next rework of the same system fails here instead of shipping a tip that misinforms players.
    var all = T.join(' \n ');
    // Apothecary crafts DRAUGHTS since v0.0.87.0; Weapon Coatings are retired (held stacks still work, but
    // no recipe makes one), and the poison line moved wholly to Alchemy.
    ok(!/Weapon Coating/i.test(all), 'no tip still claims Apothecary crafts Weapon Coatings');
    ok(T.some(function(t){ return /Mycology/.test(t) && /Draught/.test(t); }), 'a tip points Mycology at Draughts');
    // The 'enchant' POTION type was retired: Enchant Crystals are the Improvement tab's input, never a
    // Battle-tab consumable, so no tip may tell a player to ready one for damage.
    ok(!/Weapon Enchants/i.test(all), 'no tip still calls Enchant Crystals "Weapon Enchants"');
    ok(T.some(function(t){ return /Enchant Crystals/.test(t) && /Improvement/.test(t); }),
       'a tip sends Enchant Crystals to the Improvement tab');
    // The Firebomb stopped being flat damage in v0.0.87.1 (it is the opener) and the poison stopped being
    // described in "combat score" back in v0.0.68.0.
    ok(!/flat fire damage/i.test(all), 'no tip still calls the Firebomb flat fire damage');
    ok(!/combat score/i.test(all), 'no tip describes damage in the retired "combat score" unit');
    // A Staff DOES auto-attack: noAttack is never set true anywhere, so a tip asserting otherwise is false
    // whatever the balance decision turns out to be.
    ok(!/Staff<\/b> deals no damage/i.test(all) && !/Staff deals no damage/i.test(all),
       'no tip claims a Staff deals no damage (it auto-attacks; noAttack is never set)');

    // ---- The Ko-fi tip. Pinned two ways, because a tip that names a button is only useful while the button
    // is still called that: the tip must exist, and its wording must match the label kofiLinkHtml actually
    // renders. Rename the button and this fails instead of quietly sending players looking for nothing.
    var kofi = T.filter(function(t){ return /Ko-fi/.test(t); });
    ok(kofi.length >= 1, 'a tip points players at Ko-fi');
    // Reads the SHARED constant the button renders from. An earlier version of this passed the label into
    // kofiLinkHtml from the test itself, so it echoed back whatever the test said and renaming the real
    // button changed nothing -- caught by planting the rename and watching this pass.
    ok(kofi.some(function(t){ return t.indexOf(FF.KOFI_LABEL) !== -1; }),
       'the tip quotes the Ko-fi button label exactly as rendered (' + FF.KOFI_LABEL + ')');
    ok(FF.kofiLinkHtml(FF.KOFI_LABEL).indexOf(FF.KOFI_URL) !== -1, 'and the button links to that URL');
    ok(/^https:\/\/ko-fi\.com\//.test(FF.KOFI_URL), 'the Ko-fi URL is a real ko-fi.com link');

    // A sample of the other new claims, so a future rework of these systems trips here.
    ok(T.some(function(t){ return /Mortal guild/.test(t) && /no shared treasury/.test(t); }), 'the Mortal-guild treasury tip is present');
    ok(T.some(function(t){ return /Enchant before you Enhance/.test(t); }), 'the enchant-before-enhance ordering tip is present');
    ok(T.some(function(t){ return /Barrier Shards/.test(t) && /star/.test(t); }), 'the Barrier Shard source tip is present');
    ok(T.some(function(t){ return /Toxin/.test(t) && /own clock/.test(t); }), 'the clocked-Toxin tip is present');

    // ---- THE ESTATE SERIES (v0.0.90.0 through v0.0.94.0). Ten tips, each pinned to the number or rule it
    // states, because every one of these systems is young enough to be re-tuned. A tip that quotes a figure
    // is a promise, so the figures are read from the SHARED constants rather than retyped here: change the
    // constant and this fails instead of the ticker quietly lying to players.
    ok(T.some(function(t){ return /Curbs, Fences and Walls/.test(t) && /one minute per tier/.test(t) && /Architecture/.test(t); }),
       'a tip states the border build timer and the Architecture gate');
    // The three multipliers ARE 1/2/3, so the tip's "one/two/three minutes per tier" is checked against them.
    eq([FF.ESTATE_BORDER_TYPE_TIME_MULT.curb, FF.ESTATE_BORDER_TYPE_TIME_MULT.fence, FF.ESTATE_BORDER_TYPE_TIME_MULT.wall].join(','), '1,2,3',
       'and the multipliers it quotes are the ones the game uses');
    eq(FF.ESTATE_BORDER_MS_PER_TIER, 60000, 'the per-tier minute the tip quotes is a real minute');
    eq(FF.ESTATE_BORDER_GATE_SKILL, 'architecture', 'the skill the tip names is the skill that gates');
    ok(T.some(function(t){ return /<b>Curb<\/b>/.test(t) && /Aqueduct/.test(t) && /free/.test(t); }),
       'a tip explains that a Curb lines an Aqueduct link');
    ok(T.some(function(t){ return /fenced on all four borders/.test(t) && /15%/.test(t) && /weakest/.test(t); }),
       'a tip states the fence shelter: all four, and priced off the weakest');
    eq(Math.round(FF.FENCE_SHELTER_MAX_CUT * 100), 15, 'and the 15% it quotes is the real cap');
    ok(T.some(function(t){ return /Estate Appraisal/.test(t) && /20%/.test(t) && /dilutes/.test(t); }),
       'a tip states the Appraisal, its Peon effect, and that expanding dilutes it');
    eq(Math.round(FF.ESTATE_APPRAISAL_MAX_CUT * 100), 20, 'and the 20% it quotes is the real cap');
    ok(T.some(function(t){ return /Bunkhouse/.test(t) && /five Peons to ten/.test(t); }), 'a tip states the Bunkhouse Peon cap');
    eq(FF.PEON_MAX_SLOTS + FF.BUNKHOUSE_MAX, 10, 'and five Bunkhouses really do reach ten Peons');
    // The OLD cap tip said "up to five ... and five on the guild's" flat, which the Bunkhouse made false.
    ok(!T.some(function(t){ return /Run up to five on your Estate/.test(t); }), 'no tip still gives the flat five-Peon cap');
    ok(T.some(function(t){ return /Foreman's Office/.test(t) && /several neighbouring Workshops/.test(t); }),
       'a tip explains what a Foreman fixes for a crowded Cottage');
    ok(T.some(function(t){ return /Salvage Yards/.test(t) && /at or below/.test(t) && /five times/.test(t); }),
       'a tip states the Yard tier rule and the fantastic scrap multiple');
    eq(FF.SALVAGE_YIELD_BY_RANK[3] / FF.SALVAGE_YIELD_BY_RANK[0], 5, 'and a fantastic item really scraps for five times a normal one');
    ok(T.some(function(t){ return /Ley Font/.test(t) && /Bellows/.test(t) && /only the bill/.test(t); }),
       'a tip states the refund buildings and that they do not touch the odds');
    ok(T.some(function(t){ return /Apiary/.test(t) && /within one tile/.test(t) && /still one bonus/.test(t); }),
       'a tip states the Apiary aura and that hives do not stack');
    eq(FF.APIARY_YIELD_BONUS, 1, 'and the one crop it promises is the real figure');
    ok(T.some(function(t){ return /Aqueduct/.test(t) && /waterside/.test(t) && /Sun Terrace/.test(t); }),
       'a tip explains the Aqueduct as a waterside bank and the Sun Terrace as the hilltop fix');
  });

  // ---- Icon shape symbols exist (previously-blank Dairy/Ranching/Tanning/Weaving/etc. icons) ---------
  suite('icon shapes defined', function(){
    ['milk','cheese','churn','block','bottle','hide','spool','mug'].forEach(function(sh){
      ok(document.getElementById('shape-'+sh), 'shape-'+sh+' symbol is defined (icon renders, not blank)');
    });
  });

  // ---- Guild estate: assist a teammate's task ------------------------------------------
  // Guild estate jobs are SERVER-authoritative now (guild_estate_jobs table + RPCs). The lifecycle
  // (start/assist/complete/cancel) round-trips through Supabase, so it isn't unit-testable without a
  // backend; what stays client-side and testable is the read model -- guildJobFromServer's mapping,
  // guildJobByOwner's filtering, and that a blob (grid) hydrate no longer touches the job list.
  suite('guild estate jobs (server model): read model', function(){
    var ge = FF.guildEstate;
    var saved = { status:ge.status, jobs:ge.jobs, version:ge.version };
    ge.status = 'ready'; ge.version = 0;
    var NOW = Date.now();

    // guildJobFromServer flattens a server row into the flat client job shape, carrying owner + assist info.
    var row = { kind:'pave', x:3, y:4, owner:'alice', ownerName:'Alice',
      payload:{ paveTileId:'paving_t2' }, startAt:NOW-1000, readyAt:NOW+60000 };
    var mapped = FF.guildJobFromServer(row);
    eq(mapped.owner, 'alice', 'server row -> client job keeps the owner');
    eq(mapped.ownerName, 'Alice', 'server row -> client job keeps the owner name');
    eq(mapped.paveTileId, 'paving_t2', 'server payload is flattened onto the job (paveTileId)');
    eq(mapped.readyAt, NOW+60000, 'readyAt carries through as epoch ms');
    var arow = { kind:'assist', x:3, y:4, owner:'bob', ownerName:'Bob', payload:{}, assistOf:'alice', assistOfName:'Alice', startAt:NOW, readyAt:NOW+30000 };
    var amap = FF.guildJobFromServer(arow);
    eq(amap.assistOf, 'alice', 'an assist job maps assistOf');
    eq(amap.assistOfName, 'Alice', 'an assist job maps assistOfName');

    // guildJobByOwner returns a member's non-assist job (the assist row is excluded).
    ge.jobs = [ FF.guildJobFromServer(row), amap ];
    var byOwner = FF.guildJobByOwner('alice');
    ok(byOwner && byOwner.kind==='pave', "guildJobByOwner finds a member's non-assist job");
    ok(!FF.guildJobByOwner('bob'), 'guildJobByOwner excludes assist jobs');

    // A blob (grid) hydrate no longer carries jobs -- the server list is left intact across a grid sync.
    var before = ge.jobs.slice();
    FF.guildEstateHydrate({ grid:ge.grid, jobs:[{ owner:'zzz', kind:'clear', x:9, y:9, startAt:NOW, readyAt:NOW+1 }], expansionsPurchased:0, edgesX:ge.edgesX, edgesY:ge.edgesY }, 9);
    eq(ge.jobs.length, before.length, 'a grid hydrate does not replace the (server-owned) job list');
    ok(!ge.jobs.some(function(j){ return j.owner==='zzz'; }), "a blob's jobs field is ignored on hydrate");

    ge.status = saved.status; ge.jobs = saved.jobs; ge.version = saved.version;
  });

  // ---- Leaderboard covers every skill / proficiency / class / physique ------------------
  suite('leaderboard coverage', function(){
    // Union of every skill id the leaderboard can rank or show (drives both the "Rank by"
    // dropdown and the profile page).
    var grouped = {};
    FF.SKILL_GROUPS.forEach(function(g){ g.skills.forEach(function(sk){ grouped[sk] = true; }); });

    // Every main skill/proficiency/class is grouped, so newly-added content can never silently
    // drop off the board.
    // Every Class has a hand-crafted hero portrait (the leaderboard shows it per player, not a small icon).
    ok(FF.CLASS_PORTRAITS && FF.CLASS_PORTRAITS.none, 'the no-class portrait exists');
    FF.CLASS_SKILL_IDS.forEach(function(cid){
      var pt = FF.CLASS_PORTRAITS[cid];
      ok(typeof pt === 'string' && pt.indexOf('<svg') === 0, 'class ' + cid + ' has a hand-crafted portrait');
    });
    FF.ALL_MAIN_SKILL_IDS.forEach(function(id){ ok(grouped[id], 'leaderboard covers main skill: ' + id); });
    // Every physique too (body physiques + elemental attunements).
    FF.PHYSIQUE_SKILLS.forEach(function(p){ ok(grouped[p.id], 'leaderboard covers physique: ' + p.id); });

    // Spot-check the recently-added content specifically.
    ['scimitar','claw','treasureHunter','wands','staves','scepters','warding',
     'clotharmor','leatherarmor','chainmailarmor','platearmor',
     'fireAttunement','waterAttunement','earthAttunement','lightAttunement','darkAttunement']
      .forEach(function(id){ ok(grouped[id], 'newly-added content is on the leaderboard: ' + id); });

    // Everything ranked has a human-readable label (no raw ids leak into the UI).
    Object.keys(grouped).forEach(function(id){ ok(FF.SKILL_LABELS[id] && FF.SKILL_LABELS[id] !== id, 'labelled: ' + id); });

    // There is a dedicated Physique group.
    ok(FF.SKILL_GROUPS.some(function(g){ return g.label === 'Physique'; }), 'a Physique group exists');

    // Profile stats fold physiques into the skills map AND count them toward total_level, so the
    // server's `total_level == sum(skills)` validation passes (submit_profile rejects any mismatch).
    var s = FF._state;
    var physId = FF.PHYSIQUE_SKILLS[0].id, mainId = 'mining';
    var snap = { phys:s.physique[physId], xp:s.xp[mainId] };
    function sumSkills(st){ return Object.keys(st.skills).reduce(function(a,k){ return a + st.skills[k]; }, 0); }
    s.physique[physId] = 0; s.xp[mainId] = 0;
    var base = FF.computeProfileStats();
    ok(base.skills[physId] !== undefined, 'physiques appear in the profile skills map');
    eq(base.total_level, sumSkills(base), 'total_level equals the sum of every submitted skill (server invariant)');
    // Guard the server's MAX_SKILLS cap (submit_profile rejects the WHOLE submission if the skill count
    // exceeds it -- which silently froze the entire leaderboard once the set outgrew the old cap of 160).
    // The submitted set is ~172 today; keep it well under the server's 400 so adding classes/skills can't
    // break profile writes without this failing first as a heads-up to bump the server cap.
    var submittedSkillCount = Object.keys(base.skills).length;
    ok(submittedSkillCount < 350, 'submitted leaderboard skill count (' + submittedSkillCount + ') stays well under the server MAX_SKILLS cap (400)');
    s.physique[physId] = FF.xpFloorForLevel(31); // ~Lv 31
    var afterPhys = FF.computeProfileStats();
    ok(afterPhys.skills[physId] > 0, 'physique level shows in the profile');
    ok(afterPhys.total_level > base.total_level, 'physiques now raise total_level');
    eq(afterPhys.total_level, sumSkills(afterPhys), 'total_level still equals sum(skills) after training a physique');
    s.xp[mainId] = FF.xpFloorForLevel(31);
    ok(FF.computeProfileStats().total_level > afterPhys.total_level, 'a main skill also raises total_level');
    s.physique[physId] = snap.phys; s.xp[mainId] = snap.xp;

    // Ranking by a physique metric reads the skills map.
    eq(FF.lbMetricValue({ skills:{ fireAttunement: 42 } }, 'skill:fireAttunement'), 42, 'can rank by a physique');
    eq(FF.lbMetricValue({ skills:{} }, 'skill:fireAttunement'), 0, 'missing physique ranks as 0');
  });

  // ---- PEON_MAX_SLOTS must be a defined constant (its absence blanked the Peons tab) ---
  suite('peon slot constant', function(){
    eq(FF.PEON_MAX_SLOTS, 5, 'PEON_MAX_SLOTS defined = 5 (10 total: 5 personal + 5 guild)');
    // Cottage build timer: 10 minutes per tier (tier index T -> (T+1)*10 min).
    eq(FF.ESTATE_COTTAGE_MS_PER_TIER, 10*60*1000, 'cottage build = 10 min per tier');
    eq((0+1)*FF.ESTATE_COTTAGE_MS_PER_TIER, 600000, 'tier-0 cottage builds in 10 min');
    eq((3+1)*FF.ESTATE_COTTAGE_MS_PER_TIER, 2400000, 'tier-3 cottage builds in 40 min');
  });

  // ---- Server-wide EXP buff -------------------------------------------------------------
  suite('server exp buff', function(){
    eq(FF.SERVER_BUFF_EXP_COST, 100000, 'exp buff costs 100,000 gold');
    eq(FF.SERVER_BUFF_EXP_MULT, 1.5, 'exp buff is +50% XP');
    eq(FF.expBuffMultFor(1000, 2000), 1.5, 'buff active (now < until) -> 1.5x');
    eq(FF.expBuffMultFor(3000, 2000), 1, 'buff expired (now >= until) -> 1x');
    eq(FF.expBuffMultFor(1000, 0), 1, 'no buff (until 0) -> 1x');
    ok(FF.LB_STAT_METRICS.some(function(m){ return m.key === 'hoursBuffed'; }), 'hoursBuffed is a leaderboard metric');
    // Summoning still works; it just no longer pings a (removed) server-wide grant. Force a summon on a
    // skill with a familiar defined but not yet owned and confirm the familiar is granted.
    var s = FF._state;
    var skill = Object.keys(FF.FAMILIAR_DATA).filter(function(k){ return !(s.familiars[k] && s.familiars[k].owned); })[0];
    ok(skill, 'there is a skill whose familiar is not yet owned to test the summon');
    if(skill){
      var savedRandom = Math.random, savedFam = s.familiars[skill];
      s.familiars[skill] = undefined;
      Math.random = function(){ return 0; };    // force the summon roll to succeed
      try { FF.maybeSummonFamiliar(skill); } finally { Math.random = savedRandom; }
      ok(s.familiars[skill] && s.familiars[skill].owned, 'the brand-new familiar was summoned');
      s.familiars[skill] = savedFam;
    }
    // The buy/registration buff is a full hour; the server extends greatest(now, active_until) by that and
    // the client just reflects whatever active_until comes back.
    eq(FF.SERVER_BUFF_EXP_MS, 3600*1000, 'a full (purchase/registration) buff is 1 hour');
    ok(typeof FF.serverBuffGrant === 'undefined', 'the free client-callable +50% EXP grant is gone (only the paid buy extends it)');
  });

  // ---- Rarity Bonus: an event-triggered, stacking server-wide buff (sacrifice a rare+ item) ----
  suite('server buff: Rarity Bonus', function(){
    // Duration scales linearly t0..t20, per rarity (mirrors the server's raritySeconds).
    eq(FF.rarityBuffSeconds('rare', 0), 10, 'rare t0 -> 10s');
    eq(FF.rarityBuffSeconds('rare', 20), 300, 'rare t20 -> 5 min');
    eq(FF.rarityBuffSeconds('rare', 10), 155, 'rare t10 is the 10..300 midpoint');
    eq(FF.rarityBuffSeconds('supreme', 0), 30, 'supreme t0 -> 30s');
    eq(FF.rarityBuffSeconds('supreme', 20), 600, 'supreme t20 -> 10 min');
    eq(FF.rarityBuffSeconds('fantastic', 0), 30, 'fantastic t0 -> 30s');
    eq(FF.rarityBuffSeconds('fantastic', 20), 900, 'fantastic t20 -> 15 min');
    eq(FF.rarityBuffSeconds('normal', 20), 0, 'a normal (non-rare) item grants nothing');
    eq(FF.rarityBuffSeconds('rare', 99), 300, 'tier is clamped to t20');
    // Effect: the per-rarity chance bonus applies ONLY while the shared timer is live.
    eq(FF.SERVER_RARITY_BONUS.rare, 0.05, 'rare bonus is +5% (5x base)');
    eq(FF.SERVER_RARITY_BONUS.supreme, 0.005, 'supreme bonus is +0.5% (5x base)');
    eq(FF.SERVER_RARITY_BONUS.fantastic, 0.00005, 'fantastic bonus is +0.005% (5x base)');
    eq(FF.rarityBonusShortLabel(), '5%R · 0.5%S · 0.005%F', 'the top-bar chip shows the compact per-rarity summary (3dp so the fantastic figure survives)');
    var sv = FF._serverBuff.rarityUntil;
    try {
      FF._serverBuff.rarityUntil = 0;
      ok(!FF.serverRarityBuffActive() && FF.serverBuffRarityBonus('rare') === 0, 'no bonus while inactive');
      FF._serverBuff.rarityUntil = Date.now() + 60000;
      ok(FF.serverRarityBuffActive(), 'active with a future timer');
      near(FF.serverBuffRarityBonus('rare'), 0.05, 'rare +5% while active', 1e-9);
      near(FF.serverBuffRarityBonus('supreme'), 0.005, 'supreme +0.5% while active', 1e-9);
      near(FF.serverBuffRarityBonus('fantastic'), 0.00005, 'fantastic +0.005% while active', 1e-12);
    } finally { FF._serverBuff.rarityUntil = sv; }
  });

  // ---- Physique XP scales with task tier: each associated physique gains tier+1 (1..21) --------
  suite('physique tier XP', function(){
    eq(FF.itemTierFromId('mining_t0'), 0, 'itemTierFromId t0');
    eq(FF.itemTierFromId('bodyarmor_chain_chest_t20_normal'), 20, 'itemTierFromId t20');
    eq(FF.itemTierFromId('shaft'), 0, 'itemTierFromId no-tier -> 0');
    var pairs = [['bodyStrength', 2], ['curiosity', 1]];
    eq(JSON.stringify(FF.physTierPairs(pairs, 0)), JSON.stringify([['bodyStrength', 1], ['curiosity', 1]]), 't0 -> 1 xp each');
    eq(JSON.stringify(FF.physTierPairs(pairs, 20)), JSON.stringify([['bodyStrength', 21], ['curiosity', 21]]), 't20 -> 21 xp each');
    eq(FF.physTierPairs(pairs, 5)[0][1], 6, 't5 -> 6 xp');
    // recipeTier: explicit tierIndex wins; otherwise fall back to the output id's _t<n> suffix so
    // standard recipes (no tierIndex field) still scale physique XP (regression: Logic stuck at 1).
    eq(FF.recipeTier({tierIndex:7}, 'cooking_t3'), 7, 'recipeTier prefers explicit tierIndex');
    eq(FF.recipeTier({}, 'stonecutting_t5'), 5, 'recipeTier falls back to item id tier');
    eq(FF.recipeTier({id:'twine_t2'}, null), 2, 'recipeTier falls back to recipe.id tier');
    eq(FF.recipeTier({}, 'fletching_shaft'), 0, 'recipeTier no-tier -> 0');
    // A standard carpentry recipe at t4 -> logic (and every associated physique) gains 5.
    eq(FF.physTierPairs([['grossMotor',2],['sleightOfHand',1],['logic',1]], FF.recipeTier({}, 'carpentry_t4'))[2][1], 5, 'carpentry t4 -> logic gains 5');
  });

  // ---- Every physique that interacts with a gather/craft skill now earns tiered XP from it ------
  suite('physique XP: benefit-set folded into trained-set', function(){
    function trainedIds(sk){ return FF.GATHER_PHYSIQUE[sk] ? FF.GATHER_PHYSIQUE[sk].map(function(p){return p[0];}) : FF.CRAFT_PHYSIQUE[sk].map(function(p){return p[0];}); }
    // The core rule: for every gathering/crafting skill, the physiques that BENEFIT it are a subset
    // of the physiques TRAINED by it -- so anything that interacts with the action also earns XP.
    Object.keys(FF.GATHER_PHYSIQUE).concat(Object.keys(FF.CRAFT_PHYSIQUE)).forEach(function(sk){
      var trained = trainedIds(sk);
      FF.physiqueBenefitsForSkill(sk).forEach(function(e){
        ok(trained.indexOf(e[0]) !== -1, sk + ' trains its benefiting physique ' + e[0]);
      });
      // physTierPairs still gives every trained physique tier+1 (uniform, like Logic).
      var pairs = FF.physTierPairs(FF.CRAFT_PHYSIQUE[sk] || FF.GATHER_PHYSIQUE[sk], 4);
      ok(pairs.every(function(p){ return p[1] === 5; }), sk + ': all physiques gain tier+1 (=5 at t4)');
    });
    // Spot-check the specific gaps this closes (benefit-only -> now trained).
    ok(trainedIds('foraging').indexOf('fineMotor') !== -1, 'foraging now trains Fine Motor (its find-rate physique)');
    ok(trainedIds('tailoring').indexOf('handStrength') !== -1, 'tailoring now trains Hand Strength');
    ok(trainedIds('tailoring').indexOf('grossMotor') !== -1, 'tailoring now trains Gross Motor (success)');
    ok(trainedIds('masonry').indexOf('coreStrength') !== -1, 'masonry now trains Core Strength');
    ok(trainedIds('alchemy').indexOf('criticalThinking') !== -1, 'alchemy now trains Critical Thinking');
    ok(trainedIds('runesmithing').indexOf('sleightOfHand') !== -1, 'runesmithing now trains Sleight of Hand (speed)');
    // Unchanged where already covered: heavy crafts keep exactly their original set + no phantom adds.
    ok(trainedIds('carpentry').indexOf('grossMotor') !== -1 && trainedIds('carpentry').indexOf('handStrength') === -1, 'carpentry keeps Gross Motor, gains no hand-craft physique');
  });

  // ---- Chat profanity filter -------------------------------------------------------------------
  suite('chat: profanity filter', function(){
    var c = FF.censorChat;
    function censored(s){ var out = c(s); return out !== s && out.indexOf('*') !== -1; }
    // Clean text is untouched.
    eq(c('hello there, nice to meet you'), 'hello there, nice to meet you', 'clean text passes through');
    eq(c(''), '', 'empty string is safe');
    // Bad words get masked (first char kept, rest starred).
    eq(c('you fuck'), 'you f***', 'basic swear masked');
    ok(censored('what the shit'), 'shit masked');
    ok(censored('bitch'), 'bitch masked');
    // Inflections and compounds.
    ok(censored('stop fucking around'), 'inflection (fucking) masked');
    ok(censored('you asshole'), 'compound (asshole) masked');
    ok(censored('motherfucker'), 'motherfucker masked');
    // Light obfuscation: leetspeak + repeated letters.
    ok(censored('sh1t'), 'leetspeak (sh1t) masked');
    ok(censored('fuuuck'), 'stretched (fuuuck) masked');
    ok(censored('@sshole'), 'leet @ (@sshole) masked');
    // No Scunthorpe: real words that merely contain a bad substring are untouched.
    eq(c('the assassin joined our class in the grass'), 'the assassin joined our class in the grass', 'assassin/class/grass untouched');
    eq(c('check the cockpit and pass'), 'check the cockpit and pass', 'cockpit/pass untouched');
    eq(c('scunthorpe analysis'), 'scunthorpe analysis', 'scunthorpe untouched');
    // Punctuation-adjacent still catches.
    ok(censored('fuck!'), 'trailing punctuation still masked');
    // First letter of the mask is preserved so length/shape stays readable.
    ok(c('shit').charAt(0) === 's' && c('shit').slice(1) === '***', 'mask keeps first char + stars');
    // Website links are stripped (scam/off-site link prevention), on send AND display.
    eq(c('visit http://evil.com/win now'), 'visit [link removed] now', 'http URL removed');
    eq(c('go to https://phish.io/x'), 'go to [link removed]', 'https URL removed');
    eq(c('see www.example.org for more'), 'see [link removed] for more', 'www URL removed');
    eq(c('join discord.gg/abc123'), 'join [link removed]', 'bare domain.tld/path removed');
    eq(c('my site is cool-stuff.net today'), 'my site is [link removed] today', 'hyphenated bare domain removed');
    ok(c('grab it at bit.ly/xyz').indexOf('[link removed]') !== -1, 'short-link domain removed');
    // False positives are NOT censored: decimals, initialisms, party codes, item tokens.
    eq(c('it does 3.5x damage'), 'it does 3.5x damage', 'decimals are not links');
    eq(c('e.g. the tunnel'), 'e.g. the tunnel', 'initialisms (e.g.) are not links');
    eq(c('join my party d2:3f9a1b2c-4d5e-6f70'), 'join my party d2:3f9a1b2c-4d5e-6f70', 'a party code is not a link');
    eq(c('look {{i:AbC123deF}}'), 'look {{i:AbC123deF}}', 'an item-link token is not a website link');
  });

  // ---- Chat profanity filter: per-viewer display toggle ----------------------------------------
  suite('chat: profanity filter is an opt-out display setting', function(){
    var s = FF._state;
    s.settings = s.settings || {};
    var prev = s.settings.chatFilter;
    var d = FF.chatDisplayCensor;
    // Default (filter ON): profanity is masked at display, links always stripped.
    s.settings.chatFilter = true;
    ok(d('you fuck').indexOf('*') !== -1, 'filter on -> profanity masked at display');
    eq(d('visit http://evil.com now'), 'visit [link removed] now', 'filter on -> links removed');
    // Opted out (filter OFF): the raw words come through, but links are STILL stripped (scam prevention).
    s.settings.chatFilter = false;
    eq(d('you fuck'), 'you fuck', 'filter off -> profanity shown raw');
    eq(d('visit http://evil.com now'), 'visit [link removed] now', 'filter off -> links still removed');
    // Undefined setting is treated as ON (safe default), so it never leaks profanity by accident.
    delete s.settings.chatFilter;
    ok(d('you fuck').indexOf('*') !== -1, 'missing setting defaults to masking');
    // The underlying helpers are independent: maskProfanity always masks, censorChat is the full pass.
    ok(FF.maskProfanity('shit').charAt(0) === 's' && FF.maskProfanity('shit').slice(1) === '***', 'maskProfanity masks unconditionally');
    ok(FF.censorChat('you fuck').indexOf('*') !== -1 && FF.censorChat('go to www.x.io').indexOf('[link removed]') !== -1, 'censorChat still does links + profanity');
    s.settings.chatFilter = prev;
  });

  // ---- Chat: guild tags before names, Mortal-path names in red -------------------------------------
  // Owner request: chat names carry the poster's [GUILD] tag, and Mortal-path players wear the same red
  // the leaderboard gives them. Both ride the per-poster meta fetch (leaderboard view for mortal, the
  // world-readable guild_members -> guilds embed for the tag); an unfetched poster renders plain.
  suite('chat: guild tags + mortal red names', function(){
    var now = Date.now(), iso = new Date(now).toISOString();
    try {
      FF._setChatMod({
        roles:{}, mutes:{}, myRole:null,
        authUser:{ username:'Me', id:'u-me2' },
        titles:{ 'u-mort':'', 'u-tagged':'', 'u-plain':'' },
        mortals:{ 'u-mort':true, 'u-tagged':false, 'u-plain':false },
        gtags:{ 'u-mort':'', 'u-tagged':'IVY', 'u-plain':'' },
        messages:[
          { id:11, user_id:'u-mort',    username:'Doomed',  body:'hi',  created_at:iso },
          { id:12, user_id:'u-tagged',  username:'Clanner', body:'yo',  created_at:iso },
          { id:13, user_id:'u-plain',   username:'Nobody',  body:'sup', created_at:iso },
          { id:14, user_id:'u-unknown', username:'Ghost',   body:'??',  created_at:iso }
        ]
      });
      var html = FF.chatMessagesHtml();
      ok(/class="chat-user mortal"[^>]*>Doomed/.test(html), 'a Mortal-path poster wears the red name class');
      ok(html.indexOf('title="Mortal path"') !== -1, 'the red name explains itself on hover');
      ok(/chat-guild-tag/.test(html) && html.indexOf('[IVY]') !== -1, 'a guilded poster shows a [TAG] chip');
      ok(html.indexOf('[IVY]') < html.indexOf('Clanner'), 'the tag sits BEFORE the name');
      ok(/class="chat-user"[^m]*>Clanner/.test(html) || /class="chat-user">Clanner/.test(html), 'a non-mortal name stays the normal colour');
      ok(/class="chat-user">Ghost/.test(html), 'an unfetched poster renders plain — no undefined leakage');
      ok(!/undefined/.test(html), 'no undefined anywhere in the rendered chat');
      // The tag is escaped like every other user-influenced string.
      FF._setChatMod({ gtags:{ 'u-tagged':'<b>' } });
      ok(FF.chatMessagesHtml().indexOf('[&lt;b&gt;]') !== -1, 'a hostile tag renders escaped, never as markup');
      // Guild channel: mortal red applies, the (redundant, same-guild) tag does not.
      FF._setChatMod({ guildMessages:[ { id:1, user_id:'u-mort', username:'Doomed', body:'x', created_at:iso } ] });
      var gh = FF.guildChatMessagesHtml();
      ok(/class="chat-user mortal"/.test(gh), 'guild chat colours Mortal-path posters too');
      ok(!/chat-guild-tag/.test(gh), 'guild chat shows no tag — everyone in it shares one');
      // The palette is real CSS, not just a class name: the mortal name computes a different colour.
      var probe = document.createElement('div');
      probe.innerHTML = '<span class="chat-user">a</span><span class="chat-user mortal">b</span>';
      document.body.appendChild(probe);
      var cPlain = getComputedStyle(probe.children[0]).color, cMort = getComputedStyle(probe.children[1]).color;
      probe.remove();
      ok(cPlain !== cMort, 'the .mortal class actually changes the name colour (' + cMort + ')');
    } finally {
      FF._setChatMod({ messages:[], guildMessages:[], titles:{}, mortals:{}, gtags:{}, authUser:null, myRole:null });
    }
  });

  // ---- Chat moderation: role badges, muted state, mod-button gating, modal protection --------------
  suite('chat: moderation roles + mute + mod controls', function(){
    var savedAuth = FF.chatAmIMuted; // just to reference the module; real restore below via _setChatMod
    var OWNER='u-owner', MOD='u-mod', PLAYER='u-player', ME='u-me';
    var now = Date.now();
    // Baseline: I'm a regular player. Roles map owner+mod; player u-player is muted.
    FF._setChatMod({
      roles: { 'u-owner':'owner', 'u-mod':'moderator' },
      mutes: { 'u-player': now + 3600*1000 },
      myRole: null,
      authUser: { username:'Me', id:ME },
      messages: [
        { id:1, user_id:OWNER, username:'Boss', body:'hi', created_at:new Date(now).toISOString() },
        { id:2, user_id:MOD,   username:'Mod1', body:'yo', created_at:new Date(now).toISOString() },
        { id:3, user_id:PLAYER,username:'Spammer', body:'buy gold', created_at:new Date(now).toISOString() },
        { id:4, user_id:ME,    username:'Me', body:'hello', created_at:new Date(now).toISOString() }
      ]
    });
    // Helpers.
    eq(FF.chatRoleOf(OWNER), 'owner', 'chatRoleOf reads the owner role');
    eq(FF.chatRoleOf(MOD), 'moderator', 'chatRoleOf reads the moderator role');
    eq(FF.chatRoleOf(PLAYER), null, 'a regular player has no role');
    ok(FF.chatMuteUntil(PLAYER) > now, 'an active mute reports its expiry');
    eq(FF.chatMuteUntil(OWNER), 0, 'no mute -> 0');
    ok(!FF.chatIsMod() && !FF.chatIsOwner(), 'a regular player is neither mod nor owner');
    eq(FF.chatAmIMuted(), 0, 'I am not muted');

    // The "⋯" player menu is open to EVERYONE now (View Profile etc.) -- one per OTHER message, none on
    // my own. Badges + muted tag still render for all.
    var htmlPlayer = FF.chatMessagesHtml();
    ok(/chat-mod-owner/.test(htmlPlayer) && /chat-mod-moderator/.test(htmlPlayer), 'owner + moderator badges render for everyone');
    ok(/chat-muted-tag/.test(htmlPlayer), 'a muted user shows the muted marker');
    ok((htmlPlayer.match(/data-action="chatModOpen"/g)||[]).length === 3, 'a regular player sees the ⋯ menu on others (3 of 4 messages)');
    ok(htmlPlayer.indexOf('data-uid="'+ME+'"') === -1, 'no ⋯ menu on my own message');

    // As a moderator, the ⋯ buttons are the same (moderation lives INSIDE the modal now).
    FF._setChatMod({ myRole:'moderator' });
    var htmlMod = FF.chatMessagesHtml();
    ok((htmlMod.match(/data-action="chatModOpen"/g)||[]).length === 3, 'a moderator sees the same 3 ⋯ menus');

    // Modal for a regular player, viewed by a regular player: View Profile only, NO moderation section.
    FF._setChatMod({ myRole:null, target:{ mid:3, uid:PLAYER, name:'Spammer' } });
    FF.renderChatModModal();
    var ovPlain = document.getElementById('chatModOverlay').innerHTML;
    ok(/data-action="chatViewProfile"/.test(ovPlain), 'everyone gets View Profile');
    ok(!/Moderation/.test(ovPlain) && !/data-action="chatModMute"/.test(ovPlain), 'a non-moderator sees no moderation controls in the menu');
    FF._setChatMod({ myRole:'moderator' });

    // Modal gating: a moderator opening a fellow-moderator sees the owner-only lock (no action buttons).
    FF._setChatMod({ target:{ mid:2, uid:MOD, name:'Mod1' } });
    FF.renderChatModModal();
    var ovModOnMod = (typeof document !== 'undefined' && document.getElementById('chatModOverlay')) ? document.getElementById('chatModOverlay').innerHTML : '';
    ok(/Only the owner can moderate/.test(ovModOnMod), 'a mod cannot moderate another mod (owner-only lock shown)');
    ok(!/data-action="chatModMute"/.test(ovModOnMod), '...and no mute button is offered for a protected target');

    // A moderator on a regular player: mute presets + permanent chat-ban + delete, but NO role controls.
    FF._setChatMod({ target:{ mid:3, uid:PLAYER, name:'Spammer' } });
    FF.renderChatModModal();
    var ovModOnPlayer = document.getElementById('chatModOverlay').innerHTML;
    // u-player is already muted in this fixture, so the modal offers Unmute; clear the mute to see mute presets.
    ok(/data-action="chatModDelete"/.test(ovModOnPlayer), 'delete-message is offered');
    ok(/data-action="chatModUnmute"/.test(ovModOnPlayer), 'an already-muted target offers Unmute');
    ok(!/data-action="chatModSetRole"/.test(ovModOnPlayer), 'a moderator sees NO role controls (owner-only)');

    // As the OWNER on an unmuted regular player: mute presets, chat-ban, AND Make Moderator.
    FF._setChatMod({ myRole:'owner', mutes:{}, target:{ mid:3, uid:PLAYER, name:'Spammer' } });
    FF.renderChatModModal();
    var ovOwnerOnPlayer = document.getElementById('chatModOverlay').innerHTML;
    ok(/data-action="chatModMute"[^>]*data-min="10"/.test(ovOwnerOnPlayer), 'mute presets shown for an unmuted target');
    ok(/data-min="5256000"/.test(ovOwnerOnPlayer), 'permanent chat-ban offered');
    ok(/Make Moderator/.test(ovOwnerOnPlayer), 'the owner can appoint a moderator');
    // Owner on an existing moderator: Remove Moderator, and no owner-lock.
    FF._setChatMod({ target:{ mid:2, uid:MOD, name:'Mod1' } });
    FF.renderChatModModal();
    var ovOwnerOnMod = document.getElementById('chatModOverlay').innerHTML;
    ok(/Remove Moderator/.test(ovOwnerOnMod) && !/Only the owner can moderate/.test(ovOwnerOnMod), 'the owner can moderate a moderator (Remove Moderator shown)');

    // Muted-self: chatAmIMuted reflects it; label reads permanent for a ~10y ban.
    FF._setChatMod({ myRole:null, mutes:{ 'u-me': now + 60*1000 } });
    ok(FF.chatAmIMuted() > now, 'a muted local player reports their own mute');
    eq(FF.chatMuteLabel(now + 40*24*3600*1000), 'permanently', 'a >30-day mute reads as a permanent chat-ban');
    ok(/^until /.test(FF.chatMuteLabel(now + 3600*1000)), 'a short mute reads as an until-timestamp');

    // Owner-only Moderation panel: appoint box + named lists of mods and muted players.
    FF._setChatMod({
      myRole:'owner',
      roles:{ 'u-owner':'owner', 'u-mod':'moderator', 'u-mod2':'moderator' },
      mutes:{ 'u-player': now + 3600*1000 },
      names:{ 'u-mod':'Mod1', 'u-mod2':'Mod2', 'u-player':'Spammer' }
    });
    var panel = FF.renderChatModerationPanel();
    ok(/id="modAppointInput"/.test(panel) && /data-action="chatModAppoint"/.test(panel), 'the panel has an appoint-by-username box');
    ok(/Moderators <span[^>]*>\(2\)/.test(panel), 'it lists the moderator count');
    ok(/Mod1/.test(panel) && /Mod2/.test(panel), 'moderators are listed by name');
    ok((panel.match(/data-action="chatModRemove"/g)||[]).length === 2, 'each moderator has a Remove button');
    ok(/Muted players <span[^>]*>\(1\)/.test(panel) && /Spammer/.test(panel) && /data-action="chatModSettingsUnmute"/.test(panel), 'muted players are listed with an Unmute button');

    // Clamped players: owner sees the quarantine list + one-click Unclamp, plus a manual clamp box.
    FF._setChatMod({
      myRole:'owner',
      names:{ 'u-mod':'Mod1', 'u-mod2':'Mod2', 'u-player':'Spammer', 'u-cheat':'Duper' },
      clamps:{ 'u-cheat':{ user_id:'u-cheat', username:'Duper', surfaces:['marketplace','leaderboard','guild','chat'], auto:true, signal:'progress +1.2e13 in 6s' } }
    });
    var panel2 = FF.renderChatModerationPanel();
    ok(/Clamped players <span[^>]*>\(1\)/.test(panel2), 'the panel lists the clamped-player count');
    ok(/Duper/.test(panel2) && /progress \+1.2e13/.test(panel2), 'a clamped player shows its name + auto-detection signal');
    ok(/data-action="clampClear"[^>]*data-uid="u-cheat"/.test(panel2), 'each clamped player has a one-click Unclamp button');
    ok(/id="clampInput"/.test(panel2) && /data-action="clampApply"/.test(panel2) && /id="clampSurf_marketplace"/.test(panel2), 'the panel has a manual clamp box with per-surface toggles');

    // Detection signals (shadow): recorded flags the owner can review + clamp with a click.
    FF._setChatMod({
      myRole:'owner',
      names:{ 'u-mod':'Mod1', 'u-mod2':'Mod2', 'u-player':'Spammer', 'u-flag':'Suspect', 'u-done':'Handled' },
      clamps:{},
      signals:[
        { id:1, user_id:'u-flag', username:'Suspect', kind:'progress_jump', detail:{ jump:1.2e13, elapsed_ms:8000 }, clamped:false, created_at:now },
        { id:2, user_id:'u-done', username:'Handled', kind:'progress_jump', detail:{ jump:9e12 }, clamped:true, created_at:now }
      ]
    });
    var panel3 = FF.renderChatModerationPanel();
    ok(/Detection signals <span[^>]*>\(2, shadow\)/.test(panel3), 'the panel lists recorded detection signals in shadow mode');
    ok(/Suspect/.test(panel3) && /progress_jump/.test(panel3), 'a signal shows the flagged player + evidence');
    ok(/data-action="clampFromSignal"[^>]*data-uid="u-flag"/.test(panel3), 'an un-actioned signal has a one-click Clamp button');
    ok((panel3.match(/data-action="clampFromSignal"/g)||[]).length === 1, 'an already-clamped signal shows no Clamp button');
    FF._setChatMod({ clamps:{}, signals:[] });
    // chatNameFor falls back to a uid fragment when the name isn't cached.
    eq(FF.chatNameFor('u-mod'), 'Mod1', 'chatNameFor resolves a cached username');
    ok(/…$/.test(FF.chatNameFor('u-unknown-123456789')), 'chatNameFor falls back to a uid fragment');

    // ---- Titles: label resolution + tag next to chat names + on the public profile card ----
    var titleIds = Object.keys(FF.TITLE_BY_ID || {});
    if(titleIds.length){
      var tId = titleIds[0], tName = FF.TITLE_BY_ID[tId].name;
      eq(FF.titleName(tId), tName, 'titleName resolves a published title id to its display name');
      eq(FF.titleName('title_not_real_xyz'), '', 'an unknown title id resolves to no label');
      // Title tag next to the poster's name in chat.
      FF._setChatMod({ myRole:null, authUser:{ username:'Me', id:ME }, titles:{ 'u-owner':tId },
        messages:[{ id:9, user_id:OWNER, username:'Boss', body:'hi', created_at:new Date(now).toISOString() }] });
      var htmlTitle = FF.chatMessagesHtml();
      ok(/class="chat-title"/.test(htmlTitle) && htmlTitle.indexOf(tName) !== -1, 'an equipped title renders as a tag next to the chat name');
      // Same title on the public profile card body.
      var card = FF.profileCardBodyHtml({ username:'Boss', total_level:120, gold:5, title:tId, skills:{}, stats:{} });
      ok(/class="profile-title"/.test(card) && card.indexOf(tName) !== -1, 'the profile card shows the equipped title under the name');
      ok(/Total Level/.test(card), 'the profile card still shows headline stats');
    }

    // ---- Public profile modal: loading / no-profile / populated states ----
    FF._setChatMod({ profileTarget:{ uid:PLAYER, name:'Spammer', data:null, loading:true, error:false } });
    FF.renderPlayerProfileModal();
    ok(/Loading profile/.test(document.getElementById('playerProfileOverlay').innerHTML), 'the profile modal shows a loading state');
    FF._setChatMod({ profileTarget:{ uid:PLAYER, name:'Spammer', data:null, loading:false, error:true } });
    FF.renderPlayerProfileModal();
    ok(/hasn.t published a profile/.test(document.getElementById('playerProfileOverlay').innerHTML), 'the profile modal handles a player with no published profile');
    FF._setChatMod({ profileTarget:{ uid:PLAYER, name:'Spammer', loading:false, error:false, data:{ id:PLAYER, username:'Spammer', total_level:88, gold:12, skills:{}, stats:{} } } });
    FF.renderPlayerProfileModal();
    var pm = document.getElementById('playerProfileOverlay').innerHTML;
    ok(/Spammer/.test(pm) && /Total Level/.test(pm) && /data-action="closePlayerProfile"/.test(pm), 'the profile modal renders a fetched profile with a Close button');

    // Clean up module state so later suites see a pristine chat.
    FF._setChatMod({ roles:{}, mutes:{}, names:{}, titles:{}, myRole:null, messages:[], authUser:null, target:null, profileTarget:null });
    FF.renderChatModModal(); FF.renderPlayerProfileModal();
    void savedAuth;
  });

  // ---- Combat log tab + advanced-pipeline toggle ------------------------------------------------
  suite('chat: combat log + advanced toggle', function(){
    var s = FF._state;
    var sv = { adv: s.settings && s.settings.advancedCombatLog };
    s.settings = s.settings || {};
    FF._clReset();
    eq(FF._clGet().length, 0, 'combat log starts empty');
    ok(/No combat yet/.test(FF.combatLogHtml()), 'empty log shows the intro line');

    // Basic entries (advanced off): no pipeline detail.
    s.settings.advancedCombatLog = false;
    eq(FF.advCombat(), false, 'advanced off by default');
    FF.combatLogPush({ dir:'out', dmg:145, crit:true, target:'Wolf' });
    FF.combatLogPush({ dir:'in', dmg:12, blocked:true, target:'Wolf' });
    FF.combatLogPush({ dir:'miss', target:'Wolf' });
    FF.combatLogPush({ dir:'dodge', target:'Wolf' });
    eq(FF._clGet().length, 4, 'four events recorded');
    var basic = FF.combatLogHtml();
    ok(/You hit Wolf for <b>145<\/b>/.test(basic) && /cl-crit/.test(basic), 'a dealt hit shows damage + CRIT');
    ok(/Wolf hit you for <b>12<\/b>/.test(basic) && /blocked/.test(basic), 'a taken hit shows damage + blocked tag');
    ok(/You missed Wolf/.test(basic) && /You dodged Wolf/.test(basic), 'miss + dodge lines render');
    ok(!/cl-detail/.test(basic), 'no pipeline detail while Advanced is off');

    // Special attacks and status-effect (DoT) ticks read distinctly from a raw swing.
    FF._clReset(); s.settings.advancedCombatLog = false;
    FF.combatLogPush({ dir:'in', dmg:9, target:'Wolf' });
    FF.combatLogPush({ dir:'special', target:'Wolf', spName:'Rend' });
    FF.combatLogPush({ dir:'dot', dmg:4, word:'Bleed', target:'Wolf' }); // plain word: playerDotWord dropped its emoji in the v0.0.86.22 sweep (the word flows through escapeHtml)
    var kinds = FF.combatLogHtml();
    ok(/Wolf hit you for <b>9<\/b>/.test(kinds), 'a raw swing reads as a plain hit');
    ok(/cl-special/.test(kinds) && /Wolf uses <b>Rend<\/b>/.test(kinds), 'a special attack names the skill in its own style, distinct from a raw hit');
    ok(/cl-dot/.test(kinds) && /Bleed ticks you for <b>4<\/b>/.test(kinds), 'a status tick reads as a DoT, not a raw hit');

    // Advanced on: an entry with a detail string renders the pipeline breakdown.
    s.settings.advancedCombatLog = true;
    eq(FF.advCombat(), true, 'advCombat reflects the QoL toggle');
    FF.combatLogPush({ dir:'out', dmg:200, crit:false, target:'Bear', detail:'roll 10–20 × physique 1.2 = 200' });
    var adv = FF.combatLogHtml();
    ok(/cl-detail/.test(adv) && /physique 1.2/.test(adv), 'the pipeline detail renders when present');

    // Perk/class descriptions: the normal log tags the effects behind a hit; the Advanced detail itemizes them.
    ok(FF.PLAYER_DMG_MODS.every(function(m){ return typeof m.label === 'string' && m.label.length > 0; }), 'every damage mod carries a display label');
    var _bd = FF.playerDamageModBreakdown({ monster:{}, weaponStyle:{attackTypes:{blunt:1}}, enchTot:{}, isCrit:false, isOffhand:false });
    ok(Array.isArray(_bd) && _bd.every(function(p){ return p.label && Math.abs(p.mult-1) > 0.005; }), 'the breakdown lists only labeled, non-1x effects');
    FF._clReset(); s.settings.advancedCombatLog = false;
    FF.combatLogPush({ dir:'out', dmg:1234, crit:true, target:'Orc', perks:['Vanish','Rage'] });
    var perkLine = FF.combatLogHtml();
    ok(/via Vanish, Rage/.test(perkLine), 'the out-hit line names the perks/class effects that boosted it');
    ok(/cl-perks/.test(perkLine), 'the perk tag uses its own style');
    FF._clReset();
    FF.combatLogPush({ dir:'out', dmg:10, target:'Orc' });
    ok(!/via /.test(FF.combatLogHtml()), 'no perk tag when nothing boosted the hit');

    // Spell Echo: an echo hit reads distinctly from a normal swing, and carries its own Advanced breakdown.
    FF._clReset(); s.settings.advancedCombatLog = true;
    FF.combatLogPush({ dir:'out', dmg:50, crit:false, target:'Bear', echo:'Spell Echo', detail:'spell echo — 50% × 100 hit = 50' });
    var echoHtml = FF.combatLogHtml();
    ok(/cl-echo/.test(echoHtml) && /Spell Echo<\/span> hits Bear/.test(echoHtml), 'a Spell Echo entry reads as an echo, not a normal "You hit"');
    ok(!/You hit Bear/.test(echoHtml), 'an echo is not rendered as a normal hit line');
    ok(/spell echo — 50%/.test(echoHtml), 'the echo carries its Advanced pipeline detail');
    FF._clReset();
    FF.combatLogPush({ dir:'out', dmg:80, target:'Bear', echo:'Twin Echo' });
    ok(/Twin Echo<\/span> hits Bear/.test(FF.combatLogHtml()), 'a Twin Echo is named too');

    // Familiar spells land in the feed too (ticket-0101): damage hits, siphon drains and utility casts.
    FF._clReset(); s.settings.advancedCombatLog = true;
    var svAct2 = s.activity, svHp2 = s.playerHp, svAm = s.familiarBuffs.armorMult, svAu = s.familiarBuffs.armorUntil;
    try {
      s.activity = { type:'combat', playerSwungOnce:true, monsterId:'wildlife_wolf', monsterHp:1e9 };
      FF.castFamiliarSpell({ type:'hit', name:'Test Bolt', dmgType:'blunt', element:null, amount:10 }, 50, 'mining');
      var famEntries = FF._clGet().filter(function(e){ return e.dir==='fam'; });
      eq(famEntries.length, 1, 'a familiar hit pushes one combat-log entry');
      ok(famEntries[0].dmg > 0 && famEntries[0].spName==='Test Bolt', 'the entry carries the spell name and damage');
      eq(famEntries[0].fam, FF.FAMILIAR_DATA.mining.name, 'the entry is tagged with the casting familiar');
      ok(/base /.test(famEntries[0].detail||'') && / = /.test(famEntries[0].detail||''), 'Advanced on: the familiar hit carries a pipeline breakdown');
      var famHtml = FF.combatLogHtml();
      ok(/cl-fam/.test(famHtml) && /Test Bolt/.test(famHtml) && /hits /.test(famHtml), 'the familiar hit renders in its own style');
      // A siphon drain tags the HP it stole.
      FF._clReset(); s.playerHp = 1;
      FF.castFamiliarSpell({ type:'siphon', name:'Test Drain', dmgType:'void', element:null, amount:10 }, 50, 'mining');
      var sip = FF._clGet().filter(function(e){ return e.dir==='fam'; })[0];
      ok(sip && sip.heal > 0, 'a siphon logs the HP it drained back');
      ok(/\+.*HP/.test(FF.combatLogHtml()), 'the drain renders its +HP tag');
      // Utility & heal casts get a cast line while fighting.
      FF._clReset(); s.playerHp = 1;
      FF.castFamiliarSpell({ type:'heal', name:'Test Mend', amount:10 }, 50, 'mining');
      FF.castFamiliarSpell({ type:'armorBuff', name:'Test Ward', mult:1.5, durationMs:6000 }, 50, 'mining');
      var casts = FF._clGet().filter(function(e){ return e.dir==='fam'; });
      eq(casts.length, 2, 'heal + buff casts each log a line');
      ok(casts[0].heal > 0, 'the heal cast carries the HP restored');
      ok(/casts <b>Test Ward<\/b>/.test(FF.combatLogHtml()), 'a utility cast reads as a cast, not a hit');
      // Out of combat the feed stays quiet (buffs can fire between fights).
      FF._clReset(); s.activity = null;
      FF.castFamiliarSpell({ type:'armorBuff', name:'Test Ward', mult:1.5, durationMs:6000 }, 50, 'mining');
      eq(FF._clGet().length, 0, 'no combat-log entry for a cast outside combat');
    } finally { s.activity = svAct2; s.playerHp = svHp2; s.familiarBuffs.armorMult = svAm; s.familiarBuffs.armorUntil = svAu; }

    // Ring buffer cap: never grows unbounded.
    FF._clReset();
    for(var i=0;i<260;i++) FF.combatLogPush({ dir:'out', dmg:1, target:'x' });
    ok(FF._clGet().length <= 200, 'the combat log is capped (ring buffer)');

    // A blank push and an offline capture are ignored (offline is exercised implicitly: push guards on it).
    FF._clReset();
    FF.combatLogPush(null);
    eq(FF._clGet().length, 0, 'a null push is ignored');

    FF._clReset();
    s.settings.advancedCombatLog = sv.adv;
  });

  // ---- Chat unread counter ---------------------------------------------------------------------
  suite('chat: unread count + "Chat (N)" suffix', function(){
    var s = FF._state;
    s.settings = s.settings || {};
    s.settings.chatFlash = true;
    FF.clearChatUnread();
    eq(FF.getChatUnreadCount(), 0, 'starts at 0');
    eq(FF.chatUnreadSuffix(), '', 'no suffix when nothing unread');
    // A message arriving while chat isn't focused/on-screen accrues an unread.
    FF.noteChatActivity(); FF.noteChatActivity(); FF.noteChatActivity(); FF.noteChatActivity();
    eq(FF.getChatUnreadCount(), 4, 'four notes -> count 4');
    eq(FF.chatUnreadSuffix(), ' (4)', 'suffix reads " (4)"');
    // Mobile FAB badge reflects the same count and flashes.
    var badge = document.getElementById('ffChatFabBadge');
    ok(badge && badge.textContent === '4', 'FAB badge shows 4');
    ok(document.getElementById('ffChatFab').classList.contains('ff-chatfab-alert'), 'FAB flashes while unread');
    // Reading chat clears everything.
    FF.clearChatUnread();
    eq(FF.getChatUnreadCount(), 0, 'clear resets to 0');
    eq(FF.chatUnreadSuffix(), '', 'suffix gone after clear');
    ok(badge.textContent === '', 'FAB badge cleared');
    ok(!document.getElementById('ffChatFab').classList.contains('ff-chatfab-alert'), 'FAB no longer flashes');
    // Count caps its label at 99+.
    for(var i=0;i<120;i++) FF.noteChatActivity();
    eq(FF.chatUnreadSuffix(), ' (99+)', 'label caps at 99+');
    FF.clearChatUnread();
    // Respecting the setting: with chatFlash off, no unread accrues.
    s.settings.chatFlash = false;
    FF.noteChatActivity();
    eq(FF.getChatUnreadCount(), 0, 'no unread when chatFlash disabled');
    s.settings.chatFlash = true;
  });

  // ---- Guild membership cap --------------------------------------------------------------------
  suite('guild: 10-member cap', function(){
    eq(FF.GUILD_MAX_MEMBERS, 10, 'cap is 10');
    ok(FF.guildIsFull(10), '10 members is full');
    ok(FF.guildIsFull(11), 'over cap is full');
    ok(!FF.guildIsFull(9), '9 members is not full');
    ok(!FF.guildIsFull(0), 'empty is not full');
    ok(!FF.guildIsFull(undefined), 'undefined count treated as not full');
  });

  // ---- Guild roster: presence dot + last-seen lines (ticket: "online status like the leaderboard",
  // v0.0.78.0). The dot reuses the leaderboard's .lb-online[data-uid] markup verbatim, so
  // updateLeaderboardPresence() repaints roster dots for free; the "last seen" line reads the
  // server-witnessed save clock (guild_action get_state ships members[].last_active as epoch ms) --
  // the same clock the server's leadership-succession check judges by.
  suite('guild roster: online dots and last-seen lines', function(){
    var A = FF.rosterAgoText, now = Date.now();
    eq(A(30*1000), 'moments ago', 'under a minute reads as moments');
    eq(A(5*60*1000), '5m ago', 'minutes band');
    eq(A(3*3600*1000), '3h ago', 'hours band');
    eq(A(47*3600*1000), '47h ago', 'stays in hours through 48h -- the succession ELIGIBILITY window reads in hours');
    eq(A(72*3600*1000), '3d ago', 'the 72h dethrone threshold reads as days');
    eq(A(90*24*3600*1000), '3mo ago', 'long absences read in months');
    eq(FF.rosterLastSeenText(now - 5*60*1000, true), 'Online now', 'presence wins over the save clock');
    eq(FF.rosterLastSeenText(now - 5*60*1000, false), 'Last seen 5m ago', 'offline members show the save-clock absence');
    eq(FF.rosterLastSeenText(null, false), '', 'no server clock -> no line, never a NaN');
    var G = FF.guildState, saved = { guild:G.guild, members:G.members, myRank:G.myRank, applications:G.applications };
    try {
      G.guild = { id:'g-test', tag:'TST', name:'Testers', open:true };
      G.myRank = 'member'; G.applications = [];
      G.members = [
        { user_id:'u-lead', username:'AbsentLeader', rank:'leader',  last_active: now - 4*24*3600*1000 },
        { user_id:'u-off',  username:'ActiveBob',   rank:'officer', last_active: now - 60*1000 }
      ];
      var html = FF.renderGuildRoster();
      ok(html.indexOf('lb-online') !== -1, 'roster rows carry the leaderboard presence dot');
      ok(html.indexOf('data-uid="u-lead"') !== -1 && html.indexOf('data-uid="u-off"') !== -1,
        'dots carry data-uid, so updateLeaderboardPresence() live-repaints them with the leaderboard');
      ok(html.indexOf('Last seen 4d ago') !== -1, 'the absent leader shows a days-scale absence');
      ok(html.indexOf('Last seen 1m ago') !== -1, 'the active officer shows a minutes-scale one');
    } finally { G.guild=saved.guild; G.members=saved.members; G.myRank=saved.myRank; G.applications=saved.applications; }
  });

  // ---- Outfitting craft pages carry no equipping UI (owner order, v0.0.79.12) ----------------------
