  // ---- Final proposal slice: Trapping/Tapping/Spelunking (gather) + Chandlery/Woodcarving/
  //      Glassblowing/Cooperage (craft) -- completes the 30-skill web ------------------------------
  suite('skills: tapping/spelunking + chandlery/woodcarving/glassblowing/cooperage', function(){
    // Two new gathering domains, each a full 21-tier ladder (Trapping was removed; its Fat/Tallow is now a Butchering byproduct).
    ['tapping','spelunking'].forEach(function(g){
      ok(FF.GATHERING_SKILLS[g], g + ' is a gathering skill');
      eq(FF.GATHERING_SKILLS[g].items.length, FF.TIER_COUNT, g + ' has 21 tiers');
      ok(FF.GATHER_PHYSIQUE[g], 'physique table includes ' + g);
    });
    // Trapping is fully removed as a skill; its output is rendered from Butchering instead.
    ok(!FF.GATHERING_SKILLS.trapping, 'Trapping is no longer a gathering skill');
    ok(!FF.GATHER_PHYSIQUE.trapping && !FF.FAMILIAR_DATA.trapping, 'Trapping physique + familiar removed');
    ok(FF._state.xp.trapping == null || FF.GATHERING_SKILLS.trapping == null, 'Trapping is not a live skill');
    // The butcher recipe now yields Fat/Tallow (fat_t<n>) alongside Meat and Hide.
    var bp = FF.ALL_CRAFT_RECIPES['butcher_process_t5'];
    ok(bp && bp.fatId === 'fat_t5' && bp.fatPhysique, 'butchering a t5 carcass can yield fat_t5');
    var fat5 = FF.ALL_SELLABLE && FF.ALL_SELLABLE['fat_t5'];
    ok(fat5 && /Fat|Tallow|Grease|Lard|Wax/.test(fat5.name), 'fat item is registered + sellable');
    // Four new crafting skills, each a full 21-tier ladder.
    ['chandlery','woodcarving','glassblowing','cooperage'].forEach(function(c){
      ok(FF.CRAFTING_SKILLS[c], c + ' is a crafting skill');
      eq(FF.CRAFTING_SKILLS[c].recipes.length, FF.TIER_COUNT, c + ' has 21 tiers');
      ok(FF.CRAFT_PHYSIQUE[c], 'physique table includes ' + c);
    });
    // Each new gather has its named consumer (the interlock holds).
    eq(FF.ALL_CRAFT_RECIPES['chandlery_t5'].inputs['fat_t5'], 1, 'Chandlery renders Butchering Fat/Tallow into Candles 1:1');
    var carv = FF.ALL_CRAFT_RECIPES['woodcarving_t5'].inputs;
    ok(carv['carpentry_t5'] === 1 && carv['tapping_t5'] === 1, 'Woodcarving binds a Carpentry Plank + Tapping Resin');
    var glass = FF.ALL_CRAFT_RECIPES['glassblowing_t5'].inputs;
    ok(glass['spelunking_t5'] === 1 && glass['coal'] === 1, 'Glassblowing melts a Spelunking Mineral over coal');
    var barrel = FF.ALL_CRAFT_RECIPES['cooperage_t5'].inputs;
    ok(barrel['carpentry_t5'] === 2 && barrel['metallurgy_t5'] === 1, 'Cooperage binds Planks with a Metallurgy band');
    // All seven are seeded in the xp table (save-merge safety -- newGame() must know them).
    ['tapping','spelunking','chandlery','woodcarving','glassblowing','cooperage'].forEach(function(s){
      ok(FF._state.xp[s] != null, s + ' is seeded in the xp table');
    });
  });

  // ---- Knowledge vertical: Papermaking -> Bookbinding + the Tome (work-speed) buff --------------
  suite('skills: papermaking / bookbinding', function(){
    ok(FF.CRAFTING_SKILLS.papermaking, 'papermaking is a crafting skill');
    ok(FF.CRAFTING_SKILLS.bookbinding, 'bookbinding is a crafting skill');
    eq(FF.CRAFTING_SKILLS.papermaking.recipes.length, FF.TIER_COUNT, 'papermaking has 21 paper tiers');
    eq(FF.CRAFTING_SKILLS.bookbinding.recipes.length, FF.TIER_COUNT, 'bookbinding has 21 tome tiers');
    // Chain: Logs -> Paper -> Tome (Paper + Cured Leather from Tanning).
    var paper5 = FF.ALL_CRAFT_RECIPES['paper_t5'];
    ok(paper5.inputs['forestry_t5'], 'papermaking pulps Forestry logs');
    var tome5 = FF.ALL_CRAFT_RECIPES['tome_t5'];
    ok(tome5.inputs['paper_t5'] && tome5.inputs['tanning_t5'], 'tome binds Paper + Cured Leather (interlocks Tanning)');
    // Tome grants a timed work-speed buff -- its own channel.
    ok(tome5.tomeSpeedBonus > 0 && tome5.tomeDurationMs > 0, 'tomes carry a timed work-speed buff');
    var t0 = FF.ALL_CRAFT_RECIPES['tome_t0'], t20 = FF.ALL_CRAFT_RECIPES['tome_t20'];
    ok(t20.tomeSpeedBonus > t0.tomeSpeedBonus && t20.tomeSpeedBonus <= 0.15 + 1e-9, 'tome speed bonus scales with tier (cap 15%)');
    // Auto-study / the action-bar Tome widget pick the strongest owned tome (highest speed bonus,
    // tie-broken by longest duration).
    ok(typeof FF.bestAvailableTome === 'function', 'bestAvailableTome exported');
    eq(FF.bestAvailableTome(), null, 'no tomes owned -> bestAvailableTome null');
    FF._state.inventory['tome_t2'] = 1; FF._state.inventory['tome_t15'] = 1;
    var bt = FF.bestAvailableTome();
    ok(bt && bt.id === 'tome_t15', 'bestAvailableTome picks the strongest owned tome');
    delete FF._state.inventory['tome_t2']; delete FF._state.inventory['tome_t15'];
    // Studying a tome speeds work: speedMultiplier drops (lower = faster). No buff by default.
    eq(FF.tomeSpeedBonus(), 0, 'no tome buff by default');
    var before = FF.speedMultiplier(FF._state);
    FF._state.inventory['tome_t10'] = 1;
    FF.studyTome('tome_t10');
    ok(FF.isTomeActive(), 'studying a tome activates the buff');
    ok(FF.tomeSpeedBonus() > 0, 'active tome adds work speed');
    ok(FF.speedMultiplier(FF._state) < before, 'speedMultiplier drops (work is faster) while a tome is active');
    ok(FF.CRAFT_PHYSIQUE.papermaking && FF.CRAFT_PHYSIQUE.bookbinding, 'physique tables include the new skills');
  });

  // ---- 5 new combat classes: gear combos + level perks --------------------------------------
  suite('classes: frostwarden / plaguebearer / berserker / sentinel / spellblade', function(){
    var NEW = ['frostwarden','plaguebearer','berserker','sentinel','spellblade'];
    NEW.forEach(function(id){
      var cd = FF.CLASS_DEFS_BY_ID[id];
      ok(cd, id+' is a registered class');
      if(!cd) return;
      eq(cd.passives.length, 5, id+' has 5 perks');
      eq(cd.passives.map(function(p){ return p.level; }).join(','), '1,20,40,60,80', id+' perks at Lv 1/20/40/60/80');
      ok(cd.reqParts.length >= 5, id+' has a full gear set');
      ok(FF.CLASS_SKILL_IDS.indexOf(id) !== -1, id+' is its own combat skill');
    });
    // Plaguebearer change #1: Hatchet (not Falchion).
    var pb = FF.CLASS_DEFS_BY_ID.plaguebearer;
    ok(/Hatchet/.test(pb.reqText) && !/Falchion/.test(pb.reqText), 'plaguebearer wields a Hatchet, not a Falchion');
    // Plaguebearer Lv80 is Pandemic, and it is DETERMINISTIC now: at max severity the Plague is terminal and
    // erupts on a cadence. The old 10%-per-tick coin flip retired -- it made the class needlessly swingy.
    var pandemic = pb.passives.filter(function(p){ return p.level===80; })[0];
    eq(pandemic.name, 'Pandemic', 'plaguebearer Lv80 is Pandemic');
    ok(/terminal/i.test(pandemic.desc) && !/10%/.test(pandemic.desc) && !/dies|death/i.test(pandemic.desc), 'Pandemic erupts on a cadence at max severity, not on a per-tick roll-explosion chance (not on-death)');

    // ---- Functional: build mock states that activate each class, verify gating + perk math ----
    function armor(mat,tier){ return {material:mat,tier:tier||5}; }
    function stFor(id, level, extra){
      var st = { xp:{}, physique:{}, bodyArmor:{}, equippedMainhand:null, equippedOffhand:null, activity:{type:'combat', playerSwungOnce:true}, playerHp:55 };
      st.xp[id] = FF.xpFloorForLevel(level);
      if(id==='frostwarden'){ st.equippedMainhand='wandWater'; st.equippedOffhand='shieldMedium'; st.bodyArmor={helmet:armor('chain'),chest:armor('chain'),gauntlets:armor('tailoring'),boots:armor('tailoring')}; }
      if(id==='berserker'){ st.equippedMainhand='warhammer'; st.bodyArmor={chest:armor('leather'),gauntlets:armor('tailoring'),boots:armor('tailoring')}; } // no helmet = bare head
      if(id==='sentinel'){ st.equippedMainhand='maul'; st.equippedOffhand='shieldMedium'; st.bodyArmor={helmet:armor('chain'),chest:armor('chain'),gauntlets:armor('chain'),boots:armor('chain')}; }
      if(id==='spellblade'){ st.equippedMainhand='greatsword'; st.bodyArmor={helmet:armor('chain'),chest:armor('chain'),gauntlets:armor('leather'),boots:armor('leather')}; }
      if(extra) for(var k in extra) st[k]=extra[k];
      return st;
    }
    // gating: each mock activates exactly its class
    eq(FF.activeClassId(stFor('berserker',80)), 'berserker', 'berserker gear activates Berserker');
    eq(FF.activeClassId(stFor('frostwarden',80)), 'frostwarden', 'frostwarden gear activates Frostwarden');
    eq(FF.activeClassId(stFor('sentinel',80)), 'sentinel', 'sentinel gear activates Sentinel');
    eq(FF.activeClassId(stFor('spellblade',80)), 'spellblade', 'spellblade gear activates Spellblade');
    // Berserker BLOOD LEDGER: Titan's Heft / Blood Pact / The Blood Ledger / Transfusion / Glass Titan.
    var bNames = FF.CLASS_DEFS_BY_ID.berserker.passives.map(function(p){ return p.name; });
    eq(JSON.stringify(bNames), JSON.stringify(["Titan's Heft",'Blood Pact','The Blood Ledger','Transfusion','Glass Titan']), 'Berserker ladder is the Blood Ledger five');
    // Titan's Heft (Lv1): flat bonus damage = 100% of max HP.
    var bHeft = stFor('berserker',1);
    eq(FF.berserkerTitansHeftDmg(bHeft), Math.round(1.00 * FF.maxHp(bHeft)), "Titan's Heft = 100% of max HP as flat damage");
    ok(FF.berserkerTitansHeftDmg(bHeft) > 0, "Titan's Heft grants a positive flat bonus");
    // Blood Pact (Lv20): +50% damage at 2% current-HP cost.
    eq(FF.berserkerBloodPactMult(stFor('berserker',20)), 1.5, 'Blood Pact +50% damage');
    eq(FF.berserkerBloodPactMult(stFor('berserker',1)), 1, 'Blood Pact inactive below Lv20');
    near(FF.berserkerPactCost(stFor('berserker',20)), 0.02, 'Blood Pact costs 2% of current HP (no set)', 1e-9);
    eq(FF.berserkerPactCost(stFor('berserker',1)), 0, 'no pact cost below Lv20');
    // The Blood Ledger (Lv40): +1% damage per 3% of max HP inked, cap +100%; heals never erase it.
    var bLed = stFor('berserker',40); var bMh = FF.maxHp(bLed);
    bLed.activity = { type:'combat', playerSwungOnce:true, monsterHp: 100 };
    eq(FF.berserkerLedgerMult(bLed), 1, 'an empty Ledger adds nothing');
    bLed.activity.bloodLedger = Math.round(bMh * 0.30); // 30% of the bar inked -> +10%
    near(FF.berserkerLedgerMult(bLed), 1.10, 'Ledger: 30% of max HP inked = +10% damage', 1e-2);
    bLed.activity.bloodLedger = bMh * 10;               // absurdly full -> capped
    near(FF.berserkerLedgerMult(bLed), 2.0, 'the Ledger caps at +100% damage', 1e-9);
    ok(FF.berserkerLedgerCapped(bLed), 'a capped Ledger reads as capped');
    var bLow = stFor('berserker',20); bLow.activity = { type:'combat', playerSwungOnce:true, monsterHp:100, bloodLedger: bMh * 10 };
    eq(FF.berserkerLedgerMult(bLow), 1, 'the Ledger bonus is inactive below Lv40');
    // Ink helper: only accrues for an active Berserker in combat.
    var bInk = stFor('berserker',40); bInk.activity = { type:'combat', playerSwungOnce:true, monsterHp:100 };
    FF.berserkerInkLedger(500, bInk); eq(bInk.activity.bloodLedger, 500, 'inking adds to the Ledger');
    var bNot = stFor('frostwarden',40); bNot.activity = { type:'combat', playerSwungOnce:true, monsterHp:100 };
    FF.berserkerInkLedger(500, bNot); ok(!bNot.activity.bloodLedger, 'no ink without the Berserker class active');
    // Transfusion (Lv60): 8% lifesteal.
    near(FF.berserkerTransfusionLifesteal(stFor('berserker',60)), 0.08, 'Transfusion heals 8% of damage dealt', 1e-9);
    eq(FF.berserkerTransfusionLifesteal(stFor('berserker',40)), 0, 'Transfusion inactive below Lv60');
    // Glass Titan (Lv80, moved from Lv40): +200% max HP (triples the pool), -40% Armor & Dodge.
    eq(FF.berserkerGlassTitanHpMult(stFor('berserker',80)), 3, 'Glass Titan triples max HP (+200%)');
    eq(FF.berserkerGlassTitanHpMult(stFor('berserker',60)), 1, 'Glass Titan HP boost inactive below Lv80');
    eq(FF.maxHp(stFor('berserker',80)), 3 * FF.maxHp(stFor('berserker',60)), 'Glass Titan: max HP at Lv80 is triple the pre-Lv80 pool');
    eq(FF.berserkerGlassMult(stFor('berserker',80)), 0.60, 'Glass Titan -40% Armor & Dodge (x0.60)');
    eq(FF.berserkerGlassMult(stFor('berserker',60)), 1, 'Glass Titan Armor/Dodge penalty inactive below Lv80');
    // The Berserk Toll heal ceiling is retired: everyone heals to full.
    eq(FF.hpHealCeil(stFor('berserker',80)), FF.maxHp(stFor('berserker',80)), 'no heal ceiling — Berserk Toll retired');
    // Frostwarden rework: Permafrost stacks Chill (10% enemy slow each, cap 5/50%); Time Dilation quickens
    // you by half the slow (cap 30%); Rime Resonance grants +25% damage vs a Chilled foe.
    var fw = stFor('frostwarden',80);
    FF.frostwardenApplyChill(fw.activity); FF.frostwardenApplyChill(fw.activity); FF.frostwardenApplyChill(fw.activity);
    eq(FF.enemyChillStacks(fw), 3, 'Permafrost: 3 hits -> 3 Chill stacks');
    ok(Math.abs(FF.enemyChillSlowMult(fw) - 0.30) < 1e-9, 'Chill: 3 stacks -> 30% enemy slow');
    FF.frostwardenApplyChill(fw.activity); FF.frostwardenApplyChill(fw.activity); FF.frostwardenApplyChill(fw.activity);
    eq(FF.enemyChillStacks(fw), 5, 'Chill stacks cap at 5');
    ok(Math.abs(FF.enemyChillSlowMult(fw) - 0.50) < 1e-9, 'Chill slow caps at 50%');
    ok(Math.abs(FF.frostwardenTimeDilation(fw) - 0.25) < 1e-9, 'Time Dilation: 25% haste at 50% Chill');
    eq(FF.frostwardenTimeDilation(stFor('frostwarden',1)), 0, 'Time Dilation inactive below Lv20');
    // Rime Resonance retired: it was a FAMILIAR perk, and familiar damage follows a raw weapon-tier curve
    // that is ~7 orders of magnitude too small at BiS -- so the capstone did nothing but its "+25% vs Chilled"
    // clause, which is folded into Permafrost's rime brittleness (frostwardenDmgMult -> fwBrittleMult).
    var fwB = stFor('frostwarden', 85); fwB.activity = { type:'combat', playerSwungOnce:true, monsterHp:1e9, fwRime: FF.FW_RIME_MAX, dotHitAvg:1000 };
    near(FF.fwBrittleMult(fwB), 1 + FF.FW_BRITTLE_PER_RIME * FF.FW_RIME_MAX, 'Permafrost: brittleness scales with rime');
    near(FF.frostwardenDmgMult(fwB), FF.fwBrittleMult(fwB), 'and it IS the class damage row now');
    eq(FF.fwBrittleMult(stFor('frostwarden', 85)), 1, 'a foe with no rime is not brittle');
    eq(FF.frostwardenDmgMult(stFor('frostwarden',80)), 1, 'Rime Resonance neutral vs an unchilled foe');
    eq(FF.frostwardenDmgMult(stFor('frostwarden',40)), 1, 'no +25% below Lv80');
    // Sentinel "the Bramble": The Bramble (Lv1) / Thorn Lash (Lv20) / Deep Roots (Lv40) /
    // Rending Barbs (Lv60) / The Bloom (Lv80). The incoming-damage reflect is retired wholesale --
    // it returned shares of a ~4-digit monster hit against 1e11-scale player damage.
    var senNames = FF.CLASS_DEFS_BY_ID.sentinel.passives.map(function(p){ return p.name; });
    eq(JSON.stringify(senNames), JSON.stringify(['The Bramble','Thorn Lash','Deep Roots','Rending Barbs','The Bloom']), 'Sentinel ladder is the Bramble five');
    ok(typeof FF.sentinelReflectDamage === 'undefined', 'the incoming-damage reflect retired (never scale off the FOE\'s hit)');
    ok(typeof FF.sentinelReflectSourceName === 'undefined', 'the reflect labeler went with it');
    ok(typeof FF.sentinelArmorMult === 'undefined', 'Bulwark\'s Wrath +40% Armor retired (Armor never a damage input)');
    ok(typeof FF.legReflectCanCrit === 'undefined', 'Reckoning/Spinecrusher reflect-crit retired (flat at ~100% BiS crit)');
    // Thorn Lash (Lv20): scaled by growth off the PLAYER's recent hit; a Block lashes double.
    var senLash = stFor('sentinel',20,{ snGrowth:50, activity:{type:'combat', playerSwungOnce:true,monsterHp:100,dotHitAvg:1000} });
    eq(FF.snLashDamage(false, senLash), Math.round(1000 * FF.SN_LASH_PCT * 0.5), 'Thorn Lash: dotBase x 50% x growth/100');
    eq(FF.snLashDamage(true, senLash), Math.round(1000 * FF.SN_LASH_PCT * 0.5) * 2, 'a Block lashes double');
    eq(FF.snLashDamage(false, stFor('sentinel',1,{ snGrowth:50, activity:{type:'combat', playerSwungOnce:true,monsterHp:100,dotHitAvg:1000} })), 0, 'no lash below Lv20');
    // Deep Roots (Lv40): the Snare scales with growth; inert without the class or below Lv40.
    ok(Math.abs(FF.snSnareSlow(stFor('sentinel',40,{ snGrowth:100, activity:{type:'combat', playerSwungOnce:true,monsterHp:100} })) - FF.SN_SNARE_MAX) < 1e-9, 'a full hedge Snares at the 25% cap');
    eq(FF.snSnareSlow(stFor('sentinel',20,{ snGrowth:100, activity:{type:'combat', playerSwungOnce:true,monsterHp:100} })), 0, 'no Snare below Lv40');
    // Rending Barbs / Bonecrusher share the Sunder channel; the shred fraction is the legendary's axis.
    eq(FF.snShredFrac(stFor('sentinel',80)), FF.SENTINEL_SHRED_FRAC, 'Rending Barbs: the shared 50% Sunder');
    // Tie the "unlocked" flag to real reflect behaviour: the Block share contributes iff a blocked
    // reflect exceeds the unblocked one -- true only at Lv20+, so the label can only truthfully say
    // Sentinel is the shield-wall: a solid innate Block chance so its Block payoffs reliably fire.
    ok(FF.classBlockBonus(stFor('sentinel',1)) >= 0.30, 'Sentinel gains innate Block chance');
    eq(FF.classBlockBonus(stFor('spellblade',80)), 0, 'a non-Sentinel class gets no innate Block bonus');
    eq(FF.SENTINEL_SHRED_FRAC, 0.5, 'the shared Sunder ignores 50% of enemy armour');
    // The tick derives from dotBase x growth; no class or no growth means no tear.
    eq(FF.snTickDps(stFor('sentinel',80,{ snGrowth:100, activity:{type:'combat', playerSwungOnce:true,monsterHp:100,dotHitAvg:1000} })), 1000 * FF.SN_TICK_PCT * 100, 'the tear: dotBase x 0.8% x growth per second');
    eq(FF.snTickDps(stFor('sentinel',80,{ activity:{type:'combat', playerSwungOnce:true,monsterHp:100,dotHitAvg:1000} })), 0, 'an unplanted field tears nothing');
    eq(FF.snTickDps({xp:{},physique:{},bodyArmor:{},equippedMainhand:null,equippedOffhand:null,snGrowth:100,activity:{type:'combat', playerSwungOnce:true,monsterHp:100,dotHitAvg:1000},playerHp:1}), 0, 'no class -> no tear');
    // Spellblade rework v2, "the Afterimage Train": Afterimage (Lv1) / Runeglow (Lv20) / Deep Runes
    // (Lv40) / Runic Tempo (Lv60) / Standing Wave (Lv80). RULE (third never-scale entry): never scale a
    // line by raw ENCHANT COUNT/TOTALS. The deep engine tests live in their own suite below.
    var sbNames = FF.CLASS_DEFS_BY_ID.spellblade.passives.map(function(p){ return p.name; });
    eq(JSON.stringify(sbNames), JSON.stringify(['Afterimage','Runeglow','Deep Runes','Runic Tempo','Standing Wave']), 'Spellblade ladder is the Afterimage Train five');
    // Every enchant-count converter is retired.
    ok(typeof FF.spellbladeRuneHungerMult === 'undefined', 'Rune Hunger retired (a pinned +4%/enchant flat)');
    ok(typeof FF.spellbladeCriticalRunesCrit === 'undefined', 'Critical Runes retired (dead at ~100% BiS crit)');
    ok(typeof FF.spellbladeEchoChance === 'undefined', 'the echo coin flips retired (the train is deterministic)');
    ok(typeof FF.spellbladeResonantCrit === 'undefined', 'Resonant Crit retired (afterimages never re-roll a crit)');
    eq(FF.spellbladeEnchantBoost(stFor('spellblade',80)), 1, 'Empowered Runes retired: no hidden x2 across the enchant channels');
    // Runeglow (Lv20): rarity raises the ratio. Two fantastic items -> +2%.
    function sbRar(level, rarity){
      var st = stFor('spellblade', level);
      st.equippedMainhandRarity = rarity; st.bodyArmor = st.bodyArmor || {};
      st.bodyArmor.chest = { material:'chain', tier:5, rarity: rarity };
      return st;
    }
    near(FF.sbRuneglow(sbRar(20,'fantastic')), 2 * FF.SB_GLOW_FANT, 'Runeglow: two fantastic items -> +2% ratio', 1e-9);
    near(FF.sbRuneglow(sbRar(20,'rare')), 2 * FF.SB_GLOW_RARE, 'rare items glow a third as bright', 1e-9);
    eq(FF.sbRuneglow(sbRar(1,'fantastic')), 0, 'no Runeglow below Lv20');
    near(FF.sbEchoRatio(sbRar(20,'fantastic')), FF.SB_ECHO_RATIO_BASE + 2*FF.SB_GLOW_FANT, 'the ratio = base 40% + the glow', 1e-9);
    // Deep Runes (Lv40): depth from enchant-roll QUALITY (weapon critDamage rolls 5..30; 30 = maxed).
    function sbQ(level, roll){
      var st = stFor('spellblade', level);
      st.uniqueItems = { w1:{ kind:'weapon', tier:19, enhance:0, enchants:[{mod:'critDamage', roll:roll}] } };
      st.equippedMainhandUid = 'w1';
      return st;
    }
    near(FF.sbEnchantQuality(sbQ(40, 30)), 1, 'a maxed roll reads quality 1.0', 1e-9);
    near(FF.sbEnchantQuality(sbQ(40, 5)), 0, 'a floor roll reads quality 0', 1e-9);
    eq(FF.sbEchoDepth(sbQ(40, 30)), 6, 'Deep Runes: maxed rolls -> depth 6');
    eq(FF.sbEchoDepth(sbQ(40, 5)), 2, 'floor rolls -> the base depth 2');
    eq(FF.sbEchoDepth(sbQ(1, 30)), 1, 'below Deep Runes the train is a single afterimage');
    // No class active -> every perk multiplier is neutral.
    var none = { xp:{}, physique:{}, bodyArmor:{}, equippedMainhand:null, equippedOffhand:null, activity:{type:'combat', playerSwungOnce:true}, playerHp:1 };
    eq(FF.berserkerLedgerMult(none), 1, 'no class -> Blood Ledger neutral');
    // Quick Quill (D3 2pc) rate vs base: +5% per 2% inked vs +1% per 3%.
    ok(Math.abs(FF.BERSERK_LEDGER_RATE - 0.01/0.03) < 1e-9 && Math.abs(FF.BERSERK_LEDGER_RATE_D3 - 0.05/0.02) < 1e-9, 'Ledger rates: base +1%/3%, Quick Quill +5%/2%');
    eq(FF.frostwardenDmgMult(none), 1, 'no class -> Frostwarden damage neutral');
    eq(FF.snSnareSlow(none), 0, 'no class -> no Bramble Snare');
    eq(FF.enemyChillSlowMult(none), 0, 'no chill -> no enemy slow');
  });

  suite('classes: pyromancer / sharpshooter / juggernaut / nightblade / executioner (unused weapons)', function(){
    var NEW = ['pyromancer','sharpshooter','juggernaut','nightblade','executioner'];
    NEW.forEach(function(id){
      var cd = FF.CLASS_DEFS_BY_ID[id];
      ok(cd, id+' is a registered class');
      if(!cd) return;
      eq(cd.passives.length, 5, id+' has 5 perks');
      eq(cd.passives.map(function(p){ return p.level; }).join(','), '1,20,40,60,80', id+' perks at Lv 1/20/40/60/80');
      ok(cd.reqParts.length >= 5, id+' has a full gear set');
      ok(FF.CLASS_SKILL_IDS.indexOf(id) !== -1, id+' is its own combat skill');
      // each carries a familiar with a unique 4-spell kit + a channelled element
      var fam = FF.FAMILIAR_DATA[id];
      ok(fam && fam.spells && fam.spells.length === 4, id+' familiar has a 4-spell kit');
    });
    // Each new class must claim a weapon type NO prior class used.
    ok(/Fire Wand/.test(FF.CLASS_DEFS_BY_ID.pyromancer.reqText), 'pyromancer wields the Fire Wand');
    ok(/Long Bow/.test(FF.CLASS_DEFS_BY_ID.sharpshooter.reqText), 'sharpshooter wields the Long Bow');
    ok(/Sledge/.test(FF.CLASS_DEFS_BY_ID.juggernaut.reqText), 'juggernaut wields the Sledge');
    ok(/Dark Wand/.test(FF.CLASS_DEFS_BY_ID.nightblade.reqText), 'nightblade wields the Dark Wand');
    ok(/Full-Moon Axe/.test(FF.CLASS_DEFS_BY_ID.executioner.reqText), 'executioner wields the Full-Moon Axe');

    function armor(mat,tier){ return {material:mat,tier:tier||5}; }
    function stFor(id, level, extra){
      var st = { xp:{}, physique:{}, bodyArmor:{}, equippedMainhand:null, equippedOffhand:null, activity:{type:'combat', playerSwungOnce:true,monsterHp:100}, playerHp:55 };
      st.xp[id] = FF.xpFloorForLevel(level);
      if(id==='pyromancer'){ st.equippedMainhand='wandFire'; st.equippedOffhand='wardLight'; st.bodyArmor={helmet:armor('tailoring'),chest:armor('tailoring'),gauntlets:armor('tailoring'),boots:armor('tailoring')}; }
      if(id==='sharpshooter'){ st.equippedMainhand='bowLong'; st.equippedOffhand='quiver'; st.bodyArmor={helmet:armor('leather'),chest:armor('leather'),boots:armor('leather'),gauntlets:armor('tailoring')}; }
      if(id==='juggernaut'){ st.equippedMainhand='sledge'; st.bodyArmor={helmet:armor('plate'),chest:armor('plate'),gauntlets:armor('plate'),boots:armor('plate')}; }
      if(id==='nightblade'){ st.equippedMainhand='wandDark'; st.equippedOffhand='wardLight'; st.bodyArmor={helmet:armor('leather'),chest:armor('leather'),gauntlets:armor('leather'),boots:armor('leather')}; }
      if(id==='executioner'){ st.equippedMainhand='fullmoonaxe'; st.bodyArmor={chest:armor('chain'),gauntlets:armor('chain'),boots:armor('leather')}; } // no helmet = bare head
      if(extra) for(var k in extra) st[k]=extra[k];
      return st;
    }
    // gating: each mock activates exactly its class (unique unused weapon disambiguates)
    eq(FF.activeClassId(stFor('pyromancer',80)), 'pyromancer', 'fire wand + ward + cloth => Pyromancer');
    eq(FF.activeClassId(stFor('sharpshooter',80)), 'sharpshooter', 'long bow + quiver + leather => Sharpshooter');
    eq(FF.activeClassId(stFor('juggernaut',80)), 'juggernaut', 'sledge + full plate => Juggernaut');
    eq(FF.activeClassId(stFor('nightblade',80)), 'nightblade', 'dark wand + ward + full leather => Voidshadow');
    eq(FF.activeClassId(stFor('executioner',80)), 'executioner', 'full-moon axe + bare head + chain => Executioner');
    // Nightblade was renamed to Voidshadow (display only; id/bonus keys unchanged).
    eq(FF.CLASS_DEFS_BY_ID.nightblade.name, 'Voidshadow', 'nightblade renamed to Voidshadow');
    // New gear requirements gate: dropping the added piece must deactivate the class.
    eq(FF.activeClassId(stFor('pyromancer',80,{bodyArmor:{helmet:armor('tailoring'),chest:armor('tailoring'),boots:armor('tailoring')}})), null, 'Pyromancer needs Cloth Gloves');
    eq(FF.activeClassId(stFor('sharpshooter',80,{bodyArmor:{helmet:armor('leather'),chest:armor('leather'),boots:armor('leather')}})), null, 'Sharpshooter needs Cloth Gloves');
    eq(FF.activeClassId(stFor('nightblade',80,{bodyArmor:{helmet:armor('leather'),chest:armor('leather'),gauntlets:armor('leather')}})), null, 'Voidshadow needs Leather Boots');

    var monFull = {hp:100}, monLow = {hp:100};
    // The Conflagration: Burn is ONE Blaze with fuel, not five stacks. Fuel drives its tick, its damage
    // multiplier, Heat Haze, and the Flashover threshold.
    eq(FF.newClassDmgMult(monFull, stFor('pyromancer',80)), 1, 'Pyromancer no longer grants flat damage');
    eq(FF.newClassCritChance(stFor('pyromancer',80)), 0, 'Pyromancer no longer grants flat crit chance');
    eq(FF.newClassCritDmg(stFor('pyromancer',80)), 0, 'Pyromancer no longer grants flat crit damage');
    eq(FF.classBlockBonus(stFor('pyromancer',80)), 0, 'Pyromancer no longer grants Block');
    var pyro = stFor('pyromancer',80);
    eq(FF.pyBlazeCap(pyro), FF.PY_FUEL_MAX, 'a bare Blaze holds 100 fuel');
    eq(FF.pyBlazeFuel(pyro), 0, 'and starts cold');
    // Hits feed fuel. The pool is the mechanic; burnStacks is DERIVED from it purely so the ~15 external
    // readers (Rimewyrm vs Scorched, Cremation, the Ranger's Fire Arrows, d2BurnTickMult...) keep working.
    FF.pyBlazeFeed(pyro.activity, 50, pyro);
    eq(FF.pyBlazeFuel(pyro), 50, 'the Blaze took the fuel');
    near(FF.pyBlazeFrac(pyro), 0.5, 'half a tank');
    ok(FF.enemyBurning(pyro), 'a living Blaze still reads as "burning" to every external effect');
    ok(FF.enemyBurnStacks(pyro) > 0, 'and still exposes a derived stack count');
    ok(pyro.activity.burnDps > 0, 'and a live burn dps for the shared tick body');
    // The Blaze is a damage multiplier in its own right, scaling with size.
    near(FF.pyBlazeDmgMult(pyro), 1 + FF.PY_BLAZE_DMG_PCT * 50, 'the Blaze is +0.6% damage per fuel');
    ok(FF.pyBlazeDmgMult(stFor('pyromancer',80)) === 1, 'a cold Blaze adds nothing');
    // Fuel feed rates: Bellows (Lv40) doubles a crit's fuel.
    eq(FF.pyFuelPerHit(false, stFor('pyromancer',80)), FF.PY_FUEL_PER_HIT, 'a normal hit feeds the base fuel');
    eq(FF.pyFuelPerHit(true, stFor('pyromancer',80)), FF.PY_FUEL_PER_HIT * FF.PY_FUEL_CRIT_MULT, 'Bellows: a crit feeds double');
    eq(FF.pyFuelPerHit(true, stFor('pyromancer',20)), FF.PY_FUEL_PER_HIT, 'no crit bonus before Lv40');
    // It burns itself down -- uptime is the skill. Bellows slows that; Everburning stops it entirely.
    ok(FF.pyBurnRate(stFor('pyromancer',1)) > 0, 'an unfed Blaze dies down');
    near(FF.pyBurnRate(stFor('pyromancer',80)), FF.PY_BURN_RATE * FF.PY_BURN_RATE_L40, 'Bellows: 30% slower burn-down');
    var down = stFor('pyromancer',80); FF.pyBlazeFeed(down.activity, 60, down);
    FF.pyBlazeBurnDown(down.activity, 1000, down);
    ok(FF.pyBlazeFuel(down) < 60, 'a second of neglect costs fuel');
    // Heat Haze re-keyed off the Blaze's SIZE; Kindling Crits and Fever-Pitch-as-capstone retired.
    // At Lv60 a full tank just sits there, so the Haze reaches its cap.
    var haze = stFor('pyromancer',60); FF.pyBlazeFeed(haze.activity, FF.pyBlazeCap(haze), haze);
    near(FF.pyromancerHeatHazeDodge(haze), FF.PY_HAZE_CAP, 'Heat Haze caps at +20% Dodge on a full Blaze');
    // At Lv80 you can never SIT at full: filling the tank erupts and falls back to a quarter, by design.
    var over = stFor('pyromancer',80); FF.pyBlazeFeed(over.activity, FF.pyBlazeCap(over), over);
    near(FF.pyBlazeFrac(over), FF.PY_FLASHOVER_FLOOR, 'a full Blaze Flashovers and resets to a quarter tank');
    // (The eruption's damage lands via applyChipDamage, which writes to the LIVE state, so a detached
    // fixture cannot observe it -- the fuel reset is the observable half here.)
    eq(FF.pyromancerHeatHazeDodge(stFor('pyromancer',40)), 0, 'Heat Haze inactive below Lv60');
    eq(FF.pyromancerKindlingCritDmg(pyro), 0, 'Kindling Crits retired');
    // The wand chassis knob: the SECOND class on the x49 element-gear stack.
    near(FF.PY_SWING_MULT, 0.32, 'the wand channels its raw swings (THE band knob, v0.0.96.17 bands)');
    ok(FF.PLAYER_DMG_MODS.some(function(r){ return r.name === 'pyromancerIgnite'; }), 'the Ignite channel is a named PLAYER_DMG_MODS row');
    ok(FF.PLAYER_DMG_MODS.some(function(r){ return r.name === 'pyromancerBlaze'; }), 'and the Blaze multiplier is its own row');
    // Sharpshooter rework v2, "the Exposure Ladder": Expose (Lv1) / Patient Eye (Lv20) / Threadbare
    // (Lv40) / Unraveling (Lv60) / Bare (Lv80). RULE: never scale a line by raw Accuracy -- every old
    // converter was pinned at its cap at BiS. The deep engine tests live in their own suite below.
    var ssNames = FF.CLASS_DEFS_BY_ID.sharpshooter.passives.map(function(p){ return p.name; });
    eq(JSON.stringify(ssNames), JSON.stringify(['Expose','Patient Eye','Threadbare','Unraveling','Bare']), 'Sharpshooter ladder is the Exposure Ladder five');
    var ssMon = FF.MONSTERS[0];
    function ssFor(level, extra){
      var st = stFor('sharpshooter', level, extra);
      st.activity = st.activity || {}; st.activity.type='combat';
      if(st.activity.monsterId == null) st.activity.monsterId = ssMon.id;
      if(st.activity.monsterHp == null) st.activity.monsterHp = ssMon.hp;
      return st;
    }
    // Every Accuracy converter is retired.
    ok(typeof FF.sharpshooterEagleEyeCrit === 'undefined', 'Eagle Eye retired (crit is ~100% at BiS)');
    ok(typeof FF.sharpshooterPinpointMult === 'undefined', 'Pinpoint retired (pinned at its cap)');
    ok(typeof FF.sharpshooterFocusCritDmg === 'undefined', "Marksman's Focus retired (pinned at its cap)");
    ok(typeof FF.sharpshooterArmorPierce === 'undefined', 'Armor-Splitter retired (the ladder strips armour now)');
    ok(typeof FF.sharpshooterPatienceMult === 'undefined', "Sniper's Patience retired (the ladder IS the patience)");
    eq(FF.classAccuracyMult(stFor('sharpshooter',80)), 1, 'no flat class accuracy bonus');
    // The ladder reads: exposure, armour strip, dodge strip, tears, Bare.
    var ssL = ssFor(80); ssL.activity.ssPeel = 6; ssL.activity.ssSeeded = true;
    near(FF.ssExposureMult(ssL), 1.30, 'Expose: 6 layers -> +30% damage taken');
    near(FF.ssArmorStrip(ssL), 0.36, 'Expose: 6 layers -> 36% armour stripped');
    near(FF.ssDodgeStrip(ssL), 0.24, 'Threadbare: 6 layers -> 24% Dodge stripped');
    near(FF.ssTearMult(ssL), 1.60, 'Threadbare: tears +10% per layer (6 -> x1.6)');
    eq(FF.ssBare(ssL), false, 'six layers is not Bare');
    ssL.activity.ssPeel = 10;
    eq(FF.ssBare(ssL), true, 'ten layers is Bare at Lv80');
    eq(FF.ssArmorStrip(ssL), 1, 'Bare: armour fully ignored');
    var ssLow = ssFor(60); ssLow.activity.ssPeel = 10; ssLow.activity.ssSeeded = true;
    eq(FF.ssBare(ssLow), false, 'no Bare below Lv80');
    near(FF.ssDodgeStrip(ssFor(20,{activity:{type:'combat', playerSwungOnce:true,monsterId:ssMon.id,monsterHp:ssMon.hp,ssPeel:6,ssSeeded:true}})), 0, 'no dodge strip below Lv40');
    eq(FF.ssPeel(stFor('pyromancer',80,{activity:{type:'combat', playerSwungOnce:true,monsterHp:100,ssPeel:6}})), 0, 'the ladder reads zero without the class');
    // Juggernaut rework v2, "the Aftershock": Seismic Impact (Lv1) / Resonance (Lv20) / Faultline (Lv40)
    // / Mounting Fury (Lv60) / The Big One (Lv80). The deep engine tests live in their own suite below;
    // this block covers the always-on multiplier ladder and the retirements.
    var jugNames = FF.CLASS_DEFS_BY_ID.juggernaut.passives.map(function(p){ return p.name; });
    eq(JSON.stringify(jugNames), JSON.stringify(['Seismic Impact','Resonance','Faultline','Mounting Fury','The Big One']), 'Juggernaut ladder is the Aftershock five');
    // Wind-Up retired: no flat damage trade, no self-slow.
    ok(Math.abs(FF.newClassDmgMult(monFull, stFor('juggernaut',80)) - 1) < 1e-9, 'Wind-Up retired: no flat class damage multiplier');
    ok(Math.abs(FF.classAttackSpeedMult(stFor('juggernaut',1)) - 1) < 1e-9, 'Wind-Up retired: the sledge swings at its natural 9s');
    // The reworked kit drops all defensive perks: no Block, no Armor mult, no incoming reduction.
    eq(FF.classBlockBonus(stFor('juggernaut',80)), 0, 'Juggernaut no longer grants Block (Bulwark removed)');
    ok(typeof FF.juggernautArmorMult === 'undefined', 'Ironclad armor helper removed');
    ok(typeof FF.juggernautIncomingMult === 'undefined', 'Unstoppable incoming helper removed');
    ok(typeof FF.juggernautSmashReady === 'undefined', 'Overhead Smash retired (meaningless at ~100% BiS crit)');
    ok(typeof FF.juggernautArmorPierce === 'undefined', 'Pulverize retired (always-on at BiS; Faultline carries the armour identity)');
    ok(typeof FF.legEarthshakerBuild === 'undefined', "Cavebreaker's Tremor meter retired (its impacts count double toward Resonance)");
    // Resonance (Lv20): +10%/stack (Standing Stones deepens to 15% -- set suite), read from state.
    ok(Math.abs(FF.jgResonanceMult(stFor('juggernaut',20,{jgResonance:2})) - 1.20) < 1e-9, 'Resonance: 2 stacks -> +20%');
    ok(Math.abs(FF.jgResonanceMult(stFor('juggernaut',20,{jgResonance:9})) - 1.30) < 1e-9, 'Resonance caps at 3 stacks (+30%)');
    eq(FF.jgResonanceMult(stFor('juggernaut',1,{jgResonance:2})), 1, 'Resonance inactive below Lv20');
    // Mounting Fury (Lv60): +8% crit dmg per impact per SESSION, cap 10 (was per-fight, cap 8).
    ok(Math.abs(FF.jgFuryCritDmg(stFor('juggernaut',60,{jgFury:3})) - 0.24) < 1e-9, 'Mounting Fury: 3 impacts -> +24% crit damage');
    ok(Math.abs(FF.jgFuryCritDmg(stFor('juggernaut',60,{jgFury:99})) - 0.80) < 1e-9, 'Mounting Fury caps at 10 (+80%)');
    eq(FF.jgFuryCritDmg(stFor('juggernaut',40,{jgFury:3})), 0, 'Mounting Fury inactive below Lv60');
    ok(Math.abs(FF.newClassCritDmg(stFor('juggernaut',60,{jgFury:3})) - 0.24) < 1e-9, 'the session Fury feeds newClassCritDmg');
    // Faultline (Lv40): stacking shred, capped, lasting while the ground rings.
    var jfSt = stFor('juggernaut',40,{activity:{type:'combat', playerSwungOnce:true,monsterHp:100,jgFaultShred:0.30,jgFaultUntil:Date.now()+5000}});
    ok(Math.abs(FF.jgFaultShred(jfSt) - 0.30) < 1e-9, 'Faultline: banked cracks read from the fight');
    ok(Math.abs(FF.jgFaultShred(stFor('juggernaut',40,{activity:{type:'combat', playerSwungOnce:true,monsterHp:100,jgFaultShred:0.9,jgFaultUntil:Date.now()+5000}})) - 0.60) < 1e-9, 'Faultline caps at 60% shred');
    eq(FF.jgFaultShred(stFor('juggernaut',40,{activity:{type:'combat', playerSwungOnce:true,monsterHp:100,jgFaultShred:0.3,jgFaultUntil:Date.now()-1}})), 0, 'the cracks re-knit when the ground falls silent');
    eq(FF.jgFaultShred(stFor('juggernaut',20,{activity:{type:'combat', playerSwungOnce:true,monsterHp:100,jgFaultShred:0.3,jgFaultUntil:Date.now()+5000}})), 0, 'Faultline inactive below Lv40');
    // Voidshadow rework v2, "the Doomsayer": Stamp of Doom (Lv1) / Marks of the Void (Lv20) /
    // Litany of Woes (Lv40) / Soul Tax (Lv60) / Doomsday (Lv80). The deep engine tests live in their
    // own suite below; this block covers the always-on multiplier ladder.
    var nbNames = FF.CLASS_DEFS_BY_ID.nightblade.passives.map(function(p){ return p.name; });
    eq(JSON.stringify(nbNames), JSON.stringify(['Stamp of Doom','Marks of the Void','Litany of Woes','Soul Tax','Doomsday']), 'Voidshadow ladder is the Doomsayer five');
    var vFuture = Date.now() + 10000;
    function nbSt(level, vuln, extraDebuffs){
      var act = { type:'combat', playerSwungOnce:true, monsterHp:100 };
      if(vuln > 0){ act.voidVulnStacks = vuln; act.voidVulnUntil = vFuture; }
      if(extraDebuffs){ for(var k in extraDebuffs) act[k] = extraDebuffs[k]; }
      return stFor('nightblade', level, { activity:act, classDebuffs:{ enemyDmgUntil:0, enemyArmorUntil:0 } });
    }
    // Marks of the Void: +2% dmg-taken per Vulnerability stack, capped at 10 (+20%) -- and that is the
    // CEILING now: the old Lv80 "+40% at max stacks" flat was retired (it could not fail at BiS).
    ok(Math.abs(FF.voidVulnMult(nbSt(1,5)) - 1.10) < 1e-9, 'Marks of the Void: 5 stacks -> +10% damage taken');
    ok(Math.abs(FF.voidVulnMult(nbSt(1,10)) - 1.20) < 1e-9, 'Marks of the Void: +20% at max (10) stacks');
    ok(Math.abs(FF.voidVulnMult(nbSt(1,20)) - 1.20) < 1e-9, 'Vulnerability mult caps at 10 stacks');
    eq(FF.voidVulnMult(nbSt(1,0)), 1, 'no Vulnerability -> neutral mult');
    ok(Math.abs(FF.voidVulnMult(nbSt(80,10)) - 1.20) < 1e-9, 'Lv80 no longer deepens the marks (the old flat Doom is retired -- Lv80 is Doomsday)');
    // enemyDebuffCount ("woes"): distinct debuffs on the foe -- Curse and Decay joined the count.
    var nbCount = stFor('nightblade',80,{ activity:{type:'combat', playerSwungOnce:true,monsterHp:100,voidVulnStacks:5,voidVulnUntil:vFuture,enemyStunUntil:vFuture}, classDebuffs:{enemyDmgUntil:vFuture,enemyArmorUntil:0} });
    eq(FF.enemyDebuffCount(nbCount), 3, 'enemyDebuffCount tallies Vulnerability + Stun + Enfeeble = 3');
    eq(FF.enemyDebuffCount(nbSt(1,0)), 0, 'a foe with no debuffs -> count 0');
    eq(FF.enemyDebuffCount(nbSt(1,0,{curseUntil:vFuture})), 1, 'Curse counts as a woe now (Cursemark feeds the Litany)');
    eq(FF.enemyDebuffCount(nbSt(1,0,{decayUntil:vFuture,decayStacks:3})), 1, 'Decay counts as a woe now');
    // Litany of Woes, the always-on half (Lv40): +3% own damage per woe.
    var nbRes = stFor('nightblade',40,{ activity:{type:'combat', playerSwungOnce:true,monsterHp:100,enemyStunUntil:vFuture}, classDebuffs:{enemyDmgUntil:vFuture,enemyArmorUntil:0} });
    ok(Math.abs(FF.voidDmgMult(nbRes) - 1.06) < 1e-9, 'Litany (own-hit half): +3% x 2 woes = +6% (no Vulnerability)');
    eq(FF.voidDmgMult(stFor('nightblade',20,{activity:{type:'combat', playerSwungOnce:true,monsterHp:100,enemyStunUntil:vFuture},classDebuffs:{enemyDmgUntil:vFuture,enemyArmorUntil:0}})), 1, 'the Litany is inactive below Lv40');
    // Soul Tax (Lv60): +2% lifesteal AND +2% dark damage per distinct woe.
    var nbTax = stFor('nightblade',60,{ activity:{type:'combat', playerSwungOnce:true,monsterHp:100,enemyStunUntil:vFuture}, classDebuffs:{enemyDmgUntil:vFuture,enemyArmorUntil:0} });
    ok(Math.abs(FF.nightbladeLifestealPct(nbTax) - 0.04) < 1e-9, 'Soul Tax: +2% lifesteal x 2 woes = +4%');
    ok(Math.abs(FF.voidDmgMult(nbTax) - (1.06 * 1.04)) < 1e-9, 'Soul Tax stacks its +2%/woe dark damage atop the Litany');
    eq(FF.nightbladeLifestealPct(stFor('nightblade',40,{activity:{type:'combat', playerSwungOnce:true,monsterHp:100,enemyStunUntil:vFuture},classDebuffs:{enemyDmgUntil:vFuture,enemyArmorUntil:0}})), 0, 'Soul Tax lifesteal inactive below Lv60');
    // Removed helpers/perks: the old flat Hex, Shadowstep dodge, and Siphon lifesteal are gone.
    eq(FF.newClassDmgMult(monFull, stFor('nightblade',80)), FF.voidDmgMult(stFor('nightblade',80)), 'Voidshadow damage is driven entirely by voidDmgMult (no flat Hex)');
    ok(typeof FF.nightbladeDodgeBonus === 'undefined', 'Shadowstep dodge helper removed');
    ok(typeof FF.voidMarkPerHit === 'undefined', 'voidMarkPerHit retired (Malediction winds the Doom now)');
    // Executioner "the Falling Axe": The Falling Axe (Lv1) / Reap the Weak (Lv20) / Momentum of the
    // Cull (Lv40) / Headsman's Tally (Lv60) / The Cull (Lv80). The old defensive flats are all gone.
    var exNames = FF.CLASS_DEFS_BY_ID.executioner.passives.map(function(p){ return p.name; });
    eq(JSON.stringify(exNames), JSON.stringify(['The Falling Axe','Reap the Weak','Momentum of the Cull','Headsman\'s Tally','The Cull']), 'Executioner ladder is the Falling Axe five');
    // Reap the Weak reads the BLADE: +30% below the live Guillotine threshold on the activity.
    ok(Math.abs(FF.newClassDmgMult(monLow, stFor('executioner',20,{activity:{type:'combat', playerSwungOnce:true,monsterHp:10,exThresh:0.5}})) - 1.30) < 1e-9, 'Reap the Weak +30% vs a foe beneath the blade');
    eq(FF.newClassDmgMult(monLow, stFor('executioner',20,{activity:{type:'combat', playerSwungOnce:true,monsterHp:60,exThresh:0.5}})), 1, 'Reap is neutral above the blade');
    var exBlade = stFor('executioner',40,{activity:{type:'combat', playerSwungOnce:true,monsterHp:60,exThresh:0.70}});
    near(FF.executionerReapThreshold(exBlade), 0.70, 'the Reap threshold IS the climbing blade (act.exThresh)', 1e-9);
    ok(Math.abs(FF.newClassDmgMult(monLow, exBlade) - 1.30) < 1e-9, 'a raised blade widens the Reap window to a 60%-HP foe');
    eq(FF.executionerReapThreshold(stFor('executioner',20)), FF.EX_THRESH_FLOOR, 'no blade hung yet -> the threshold reads the floor');
    // The retired kit: Reaping Vigor, the kill Tally HP, Gallows Humor, the 2pc instant-kill and the
    // Emberwyrm fire-execute are all gone (the Falling Axe rework).
    ok(typeof FF.execVigorAddStack === 'undefined', 'Reaping Vigor retired (a defensive flat at ~100% BiS crit)');
    ok(typeof FF.execVigorMaxHpBonus === 'undefined', 'Vigor max-HP bonus retired');
    ok(typeof FF.headsmanTallyKill === 'undefined', 'the kill-count Tally retired (the Tally counts FALLS now)');
    ok(typeof FF.headsmanTallyBonusHp === 'undefined', 'Tally max-HP bonus retired');
    ok(typeof FF.executionerGallowsCrit === 'undefined', 'Gallows Humor retired (dead at capped crit)');
    ok(typeof FF.EXEC_SET_EXECUTE_FRAC === 'undefined', 'the D1 2pc instant-kill retired (Keen Rise now; The Cull executes)');
    ok(typeof FF.d4EmberwyrmExecutes === 'undefined', 'Emberwyrm\'s fire-execute retired (it amplifies Falls +40% now)');
    eq(FF.newClassCritChance(stFor('executioner',80)), 0, 'the Executioner grants no flat crit chance');
    eq(FF.newClassCritDmg(stFor('executioner',80)), 0, 'the Executioner grants no flat crit damage');
    // No class active -> every new-class multiplier is neutral.
    var none = { xp:{}, physique:{}, bodyArmor:{}, equippedMainhand:null, equippedOffhand:null, activity:{type:'combat', playerSwungOnce:true,monsterHp:100}, playerHp:1 };
    eq(FF.newClassDmgMult(monFull, none), 1, 'no class -> new-class dmg neutral');
    eq(FF.newClassCritChance(none), 0, 'no class -> new-class crit chance neutral');
    eq(FF.newClassCritDmg(none), 0, 'no class -> new-class crit dmg neutral');
    eq(FF.nightbladeLifestealPct(none), 0, 'no class -> no siphon');
    eq(FF.jgFuryCritDmg(none), 0, 'no class -> no Mounting Fury crit damage');
    eq(FF.jgResonanceMult(none), 1, 'no class -> Resonance neutral');
    eq(FF.jgFaultShred(none), 0, 'no class -> no Faultline shred');
    // enemyHpFrac reads current/max cleanly.
    ok(Math.abs(FF.enemyHpFrac({hp:100}, {activity:{monsterHp:40}}) - 0.4) < 1e-9, 'enemyHpFrac = current/max');
    eq(FF.enemyHpFrac({hp:0}, {activity:{monsterHp:0}}), 1, 'enemyHpFrac guards against a zero max');
  });

  // ---- Classes: Ranger (medium bow; imbued arrows stack Poison/Bleed/Chill/Burn -> Apex Predator x3) --
  suite('classes: Ranger', function(){
    ok(FF.CLASS_SKILL_IDS.indexOf('ranger') !== -1, 'ranger is a class skill id');
    var cd = FF.CLASS_DEFS_BY_ID.ranger; ok(cd, 'ranger class defined');
    eq(cd.passives.map(function(p){ return p.level; }).join(','), '1,20,40,60,80', 'passives at 1/20/40/60/80');
    ok(cd.reqParts.length >= 6, 'ranger has a full gear set');
    ok(/Medium Bow/.test(cd.reqText), 'ranger wields the Medium Bow');
    var fam = FF.FAMILIAR_DATA.ranger; ok(fam && fam.spells && fam.spells.length === 4, 'ranger familiar has a 4-spell kit');
    function lea(){ return { tier:1, rarity:'normal', material:'leather' }; }
    function clo(){ return { tier:1, rarity:'normal', material:'tailoring' }; }
    function rgear(){ return { xp:{ ranger: FF.xpFloorForLevel(85) }, physique:{}, equippedMainhand:'bowMedium', equippedOffhand:'quiver', bodyArmor:{ helmet:lea(), chest:lea(), gauntlets:lea(), boots:clo() } }; }
    eq(FF.activeClassId(rgear()), 'ranger', 'medium bow + quiver + leather + cloth boots => Ranger');
    var wrongBow = rgear(); wrongBow.equippedMainhand = 'bowLong';
    eq(FF.activeClassId(wrongBow), null, 'the Medium Bow is required (a long bow does not qualify)');
    // The Beastmaster: Apex Predator's x3-on-four-random-ailments retired. Damage now comes from the Quarry
    // ramp the pack builds itself (x Hunter's Mark on the D2 full set), which is deterministic and bandable.
    var mon = { hp:100 };
    var rgQ = rgear(); rgQ.activity = { type:'combat', playerSwungOnce:true, monsterHp:50 };
    ok(Math.abs(FF.newClassDmgMult(mon, rgQ) - 1) < 1e-9, 'no Quarry -> no Ranger damage row');
    FF.rgQuarryAdd(4, rgQ);
    eq(FF.rgQuarry(rgQ), 4, 'commanded strikes stack Quarry');
    near(FF.rgQuarryMult(rgQ), 1 + 4 * FF.RG_QUARRY_PCT, 'Pack Tactics: +3% per Quarry stack');
    near(FF.newClassDmgMult(mon, rgQ), 1 + 4 * FF.RG_QUARRY_PCT, 'and it is the class damage row');
    FF.rgQuarryAdd(99, rgQ);
    eq(FF.rgQuarry(rgQ), FF.RG_QUARRY_MAX, 'Quarry caps at 10');
    rgQ.activity.rgQuarryUntil = Date.now() - 1;
    eq(FF.rgQuarry(rgQ), 0, 'Quarry decays if the pack stops working');
    // A commanded strike is a share of your landed hit, plus Feral Bond's share of your weapon damage.
    var rgS = rgear(); rgS.activity = { type:'combat', playerSwungOnce:true, monsterHp:1e9, dotHitAvg: 1000 };
    near(FF.rgStrikeDamage(rgS), FF.RG_STRIKE_PCT * 1000, "Sic 'Em: a strike is 35% of the recent average hit");
    near(FF.rgBondBonus(rgS), FF.RG_BOND_PCT * 1000, 'Feral Bond adds a share of your weapon damage on top');
    var rgLow = rgear(); rgLow.xp.ranger = FF.xpFloorForLevel(41); rgLow.activity = { type:'combat', playerSwungOnce:true, monsterHp:1e9, dotHitAvg: 1000 };
    eq(FF.rgBondBonus(rgLow), 0, 'Feral Bond needs Lv80');
    var cd = FF.CLASS_DEFS_BY_ID.samurai; ok(cd, 'samurai class defined');
    eq(cd.passives.map(function(p){ return p.level; }).join(','), '1,20,40,60,80', 'passives at 1/20/40/60/80');
    ok(cd.reqParts.length >= 5, 'samurai has a full gear set');
    ok(/Katana/.test(cd.reqText), 'samurai wields the Katana');
    var fam = FF.FAMILIAR_DATA.samurai; ok(fam && fam.spells && fam.spells.length === 4, 'samurai familiar has a 4-spell kit');
    function lea(){ return { tier:1, rarity:'normal', material:'leather' }; }
    function sgear(lvl){ return { xp:{ samurai: FF.xpFloorForLevel(lvl||85) }, physique:{}, equippedMainhand:'falchion', equippedOffhand:null, bodyArmor:{ helmet:lea(), chest:lea(), gauntlets:lea(), boots:lea() } }; }
    eq(FF.activeClassId(sgear()), 'samurai', 'katana + full leather => Samurai');
    var wrongWpn = sgear(); wrongWpn.equippedMainhand = 'greatsword';
    eq(FF.activeClassId(wrongWpn), null, 'the Katana is required (a greatsword does not qualify)');
    var mon = { hp:100 };
    // Crimson Edge (Lv40): +30% damage vs a Bleeding foe (Focus held at 0 so Bushido is neutral).
    var bleeding = sgear(); bleeding.activity = { type:'combat', playerSwungOnce:true, monsterHp:60, bleedUntil: Date.now()+4000, bleedStacks:2, bleedDps:5, samuraiFocus:0 };
    ok(FF.enemyBleeding(bleeding), 'enemyBleeding true while bleedStacks+bleedUntil are live');
    ok(Math.abs(FF.newClassDmgMult(mon, bleeding) - 1.30) < 1e-9, 'Crimson Edge: x1.30 vs a Bleeding foe');
    var unbled = sgear(); unbled.activity = { type:'combat', playerSwungOnce:true, monsterHp:60, bleedUntil:0, bleedStacks:0, samuraiFocus:0 };
    eq(FF.newClassDmgMult(mon, unbled), 1, 'no Crimson Edge bonus vs an unbled foe (Focus 0)');
    // Bushido (Lv60): +5% damage per Focus stack (no bleed, so Crimson is off).
    var focus = sgear(); focus.activity = { type:'combat', playerSwungOnce:true, monsterHp:60, bleedUntil:0, bleedStacks:0, samuraiFocus:4 };
    eq(FF.samuraiFocusStacks(focus), 4, 'samuraiFocusStacks reads the activity');
    ok(Math.abs(FF.newClassDmgMult(mon, focus) - 1.20) < 1e-9, 'Bushido: 4 Focus stacks => x1.20 damage');
    // Bushido also carries the crit (it absorbed the old Lv80 Zanshin line): +1.5% per Focus stack.
    ok(Math.abs(FF.newClassCritChance(focus) - 4*0.015) < 1e-9, 'Bushido: 4 Focus stacks => +6% crit chance');
    // Below Lv60 the Focus perks are inert even with stacks present.
    var lowLvl = sgear(45); lowLvl.activity = { type:'combat', playerSwungOnce:true, monsterHp:60, bleedUntil:0, bleedStacks:0, samuraiFocus:4 };
    eq(FF.newClassDmgMult(mon, lowLvl), 1, 'no Bushido damage below Class Lv60');
    eq(FF.newClassCritChance(lowLvl), 0, 'no Bushido crit below Class Lv60');

    // ---- The Draw-Cut cycle (the rework) --------------------------------------------------------
    // The stance is a FIXED ten: capacity is a dead axis on a cycling engine, so nothing raises it.
    eq(FF.samuraiFocusCap(sgear()), FF.SAMURAI_FOCUS_MAX, 'the stance caps at SAMURAI_FOCUS_MAX');
    var empty = sgear(); empty.activity = { type:'combat', playerSwungOnce:true, monsterHp:60, samuraiFocus:0, dotHitAvg:1000 };
    var full  = sgear(); full.activity  = { type:'combat', playerSwungOnce:true, monsterHp:60, samuraiFocus:FF.SAMURAI_FOCUS_MAX, dotHitAvg:1000 };
    ok(!FF.smSheathed(empty), 'an empty stance is not sheathed');
    ok(FF.smSheathed(full), 'a full stance is sheathed -- the next strike draws');
    // The Cut scales off the recent-hit EMA (dotBase), per stack spent. This is what makes SM_SWING_MULT
    // the single band knob: the swings feed the EMA, and the EMA is the Cut.
    near(FF.smCutDamage(full), FF.SAMURAI_FOCUS_MAX * FF.SM_CUT_PCT * 1000, 'a full-stance Cut = 10 Focus x SM_CUT_PCT x the recent average hit');
    eq(FF.smCutDamage(empty), 0, 'no stance, no Cut');
    var half = sgear(); half.activity = { type:'combat', playerSwungOnce:true, monsterHp:60, samuraiFocus:5, dotHitAvg:1000 };
    near(FF.smCutDamage(half), 5 * FF.SM_CUT_PCT * 1000, 'a half stance cuts for half -- the Cut pays for what it spent');
    // Zanshin (Lv80) is a RATE capstone: it leaves residual stance so the next cycle is shorter.
    eq(FF.smCutRefund(sgear(45)), 0, 'below Lv80 a Cut empties the stance');
    eq(FF.smCutRefund(sgear(85)), FF.SM_ZANSHIN_REFUND, 'Zanshin leaves SM_ZANSHIN_REFUND Focus behind');
    ok(FF.smCutRefund(sgear(85)) < FF.samuraiFocusCap(sgear()), 'the refund can never leave a FULL stance, which would re-fire the Cut forever');
    // The stance clock accrues fractionally so it is tick-rate independent, but samuraiFocus stays an INTEGER
    // (the UI readout and every pre-existing reader expect one).
    var acc = sgear(); acc.activity = { type:'combat', playerSwungOnce:true, monsterHp:60, samuraiFocus:0 };
    eq(FF.smFocusAdd(0.4, acc), 0, 'four tenths of a stack builds nothing yet');
    eq(acc.activity.samuraiFocus, 0, 'and the stack count is still an integer 0');
    eq(FF.smFocusAdd(0.7, acc), 1, 'but the remainder is banked and carries past 1');
    eq(acc.activity.samuraiFocus, 1, 'one whole stack now held');
    FF.smFocusAdd(9999, acc);
    eq(acc.activity.samuraiFocus, FF.samuraiFocusCap(acc), 'the stance fills to the cap and no further');
  });

  // ---- Classes: gear-requirement UI renders in a standardized slot order ------------------
  suite('classes: standardized gear order', function(){
    // Slot derivation from the part label: weapon(0) -> offhand(1) -> helm(2) -> chest(3) -> gloves(4) -> boots(5).
    eq(FF.classPartSlotRank('Rapier'), 0, 'a weapon is slot 0');
    eq(FF.classPartSlotRank('Staff'), 0, 'a staff is slot 0');
    eq(FF.classPartSlotRank('Claws (off-hand)'), 1, 'an off-hand claw is the offhand slot');
    eq(FF.classPartSlotRank('Small Shield'), 1, 'a shield is the offhand slot');
    eq(FF.classPartSlotRank('Ward'), 1, 'a ward is the offhand slot');
    eq(FF.classPartSlotRank('Quiver'), 1, 'a quiver is the offhand slot');
    eq(FF.classPartSlotRank('Warhammer'), 0, 'a warhammer is a weapon, not an offhand (no false "ward" match)');
    eq(FF.classPartSlotRank('Bare Head'), 2, 'bare head is the helm slot');
    eq(FF.classPartSlotRank('Chain Helm'), 2, 'a helm is slot 2');
    eq(FF.classPartSlotRank('Cloth Tunic'), 3, 'a tunic is the chest slot');
    eq(FF.classPartSlotRank('Plate Gloves'), 4, 'gloves are slot 4');
    eq(FF.classPartSlotRank('Cloth Shoes'), 5, 'shoes are the boots slot');
    // Every class renders its gear weapon-first, in non-decreasing slot order.
    FF.CLASS_DEFS.forEach(function(cd){
      var ranks = FF.classPartsInSlotOrder(cd.reqParts).map(function(p){ return FF.classPartSlotRank(p.label); });
      eq(ranks[0], 0, cd.id + ': the weapon renders first');
      var nonDecreasing = ranks.every(function(r, i){ return i === 0 || r >= ranks[i-1]; });
      ok(nonDecreasing, cd.id + ': gear parts render in canonical slot order');
    });
    // Concrete example: Treasure Hunter declares helm/boots/chest/gloves out of order; it renders sorted.
    var th = FF.CLASS_DEFS_BY_ID.treasureHunter;
    eq(FF.classPartsInSlotOrder(th.reqParts).map(function(p){ return p.label; }).join(' | '),
       'Scimitar | Small Shield | Chain Helm | Plate Chest | Cloth Gloves | Chain Boots',
       'Treasure Hunter gear reorders to weapon/offhand/helm/chest/gloves/boots');
  });

  // ---- Dungeons: D1 "Cave" (25 arachnids, L100->125, ~10x boss, threat targeting) ---------
  // ---- Tier curves must not reverse direction --------------------------------------------------
  // Balance II had to fix FIVE shipped tier inversions -- higher tiers weaker than lower ones. That's
  // a mechanical property, so check it mechanically instead of catching it in a later balance pass.
  //
  // Deliberately NOT asserting "every stat increases": some fields legitimately fall with tier (costs,
  // timers, penalties). What is never legitimate is a curve that REVERSES -- rises then falls, or falls
  // then rises. So walk each tier-data function across all tiers and flag any numeric field whose
  // direction flips. Flat stretches are fine (many curves plateau).
  suite('balance: tier curves never reverse direction', function(){
    var TC = FF.TIER_COUNT;
    ok(TC > 1, 'TIER_COUNT is available');
    // Only unambiguous POWER stats. Deliberately narrow: costs, timers and input counts can legitimately
    // fall or plateau, and flagging those would red-CI on correct data. These are fields where a higher
    // tier being worse than a lower one is always a bug. Widen the list as families are confirmed clean.
    var POWER = { xp:1, sell:1, levelReq:1, defense:1, reflect:1, bonus:1, dmgBonus:1, ammoPreserve:1, dmgMin:1, dmgMax:1 };
    function directionOf(vals){          // +1 rising, -1 falling, 0 flat -- ignoring equal steps
      for(var i = 1; i < vals.length; i++){ if(vals[i] > vals[i-1]) return 1; if(vals[i] < vals[i-1]) return -1; }
      return 0;
    }
    function checkCurve(label, getAt){
      var rows = [];
      for(var t = 0; t < TC; t++){ var d = null; try { d = getAt(t); } catch(e){ d = null; } if(d) rows.push(d); }
      if(rows.length < 2) return;        // nothing to compare (family may not span all tiers)
      var fields = {};
      rows.forEach(function(r){ for(var k in r){ if(POWER[k] && typeof r[k] === 'number' && isFinite(r[k])) fields[k] = 1; } });
      Object.keys(fields).forEach(function(k){
        var vals = rows.map(function(r){ return typeof r[k] === 'number' ? r[k] : null; });
        if(vals.some(function(v){ return v === null; })) return;   // field not present at every tier
        var dir = directionOf(vals), bad = -1;
        for(var i = 1; i < vals.length && dir !== 0; i++){
          var step = vals[i] > vals[i-1] ? 1 : (vals[i] < vals[i-1] ? -1 : 0);
          if(step !== 0 && step !== dir){ bad = i; break; }
        }
        ok(bad === -1, label + '.' + k + ' is monotonic across tiers' +
          (bad === -1 ? '' : ' (reverses at tier ' + bad + ': ' + vals[bad-1] + ' -> ' + vals[bad] + ')'));
      });
    }
    // Families whose type list AND tier-data fn are both exported.
    (FF.WARD_TYPES || []).forEach(function(w){ checkCurve('ward:' + w.id, function(t){ return FF.getWardTierData(w.id, t); }); });
    (FF.RING_TYPES || []).forEach(function(r){ checkCurve('ring:' + r.id, function(t){ return FF.getRingTierData(r.id, t); }); });
    (FF.AMULET_TYPES || []).forEach(function(a){ checkCurve('amulet:' + a.id, function(t){ return FF.getAmuletTierData(a.id, t); }); });
    // Single-argument families.
    if(FF.getBeltTierData) checkCurve('belt', function(t){ return FF.getBeltTierData(t); });
    if(FF.getCottageTierData) checkCurve('cottage', function(t){ return FF.getCottageTierData(t); });
  });

  // ---- The enemy card and live combat share ONE damage chain -----------------------------------
  // The card preview used to MIRROR monsterAttackTick's ~20 reducers with only a comment keeping them
  // in step. It drifted twice: D2/D3 set reducers and the Tunnelborn cloak reached combat but not the
  // card, so cards overstated incoming damage for anyone wearing them. Both now call incomingDamageMult.
  suite('combat: card preview and live chain share one reduction fn', function(){
    var s = FF._state;
    ok(typeof FF.incomingDamageMult === 'function', 'incomingDamageMult is exported as the single source');
    var foe = { name:'T', atkMin:100, atkMax:200, attackTypes:{blunt:1}, armorTypes:{blunt:1}, element:null };
    var mult = FF.incomingDamageMult(s, foe, foe.attackTypes);
    ok(typeof mult === 'number' && isFinite(mult) && mult > 0, 'the chain yields a positive finite multiplier');
    // The card must be derivable from that same multiplier: reproduce its per-hit math independently
    // and require it to match. If someone re-inlines a private chain in either place, this fails.
    var prof = FF.playerDefenseProfile(s);
    var r = FF.enemyDamageRangeVsPlayer(foe, s, prof);
    function expected(raw){
      var reduced = FF.incomingMitigationFloor(Math.round(raw * mult), raw);
      return Math.max(1, Math.round((reduced - prof.armorDefense) / prof.tenacity));
    }
    eq(r.min, expected(foe.atkMin), 'card min equals the shared chain applied to atkMin');
    eq(r.max, expected(foe.atkMax), 'card max equals the shared chain applied to atkMax');
    // The floor is part of the shared path: an absurdly mitigated hit still lands >= the floor share.
    eq(FF.incomingMitigationFloor(0, 200), Math.round(200 * FF.INCOMING_FLOOR_FRAC), 'a fully-reduced swing floors at INCOMING_FLOOR_FRAC of the roll');
    eq(FF.incomingMitigationFloor(500, 200), 500, 'the floor never REDUCES a hit that already exceeds it');
  });

  // ---- One unique can never fill both hands ---------------------------------------------------
  // Regression: once unique Claws became off-hand-equippable, equipping the SAME Claw into the main
  // hand left the off-hand pointing at it too. equippedEnchantTotals adds both hands, so its enchants
  // were counted twice (enhance multiplier included) -- a stat-duplication exploit, not just a display
  // glitch.
  suite('uniques: the same item cannot occupy both hands', function(){
    var s = FF._state;
    var savedU = s.uniqueItems, savedMain = s.equippedMainhandUid, savedOff = s.equippedOffhandUid;
    var savedMainId = s.equippedMainhand, savedOffId = s.equippedOffhand, savedXp = s.xp;
    // A tier-0 Claw with one known enchant, so double-counting is unmistakable in the totals.
    var mod = (FF.ENCHANT_MODS && FF.ENCHANT_MODS.weapon && FF.ENCHANT_MODS.weapon[0]) || null;
    if(mod){
      s.uniqueItems = { c1:{ uid:'c1', base:'stweapon_claw_t0_normal', kind:'weapon', tier:0, rarity:'normal', enhance:0, enchants:[{ mod:mod.id, roll:10 }] } };
      s.xp = Object.assign({}, s.xp, { claw: 1000000 });   // clear the proficiency gate
      s.equippedMainhand = 'claw'; s.equippedMainhandTier = 1; s.equippedMainhandUid = null;
      s.equippedOffhand = 'claw';  s.equippedOffhandTier = 1; s.equippedOffhandUid = 'c1';
      var single = FF.equippedEnchantTotals(s)[mod.stat] || 0;
      eq(single, 10, 'one equipped copy contributes its roll once');
      FF.equipUniqueWeapon('c1');                      // equip the very item already in the off-hand
      eq(s.equippedOffhandUid, null, 'equipping it into the main hand frees the off-hand');
      eq(s.equippedMainhandUid, 'c1', 'it is now in the main hand');
      eq(FF.equippedEnchantTotals(s)[mod.stat] || 0, 10, 'its enchant is still counted ONCE, not doubled');
    }
    s.uniqueItems = savedU; s.equippedMainhandUid = savedMain; s.equippedOffhandUid = savedOff;
    s.equippedMainhand = savedMainId; s.equippedOffhand = savedOffId; s.xp = savedXp;
  });

  // ---- CRAFT FAMILY REGISTRY INTEGRITY (Stage 0) ----------------------------------------------
  // A craft family has to be registered in ~12 hand-maintained places. A family present in 11 of 12
  // is invisible, which is how 'ward' went missing from matchesSpecialCraft and 'ring'/'amulet' from
  // the live inputs updater -- both shipped to players. CRAFT_FAMILIES states each family once; these
  // assertions prove it still agrees with every hand-written list, so an incomplete family fails here
  // instead of in someone's game. Nothing consumes the registry yet -- this is the safety net first.
  suite('craft families: registry matches every hand-written list', function(){
    var F = FF.CRAFT_FAMILIES;
    ok(F && typeof F === 'object', 'CRAFT_FAMILIES is exported');
    var kinds = Object.keys(F);
    eq(kinds.length, 13, 'all 13 craft families are described');   // +building (v0.0.90.0, the estate buildings)

    // 1) Every family is MATCHABLE, using the match keys the registry claims. This is the exact
    //    failure ward had: startable but never matchable, so its card never showed Stop.
    var sample = { skillId:'mining', typeId:'sword', tierIndex:3, material:'plate', slot:'chest', buildingKey:'apiary' };
    kinds.forEach(function(kind){
      var act = { type:'craft', craftKind:kind }, params = {};
      F[kind].match.forEach(function(k){ act[k] = sample[k]; params[k] = sample[k]; });
      eq(FF.matchesSpecialCraft(act, kind, params), true, kind + ': matchable via its declared match keys');
      // and a differing value on the FIRST match key must NOT match, or every card would show Stop.
      var k0 = F[kind].match[0], bad = {};
      F[kind].match.forEach(function(k){ bad[k] = sample[k]; });
      bad[k0] = (k0 === 'tierIndex') ? 99 : 'zzz-not-a-real-value';
      eq(FF.matchesSpecialCraft(act, kind, bad), false, kind + ': a different ' + k0 + ' does not match');
    });

    // 2+3) SPECIAL_DOUBLEABLE_KINDS and STACKABLE_SAC_CATEGORIES are now DERIVED from the registry,
    //      so comparing them back to it would be tautological. Pin the expected contents here instead
    //      -- an independent copy, so a wrong flag in the registry changes the derived list and fails.
    var EXPECTED_DOUBLEABLE = ['amulet','belt','bodyarmor','ring','stackquiver','stackshield','stackweapon','tool','ward','workshop'];
    eq((FF.SPECIAL_DOUBLEABLE_KINDS || []).slice().sort().join(','), EXPECTED_DOUBLEABLE.slice().sort().join(','),
       'derived SPECIAL_DOUBLEABLE_KINDS still holds exactly the 10 doubleable families');
    var EXPECTED_SAC = ['amulet','belt','relic','ring','stackquiver','stackshield','stackweapon','tool'];
    eq((FF.STACKABLE_SAC_CATEGORIES || []).slice().sort().join(','), EXPECTED_SAC.slice().sort().join(','),
       'derived STACKABLE_SAC_CATEGORIES still holds the 7 sacrificeable families plus relic');
    ok((FF.STACKABLE_SAC_CATEGORIES || []).indexOf('relic') !== -1, "'relic' survives derivation (a drop, not a craft family)");
    // cottage/offhand must NOT be doubleable -- they were the two false flags, easy to flip by accident.
    ok((FF.SPECIAL_DOUBLEABLE_KINDS || []).indexOf('cottage') === -1, 'cottage is not doubleable');
    ok((FF.SPECIAL_DOUBLEABLE_KINDS || []).indexOf('offhand') === -1, 'offhand is not doubleable');

    // 4) Every card's tier-stepper target must exist, or its +/- stepper silently does nothing.
    kinds.forEach(function(kind){
      (F[kind].cards || []).forEach(function(card){
        if(card.tierTarget === null) return;   // offhand has no tier stepper
        ok(!!FF.TIER_STEP_TARGETS[card.tierTarget], kind + ': tier target "' + card.tierTarget + '" exists in TIER_STEP_TARGETS');
      });
    });

    // 5) Lock the set of families lacking a live inputs updater. ring/amulet were in this state and
    //    their material counts lagged several crafts; a NEW family landing here must fail loudly.
    var noLive = kinds.filter(function(k){
      return (F[k].cards || []).every(function(c){ return !c.idPrefix; });
    }).sort();
    eq(noLive.join(','), (FF.CRAFT_FAMILIES_WITHOUT_LIVE_INPUTS || []).slice().sort().join(','),
       'the set of families without a live inputs updater is unchanged (belt, cottage, offhand)');

    // 6) Every family declares at least one card and at least one match key.
    kinds.forEach(function(kind){
      ok((F[kind].cards || []).length > 0, kind + ': declares at least one UI card');
      ok((F[kind].match || []).length > 0, kind + ': declares at least one match key');
    });
  });

  // ---- Every special craft kind must be matchable ---------------------------------------------
  // Regression: 'ward' (Runesmithing) was missing from matchesSpecialCraft, so a running ward craft
  // could never be found by its card -- the Inscribe button never became Stop and the progress bar
  // never filled. A kind that can be STARTED but not MATCHED is always this bug, so pin all of them.
  // ---- Jewelrycrafting: rings/amulets get the Gross Motor "all crafts" success passive (like Twine) ----
  suite('jewelrycrafting: rings/amulets get the craft-success passive', function(){
    var g = FF._state;
    var sv = { gm:g.physique.grossMotor, ct:g.craftTools && g.craftTools.jewelrycrafting };
    try {
      if(!g.craftTools) g.craftTools = {};
      g.craftTools.jewelrycrafting = 0; // no craft tool -> isolate the physique passive from the tool bonus / the 100% clamp
      // Level Gross Motor high so the "all crafts" passive is substantial (and well below the 100% clamp).
      g.physique.grossMotor = FF.xpFloorForLevel(50);
      var passive = FF.grossMotorCraftSuccessBonus(g);
      ok(passive > 0.1, 'Gross Motor gives a substantial craft-success passive at high level');
      var jrHigh = FF.jewelrySuccessRate(g);
      var twHigh = FF.craftSuccessRate(g, 'jewelrycrafting'); // Twine path (regular jewelrycrafting craft)
      // The bug: rings/amulets ignored the passive. Now ring/amulet success = jewelry base (0.5) + the
      // passive, and Twine = craft base (0.7) + the SAME passive -- they differ only by their base.
      near(jrHigh, 0.5 + passive, 'ring/amulet success = jewelry base (0.5) + the Gross Motor passive');
      near(twHigh, 0.7 + passive, 'Twine = craft base (0.7) + the SAME passive');
      near(twHigh - jrHigh, 0.2, 'the two differ only by their base (0.7 vs 0.5), not the passive');
    } finally { g.physique.grossMotor = sv.gm; if(sv.ct===undefined) delete g.craftTools.jewelrycrafting; else g.craftTools.jewelrycrafting = sv.ct; }
  });

  suite('crafting: special craft kinds are all matchable', function(){
    ok(typeof FF.matchesSpecialCraft === 'function', 'matchesSpecialCraft is exported');
    // One representative activity per kind, shaped exactly as its craft* function creates it.
    var cases = [
      { kind:'tool',        act:{ skillId:'mining', tierIndex:3 },                       params:{ skillId:'mining', tierIndex:3 } },
      { kind:'stackweapon', act:{ typeId:'sword', tierIndex:4 },                         params:{ typeId:'sword', tierIndex:4 } },
      { kind:'stackshield', act:{ typeId:'shieldSmall', tierIndex:2 },                   params:{ typeId:'shieldSmall', tierIndex:2 } },
      { kind:'stackquiver', act:{ typeId:'quiver', tierIndex:1 },                        params:{ typeId:'quiver', tierIndex:1 } },
      { kind:'ward',        act:{ typeId:'wardFire', tierIndex:5 },                      params:{ typeId:'wardFire', tierIndex:5 } },
      { kind:'bodyarmor',   act:{ material:'plate', slot:'chest', tierIndex:6 },         params:{ material:'plate', slot:'chest', tierIndex:6 } },
      { kind:'belt',        act:{ tierIndex:7 },                                         params:{ tierIndex:7 } },
      { kind:'offhand',     act:{ typeId:'torch' },                                      params:{ typeId:'torch' } },
      { kind:'ring',        act:{ typeId:'plain', tierIndex:2 },                         params:{ typeId:'plain', tierIndex:2 } },
      { kind:'amulet',      act:{ typeId:'plain', tierIndex:2 },                         params:{ typeId:'plain', tierIndex:2 } },
      { kind:'workshop',    act:{ skillId:'mining', tierIndex:1 },                       params:{ skillId:'mining', tierIndex:1 } },
      { kind:'cottage',     act:{ tierIndex:3 },                                         params:{ tierIndex:3 } }
    ];
    cases.forEach(function(c){
      var act = Object.assign({ type:'craft', craftKind:c.kind }, c.act);
      eq(FF.matchesSpecialCraft(act, c.kind, c.params), true, c.kind + ': a running craft matches its own card');
    });
    // A different tier / type must NOT match, or every card would show Stop at once.
    eq(FF.matchesSpecialCraft({ type:'craft', craftKind:'ward', typeId:'wardFire', tierIndex:5 }, 'ward', { typeId:'wardFire', tierIndex:6 }), false, 'ward: a different tier does not match');
    eq(FF.matchesSpecialCraft({ type:'craft', craftKind:'ward', typeId:'wardFire', tierIndex:5 }, 'ward', { typeId:'wardWater', tierIndex:5 }), false, 'ward: a different element does not match');
    // Amulet carries a legacy 'plain' fallback: an omitted typeId on EITHER side means plain. The
    // generic matcher has to preserve that or plain-amulet cards stop matching their own craft.
    eq(FF.matchesSpecialCraft({ type:'craft', craftKind:'amulet', tierIndex:2 }, 'amulet', { typeId:'plain', tierIndex:2 }), true, 'amulet: omitted typeId on the activity means plain');
    eq(FF.matchesSpecialCraft({ type:'craft', craftKind:'amulet', typeId:'plain', tierIndex:2 }, 'amulet', { tierIndex:2 }), true, 'amulet: omitted typeId in the params means plain');
    eq(FF.matchesSpecialCraft({ type:'craft', craftKind:'amulet', typeId:'warding', tierIndex:2 }, 'amulet', { tierIndex:2 }), false, 'amulet: a warding amulet does not match the plain card');
    // An unregistered kind can't match anything (previously the switch's default `return false`).
    eq(FF.matchesSpecialCraft({ type:'craft', craftKind:'notafamily', tierIndex:1 }, 'notafamily', { tierIndex:1 }), false, 'an unregistered craft kind never matches');
    eq(FF.matchesSpecialCraft(null, 'ward', { typeId:'wardFire', tierIndex:5 }), false, 'a null activity matches nothing');
    eq(FF.matchesSpecialCraft({ type:'gather' }, 'ward', { typeId:'wardFire', tierIndex:5 }), false, 'a non-craft activity matches nothing');
  });

  // ---- Destroying a unique must never leave it "equipped" -------------------------------------
  // Regression: a shattered Enhancement only cleared the MAINHAND, so a destroyed offhand / armour /
  // ring / amulet stayed equipped -- still drawn, still satisfying its class requirement.
  suite('uniques: destroying one clears every slot', function(){
    var s = FF._state;
    var savedU = s.uniqueItems, savedArmor = s.bodyArmor, savedJewel = s.jewelrySlots;
    var savedBelt = s.equippedBeltUid, savedRelic = s.equippedRelicUid, savedMain = s.equippedMainhandUid;
    // Each case: put a uid in a slot, destroy it, assert nothing still references it.
    function destroyedFromSlot(label, place, check){
      s.uniqueItems = {}; s.uniqueItems['u1'] = { uid:'u1', base:'stweapon_sword_t5_rare', kind:'weapon', tier:5, rarity:'rare', enhance:0, enchants:[] };
      place('u1');
      ok(FF.uniqueIsEquipped('u1'), label + ': starts equipped');
      FF.removeUnique('u1');
      eq(!!(s.uniqueItems && s.uniqueItems['u1']), false, label + ': removed from the unique table');
      eq(FF.uniqueIsEquipped('u1'), false, label + ': no slot still points at it');
      if(check) check(label);
    }
    s.bodyArmor = s.bodyArmor || {}; s.jewelrySlots = s.jewelrySlots || {};
    destroyedFromSlot('mainhand', function(uid){ s.equippedMainhandUid = uid; });
    destroyedFromSlot('body armour', function(uid){ s.bodyArmor.chest = { uid:uid, tier:5, rarity:'rare', material:'plate' }; },
      function(l){ eq(s.bodyArmor.chest.uid, null, l + ': the armour slot is emptied, not left half-set'); });
    destroyedFromSlot('amulet', function(uid){ s.jewelrySlots.amulet = { uid:uid, tier:5, rarity:'rare' }; });
    destroyedFromSlot('belt', function(uid){ s.equippedBeltUid = uid; });
    destroyedFromSlot('relic', function(uid){ s.equippedRelicUid = uid; });
    // Destroying something that was never equipped must still drop it, and not throw.
    s.uniqueItems = { u2:{ uid:'u2', base:'stweapon_sword_t1_normal', kind:'weapon', tier:1, rarity:'normal' } };
    FF.removeUnique('u2');
    eq(!!s.uniqueItems['u2'], false, 'an unequipped unique is still removed');
    FF.removeUnique(null); FF.removeUnique('nope');   // must be no-ops, not crashes
    ok(true, 'removing a null / unknown uid is a safe no-op');
    s.uniqueItems = savedU; s.bodyArmor = savedArmor; s.jewelrySlots = savedJewel;
    s.equippedBeltUid = savedBelt; s.equippedRelicUid = savedRelic; s.equippedMainhandUid = savedMain;
  });

  // ---- Enemy cards: the "damage to YOU" range (post-mitigation, current gear) ------------------
  suite('combat: enemy damage vs player', function(){
    var s = FF._state;
    var foe = { name:'Test Foe', atkMin:100, atkMax:200, attackTypes:{blunt:1}, armorTypes:{blunt:1}, element:null };
    ok(typeof FF.enemyDamageRangeVsPlayer === 'function', 'enemyDamageRangeVsPlayer is exported');
    ok(typeof FF.playerDefenseProfile === 'function', 'playerDefenseProfile is exported');
    var r = FF.enemyDamageRangeVsPlayer(foe, s);
    ok(r && typeof r.min === 'number' && typeof r.max === 'number', 'returns a {min,max} pair');
    ok(r.min >= 1 && r.max >= 1, 'a landed hit is always at least 1 (never zero/negative)');
    ok(r.min <= r.max, 'min never exceeds max');
    // Mitigation LOWERS the landed hit: the same foe lands strictly less on an armoured profile than a
    // bare one. Note "never exceeds raw" is NOT an invariant -- a bad type/element matchup multiplies the
    // hit above raw (weightedAdvantage averages >1), exactly as monsterAttackTick does, so the honest
    // displayed number can top the foe's raw max on a poor matchup. What must hold is that armour reduces it.
    var _neutralMix = { slashing:1/3, piercing:1/3, blunt:1/3 };
    var _bareProf = { armorDefense:0, offhandStyle:null, offhandItem:null, offhandProf:1, armorMix:_neutralMix, shieldProf:1, flat:1, tenacity:1 };
    var _armProf  = { armorDefense:60, offhandStyle:null, offhandItem:null, offhandProf:1, armorMix:_neutralMix, shieldProf:1, flat:1, tenacity:1 };
    var _bareMax = FF.enemyDamageRangeVsPlayer(foe, s, _bareProf).max;
    var _armMax  = FF.enemyDamageRangeVsPlayer(foe, s, _armProf).max;
    ok(_armMax < _bareMax, 'armour mitigates: the same foe lands less on an armoured profile');
    ok(_armMax < foe.atkMax, 'a well-armoured profile takes less than the foe\'s raw max');
    // Harder-hitting foe -> strictly larger (or equal, if both floor at 1) landed damage.
    var big = FF.enemyDamageRangeVsPlayer({ name:'Big', atkMin:1000, atkMax:2000, attackTypes:{blunt:1}, armorTypes:{blunt:1}, element:null }, s);
    ok(big.max >= r.max, 'a foe with higher raw damage lands at least as much on the same gear');
    // Passing a precomputed profile (what the card grid does) must match computing it inline.
    var prof = FF.playerDefenseProfile(s);
    var viaProf = FF.enemyDamageRangeVsPlayer(foe, s, prof);
    eq(viaProf.min, r.min, 'precomputed profile gives the same min as an inline profile');
    eq(viaProf.max, r.max, 'precomputed profile gives the same max as an inline profile');
    eq(FF.enemyDamageRangeVsPlayer(null, s).max, 0, 'a null foe yields a zero range (no crash)');
  });

  // ---- Death chronicle: a detailed "final hit" line when the player is slain ----
  suite('combat: death chronicle explains the final hit', function(){
    ok(typeof FF.deathBlowChronicle === 'function', 'deathBlowChronicle is exported');
    var foe = { name:'Obsidian Elemental', damageType:'piercing', element:'light' };
    // Killed by a hit that landed 42 after soaking 18 of a 60 raw swing, from 30 HP, with a Block.
    var line = FF.deathBlowChronicle(foe, 42, 60, 18, true, 30);
    ok(/Obsidian Elemental/.test(line), 'names the foe that killed you');
    ok(/42/.test(line), 'reports the final hit damage');
    ok(/Light/.test(line) && /Piercing/.test(line), 'reports the damage element and type');
    ok(/raw 60/.test(line) && /18 soaked/.test(line), 'reports the raw swing and how much armour/shield soaked');
    ok(/Blocked/.test(line), 'notes a Block');
    ok(/fell from 30 HP/.test(line), 'reports the Health you fell from');
    // A clean hit with no mitigation and no element: still coherent, no "raw" clause, physical type.
    var plain = FF.deathBlowChronicle({ name:'Rabbit' }, 10, 10, 0, false, 10);
    ok(/Rabbit/.test(plain) && /10/.test(plain) && /physical/.test(plain), 'handles a plain physical kill');
    ok(!/soaked/.test(plain), 'omits the mitigation clause when nothing was soaked');
    // No crash / sane output on a missing foe.
    ok(typeof FF.deathBlowChronicle(null, 5, 5, 0, false, 5) === 'string', 'tolerates a missing foe');
  });

  // ---- Death resets HP to 1, not 0 (no 0-HP re-entry window) ----
  suite('combat: a death lands you at 1 HP, alive and recovering', function(){
    var S = FF._state;
    var saved = { act:S.activity, hp:S.playerHp, deaths:(S.stats&&S.stats.deaths)||0 };
    try {
      // A tier-20 Tower foe hits for hundreds -- a lethal blow from 1 HP, guaranteed to trip the death path.
      var mon = FF.buildTowerMonster('all', 20);
      FF.startCombat(mon.id);
      ok(S.activity.type === 'combat', 'the fight started');
      var died = false;
      for(var i=0;i<80 && !died;i++){
        S.playerHp = 1;                 // sit at 1 HP; the next landed hit is lethal
        FF.monsterAttackTick();
        if(S.activity.type === null) died = true; // the death handler ends the fight
      }
      ok(died, 'a lethal hit triggered the death handler');
      eq(S.playerHp, 1, 'HP resets to 1 after death (not 0), so there is no 0-HP re-entry window');
      eq(S.activity.type, null, 'the fight ends on death');
    } finally {
      S.activity = saved.act; S.playerHp = saved.hp; if(S.stats) S.stats.deaths = saved.deaths;
    }
  });

  // ---- Battle IA: a live-fight "Combat" tab, split from an "Enemies" selection tab ---------------
  suite('battle tabs: Combat (live fight) vs Enemies (selection)', function(){
    ok(typeof FF.renderCombatTab === 'function' && typeof FF.renderEnemiesTab === 'function', 'both battle tabs exported');
    var battle = FF.AREAS.filter(function(a){ return a.id==='battle'; })[0];
    var subIds = battle.subs.map(function(x){ return x[0]; });
    ok(subIds.indexOf('enemies') !== -1 && subIds.indexOf('combat') !== -1, 'Battle exposes both Enemies and Combat tabs');
    ok(subIds.indexOf('enemies') < subIds.indexOf('combat'), 'Enemies is listed before Combat');
    var s = FF._state, savedAct = s.activity;
    try {
      s.activity = { type:null, tier:0 };  // out of combat
      var enemiesHtml = FF.renderEnemiesTab();
      ok(/data-action="fight"/.test(enemiesHtml), 'the Enemies tab lists foes with Fight buttons');
      var combatHtml = FF.renderCombatTab();
      ok(!/data-action="fight"/.test(combatHtml), 'the Combat tab has NO enemy Fight buttons (moved to Enemies)');
      ok(/Enemies/.test(combatHtml), 'the idle Combat tab points players to the Enemies tab');
      // Consumable prep (Auto-Eat + potions + feasts) belongs to Combat only -- it used to render on BOTH
      // tabs. Combat must carry it out of combat too, or a potion could only be armed mid-fight.
      ok(!/Auto-Eat/.test(enemiesHtml), 'the Enemies tab no longer duplicates the Auto-Eat panel');
      ok(!/Combat Potions/.test(enemiesHtml), 'the Enemies tab no longer duplicates the Combat Potions panel');
      ok(/Auto-Eat/.test(combatHtml), 'the idle Combat tab carries Auto-Eat');
      ok(/Combat Potions/.test(combatHtml), 'the idle Combat tab carries Combat Potions (pre-fight prep)');
      ok(/data-action="activatePotion"|No combat consumables/.test(combatHtml), 'potions are armable out of combat');

      // The full stats panel (Offense/Defense/Mastery/Damage Triangle) belongs to Equipment & Stats ONLY
      // (v0.0.77.9, owner request). The Combat tab duplicated it wholesale under every fight -- a screen and
      // a half of static numbers on a phone. It must be absent idle, in a live fight, and mid-dungeon, while
      // the panel itself still renders for the Equipment page.
      ok(!/Damage Triangle/.test(combatHtml) && !/>Combat Score</.test(combatHtml),
         'the idle Combat tab no longer carries the Equipment & Stats panel');
      s.activity = { type:'combat', playerSwungOnce:true, monsterId:FF.MONSTERS[0].id, monsterHp:FF.MONSTERS[0].hp,
                     tickAccum:0, monsterTickAccum:0, duelStartedAt:Date.now() };
      var liveHtml = FF.renderCombatTab();
      ok(/class="ar2 ivy"/.test(liveHtml), 'the live Combat tab renders the arena');
      ok(!/Damage Triangle/.test(liveHtml) && !/>Combat Score</.test(liveHtml),
         'the live Combat tab is the arena alone -- the stats live on Equipment & Stats');
      ok(/Damage Triangle/.test(FF.renderCombatStatsPanel()),
         'the panel itself still renders (Equipment & Stats consumes it)');
    } finally { s.activity = savedAct; }
  });

  // ---- The combat stage (v0.0.77.0): HP orbs, thin stacked bars, six companion queues, mini feed -------
  suite('combat stage: HP orbs are a damped spring whose state outlives a re-render', function(){
    // zeta = c / (2*sqrt(k)). Over 1 means overdamped, which for a HEALTH bar is the requirement, not a
    // preference: an underdamped spring overshoots and briefly shows HP the player does not have.
    var zeta = FF.ORB_DAMP / (2 * Math.sqrt(FF.ORB_K));
    ok(zeta > 1, 'the orb spring is overdamped (zeta ' + zeta.toFixed(3) + '), so the level never overshoots');

    FF._orbsReset();
    FF.orbReset('me', 1);
    var o = FF.orbState('me');
    eq(o.lvl, 1, 'a reset orb sits exactly at the level given');
    eq(o.vel, 0, 'a reset orb has no velocity');
    eq(o.slosh, 0, 'a reset orb has no slosh');

    // A hit sets a target and kicks the fluid; it does NOT teleport the level.
    FF.orbSetTarget('me', 0.4);
    eq(o.target, 0.4, 'the target takes the new fraction immediately');
    eq(o.lvl, 1, 'the LEVEL still lags -- the spring has not been stepped yet');
    ok(o.vel < 0, 'losing health kicks the fluid downward');
    ok(o.slosh > 0, 'a hit raises the slosh amplitude');
    ok(o.bubbles.length > 0, 'a hit throws bubbles');

    // Magnitude scales the impulse: that is what makes a crit look different from a chip tick.
    FF._orbsReset(); FF.orbReset('me', 1); FF.orbSetTarget('me', 0.95);
    var small = Math.abs(FF.orbState('me').vel);
    FF._orbsReset(); FF.orbReset('me', 1); FF.orbSetTarget('me', 0.05);
    ok(Math.abs(FF.orbState('me').vel) > small * 5, 'a big hit kicks far harder than a chip tick');

    // The bubble spawn is capped. Uncapped, a full-health-to-zero hit would spawn one per percent and a
    // farming chain would accumulate froth forever.
    FF._orbsReset(); FF.orbReset('me', 1);
    for(var i=0;i<50;i++){ FF.orbSetTarget('me', i%2 ? 1 : 0); }
    ok(FF.orbState('me').bubbles.length <= 80, 'bubbles are capped (' + FF.orbState('me').bubbles.length + ')');

    // A fresh foe REFILLS instantly. Springing 0 -> 1 reads as the new enemy being healed, and in a farming
    // chain that is the animation a player would see most often.
    FF.orbReset('foe', 0.02); FF.orbResetFoe();
    eq(FF.orbState('foe').lvl, 1, 'a fresh foe orb is full at once');
    eq(FF.orbState('foe').vel, 0, 'a fresh foe orb does not spring up');

    // ---- The SHIELD fluid (ticket: "missing shield bar in fight") -- a second, blue body of liquid in
    // the same glass, hanging from the top, on its own copy of the same overdamped spring.
    FF._orbsReset(); FF.orbReset('me', 1);
    var so = FF.orbState('me');
    eq(so.sLvl, 0, 'a reset orb carries no shield fluid');
    FF.orbSetShield('me', 0.3);
    eq(so.sTarget, 0.3, 'the shield target takes the new fraction immediately');
    eq(so.sLvl, 0, 'the shield LEVEL lags -- its spring has not been stepped');
    ok(so.sVel > 0, 'a filling shield kicks its fluid');
    ok(so.sSlosh > 0 && so.sBub.length > 0, 'a shield change sloshes and froths the band');
    FF.orbSetShield('me', NaN);
    eq(so.sTarget, 0.3, 'a non-finite shield target is rejected (the NaN-into-gradient pin applies here too)');
    FF.orbSetShield('me', 7);
    eq(so.sTarget, 1, 'the shield target clamps to the glass');
    FF.orbReset('me', 1);
    eq(FF.orbState('me').sTarget, 0, 'a reset clears the shield fluid with everything else');
    // Only classes with an absorb pool ever feed it: the driver is combatShieldTotal, which is zero
    // without any of the four pools.
    var S = FF._state, savedPools = { t:S.templarShield, r:S.reaperShield, l:S.lumenShield, h:S.heraldBarrier };
    S.templarShield = 0; S.reaperShield = 0; S.lumenShield = 0; S.heraldBarrier = 0;
    eq(FF.combatShieldTotal(S), 0, 'no pool, no shield fluid (most classes)');
    S.reaperShield = 500; S.heraldBarrier = 250;
    eq(FF.combatShieldTotal(S), 750, 'the pools stack into one blue band');
    S.templarShield = savedPools.t; S.reaperShield = savedPools.r; S.lumenShield = savedPools.l; S.heraldBarrier = savedPools.h;
    FF._orbsReset();
  });

  // ---- Shield readout: the orb prints a smaller blue "current / cap" under the HP value (v0.0.78.2) --
  suite('shield readout: current / cap under the HP value', function(){
    var S = FF._state, saved = { t:S.templarShield, r:S.reaperShield, l:S.lumenShield, h:S.heraldBarrier };
    try {
      // Markup: the span is ALWAYS emitted (live updates fill it in place) and hides via :empty.
      var html = FF.orbHtml('me', 'health', '10 / 20', '3 / 4');
      ok(html.indexOf('id="ar2Shield-me"') !== -1, 'the player orb carries the shield readout span');
      ok(html.indexOf('>3 / 4<') !== -1, 'seeded in the markup (render paths without a live tick stay blank otherwise)');
      ok(FF.orbHtml('foe', 'x', '1 / 2').indexOf('id="ar2Shield-foe"') !== -1, 'emitted empty on shieldless orbs, so a pool appearing mid-fight needs no rebuild');
      // The ceiling: only channels that currently HOLD shield contribute their cap.
      S.templarShield = 0; S.reaperShield = 0; S.lumenShield = 0; S.heraldBarrier = 0;
      eq(FF.combatShieldCap(S), 0, 'no pool, no ceiling');
      S.heraldBarrier = 1;
      var hOnly = FF.combatShieldCap(S);
      ok(hOnly >= 1, "one held channel contributes that channel's cap");
      S.reaperShield = 1;
      ok(FF.combatShieldCap(S) > hOnly, 'a second held channel ADDS its cap');
      S.reaperShield = 0; S.heraldBarrier = 0;
      S.templarShield = FF.maxHp(S) * 9; // Sanctveil tops the Aegis past its accrual cap by design
      ok(FF.combatShieldCap(S) >= S.templarShield, 'the ceiling never reads below what is held (no "12k / 9k")');
      // Style: blue, smaller than the HP figure, hidden while empty.
      var probe = document.createElement('div');
      probe.innerHTML = '<div class="ar2-orb me"><div class="num"><b>1</b><span class="shield"></span><i>health</i></div></div>';
      document.body.appendChild(probe);
      try {
        var sp = probe.querySelector('.shield'), bb = probe.querySelector('b');
        eq(getComputedStyle(sp).display, 'none', 'an EMPTY readout is hidden -- foes and shieldless classes show nothing extra');
        sp.textContent = '3 / 4';
        ok(getComputedStyle(sp).display !== 'none', 'and it appears the moment it holds text');
        ok(parseFloat(getComputedStyle(sp).fontSize) < parseFloat(getComputedStyle(bb).fontSize), 'smaller than the HP value');
        eq(getComputedStyle(sp).color, 'rgb(140, 204, 255)', "in the shield fluid's blue (#8cccff)");
      } finally { probe.remove(); }
    } finally { S.templarShield=saved.t; S.reaperShield=saved.r; S.lumenShield=saved.l; S.heraldBarrier=saved.h; }
  });

  suite('combat stage: bars, orbs and the mini feed render for a live fight', function(){
    var s = FF._state, savedAct = s.activity, savedHp = s.playerHp, savedMain = s.equippedMainhand;
    var savedTier = s.equippedMainhandTier, savedRar = s.equippedMainhandRarity;
    var savedComps = s.activeCompanions, savedFams = s.familiars, savedCast = s.companionCast;
    var savedBA = s.bodyArmor, savedSumXp = s.xp && s.xp.summoner;
    try {
      var mon = null;
      for(var i=0;i<FF.MONSTERS.length;i++){ if(FF.MONSTERS[i].special){ mon = FF.MONSTERS[i]; break; } }
      ok(mon, 'found a foe with a special attack to exercise the extra bar');
      s.playerHp = Math.max(1, Math.round(FF.maxHp(s) * 0.5));
      s.activity = { type:'combat', playerSwungOnce:true, monsterId:mon.id, monsterHp:Math.max(1, Math.round(mon.hp*0.5)),
                     tickAccum:0, monsterTickAccum:0, duelStartedAt:Date.now() };
      FF._orbsReset();
      var h = FF.renderArena();
      ok(/class="ar2 ivy"/.test(h), 'the stage renders and carries the ivy theme class');
      // Both plinths, and they are the MIRRORED pair rather than the same art twice.
      ok(/ivy_plinth_LEFT\.png/.test(h) && /ivy_plinth_RIGHT\.png/.test(h), 'both mirrored orb plinths are used');
      // The round anchor rings are the PORTRAIT frames, one mirrored piece per side -- they were briefly
      // wired up as orb holders, which is the mistake this pins down.
      ok(/ivy_ring_LEFT\.png/.test(h) && /ivy_ring_RIGHT\.png/.test(h), 'both mirrored portrait rings are used');
      // Retreat lives inside the player's own column, not as a stage-level sibling: as a sibling it sat below
      // the whole header row, whose height the FOE's taller stack sets.
      ok(h.indexOf('data-action="stop"') < h.indexOf('class="ar2-side foe"'),
         'Retreat is emitted inside the player side, before the foe side');
      // And it carries NO inline margin: an inline style beats every selector and silently defeated the
      // theme's frame overlap.
      ok(!/data-action="stop" style=/.test(h), 'Retreat carries no inline style');

      // ---- THE TWO ORBS MUST BE THE SAME SIZE AT THE SAME HEIGHT (v0.0.77.4) ----
      // They shipped 9% apart in diameter and 8px apart in height because the two plinth halves were trimmed
      // independently (900x506 vs 900x539), which forced a well rule PER SIDE -- each carrying its own top,
      // width and height. The art is paired now, so the only thing a side may still say is WHERE the well sits
      // horizontally. Read from the live stylesheet rather than eyeballed: this is the invariant, and it fails
      // loudly the next time someone re-measures one side and not the other.
      (function(){
        var offenders = [], seen = 0;
        function scan(rules){
          for(var i=0;i<rules.length;i++){
            var r = rules[i];
            // RECURSE ON LENGTH, NEVER ON THE PROPERTY'S EXISTENCE. Since CSS Nesting shipped, a plain
            // CSSStyleRule ALSO carries a (usually empty) cssRules list -- so `if(r.cssRules) { recurse;
            // continue; }` treats every rule in the sheet as a group, skips its own declarations, and the
            // scan silently finds nothing. This test reported zero rules found until that was fixed, which
            // is exactly the "a guard must be proven to fail before it is trusted to pass" failure.
            if(r.cssRules && r.cssRules.length) scan(r.cssRules);
            if(!r.selectorText || !/\.ar2\.ivy\s+\.ar2-orb\.(me|foe)\b/.test(r.selectorText)) continue;
            seen++;
            ['width','height','top','bottom'].forEach(function(p){
              if(r.style && r.style.getPropertyValue(p)) offenders.push(r.selectorText.slice(0,60) + ' sets ' + p);
            });
          }
        }
        for(var s2=0; s2<document.styleSheets.length; s2++){
          try { scan(document.styleSheets[s2].cssRules || []); } catch(e){ /* cross-origin sheet: skip */ }
        }
        ok(seen > 0, 'found the per-side orb rules in the stylesheet');
        ok(offenders.length === 0,
           'a per-side orb rule may only set `left` -- size and height are shared (offenders: ' + offenders.join('; ') + ')');
      })();

      ok(/id="ar2Orb-me"/.test(h) && /id="ar2Orb-foe"/.test(h), 'both orb canvases are present');
      // The numbers are SEEDED in the markup. Left to the live tick they would be blank on any render path
      // that is not followed by one -- the dungeon card, or a test.
      ok(/id="ar2Num-me">[^<]+</.test(h), 'the player orb ships its readout in the markup');
      ok(/id="ar2Num-foe">[^<]+</.test(h), 'the foe orb ships its readout in the markup');
      // A foe with a special has TWO bars; that stack is the reason the bar art is squashed.
      ok(/id="ar2AtkFoe"/.test(h), 'the foe attack bar renders');
      ok(/id="ar2AtkSpec"/.test(h), 'the foe special-charge bar renders beneath it');
      ok(/id="ar2AtkMe"/.test(h), 'the player swing bar renders');
      // The foe's name must survive in full: the element and matchup badges used to sit in the name plate
      // and, being fixed-width, truncated every foe past about nine characters.
      ok(h.indexOf('<span class="ar2-nm">' + mon.name + '</span>') !== -1, 'the foe name plate holds the whole name');
      ok(/class="ar2-foeline"/.test(h), 'the element/matchup badges moved below the bars');
      // LOCKED to the foe's own column (v0.0.77.6): the line is the foe meta's last row, after the foe's
      // bars and before its portrait ring -- the mirror of Retreat under the player's bars. As a stage-level
      // row it sat under the combat feed, a long way from the foe it describes, and a fixed offset could not
      // lock it under a stack whose bar count varies (one bar, or two when the foe has a special).
      ok(h.indexOf('class="ar2-foeline"') > h.indexOf('id="ar2AtkFoe"')
         && h.indexOf('class="ar2-foeline"') < h.indexOf('id="ar2PortFoe"'),
         'the weakness line is emitted inside the foe column: after its bars, before its portrait');
      // The tan-chrome panels sit on a tray rather than being individually re-coloured for the dark stage.
      ok(/class="ar2-tray"/.test(h), 'the consumables + Auto-Eat panels sit on the tan tray');
      ok(/data-action="stop"/.test(h), 'Retreat still renders');

      // ---- six companions, each with a cast clock and a spell queue ----
      // Six is the ceiling: one base slot plus one per Summoner perk (Lv 1/20/40/60/80). Slots come from the
      // class ladder now, not staff rarity -- so seat a maxed, fully-kitted Summoner to open all six.
      s.equippedMainhand = 'staff'; s.equippedMainhandTier = FF.TIER_COUNT; s.equippedMainhandRarity = 'fantastic';
      s.bodyArmor = { helmet:{tier:1,rarity:'normal',material:'tailoring'}, chest:{tier:1,rarity:'normal',material:'tailoring'}, gauntlets:{tier:1,rarity:'normal',material:'tailoring'}, boots:{tier:1,rarity:'normal',material:'tailoring'}, back:{tier:0,rarity:'normal',material:null} };
      s.xp.summoner = FF.xpFloorForLevel(80);
      eq(FF.activeClassId(s), 'summoner', 'the fully-kitted, Lv80 Summoner is active');
      eq(FF.summonerFamiliarSlots(s), 5, 'all five Summoner perks each opened a slot');
      eq(FF.activeCompanionSlots(s), 6, 'that ceiling is six (1 base + 5 perks)');
      var ids = Object.keys(FF.FAMILIAR_DATA).slice(0, 6);
      s.familiars = {}; s.companionCast = {};
      ids.forEach(function(id, i){ s.familiars[id] = { owned:true, level:50, stars:0 };
                                   s.companionCast[id] = { accum:0, index:i }; });
      s.activeCompanions = ids.slice();
      eq(FF.activeCompanionList(s).length, 6, 'all six companions are active');
      var h6 = FF.renderArena();
      // The companion row is a STAGE-level row between the header and the plinths: six slots need ~348px and
      // the player's column is narrower than that once the ring inset shrinks it. Asserted here rather than
      // on the earlier render, where no companions are active and the row is absent -- a guarded version of
      // this check silently never ran.
      ok(h6.indexOf('class="ar2-fams"') > 0 && h6.indexOf('class="ar2-fams"') < h6.indexOf('class="ar2-orbs"'),
         'the companion row is emitted above the plinths');
      ids.forEach(function(id){
        ok(h6.indexOf('id="ar2Fam-' + id + '"') !== -1, id + ' has a slot');
        ok(h6.indexOf('id="arenaCast-' + id + '"') !== -1, id + ' has a cast clock');
        ok(h6.indexOf('id="arenaRota-' + id + '"') !== -1, id + ' has a spell queue');
      });
      // The lit pip must follow that companion's OWN queue index, not a shared one -- each seeded a
      // different index above, so a shared counter would light the same position in every slot.
      ids.forEach(function(id, i){
        var spells = FF.FAMILIAR_DATA[id].spells || [];
        if(!spells.length) return;
        var want = i % spells.length;
        var re = new RegExp('class="ar2-pip next" id="arenaRota-' + id + '-' + want + '"');
        ok(re.test(h6), id + ': the lit pip is its own queue position ' + want);
      });

      // ---- NO ONE-FRAME STROBE: a full render() must leave the liquid canvas PAINTED (v0.0.77.8) ----
      // The loop calls orbTick() BEFORE render(), and render rebuilds the stage's DOM -- so a rebuild frame
      // used to composite a fresh, blank canvas and the liquid only came back on the NEXT frame. Black on
      // the old dark stage, a white strobe on marble, up to 10x/sec in combat. render() now repaints the
      // orbs itself before returning; this reads the actual pixels back so the fix cannot silently rot.
      // The stage's <img>s carry decoding="sync" for the same frame-accuracy reason.
      ok(/class="glass" decoding="sync"/.test(h6) && /class="holder" decoding="sync"/.test(h6),
         'the stage images decode synchronously so a rebuilt frame never paints without its art');
      FF.navPickCat('combat');
      FF._orbsReset();
      FF.orbReset('me', 0.6);
      FF.render(true);
      var _cv = document.getElementById('ar2Orb-me'), _painted = false;
      if(_cv && _cv.width){
        var _px = _cv.getContext('2d').getImageData(0, Math.max(0, _cv.height - 4), _cv.width, 3).data;
        for(var _pi = 3; _pi < _px.length; _pi += 4) if(_px[_pi] > 0){ _painted = true; break; }
      }
      ok(_painted, 'render() leaves the orb liquid painted in the same frame -- no blank-canvas strobe');
    } finally {
      s.activity = savedAct; s.playerHp = savedHp; s.equippedMainhand = savedMain;
      s.bodyArmor = savedBA; if(savedSumXp === undefined) delete s.xp.summoner; else s.xp.summoner = savedSumXp;
      s.equippedMainhandTier = savedTier; s.equippedMainhandRarity = savedRar;
      s.activeCompanions = savedComps; s.familiars = savedFams; s.companionCast = savedCast;
      FF._orbsReset();
    }
  });

  suite('combat stage: the mini feed is a tail of the ONE combat log', function(){
    var saved = FF._clGet().slice();
    try {
      FF._clReset();
      ok(/The fight begins/.test(FF.arenaMiniLogHtml()), 'an empty log shows the opening line, not an error');
      // Push more than fits, then check the mini feed carries the TAIL -- the newest lines, not the oldest.
      for(var i=0;i<FF.ARENA_MINI_LOG_ROWS + 6; i++) FF.combatLogPush({ dir:'out', target:'Foe', dmg:i+1 });
      var mini = FF.arenaMiniLogHtml();
      // Count 'log-entry', NOT 'cl-row': each row carries both cl-row and cl-row-<dir>, so counting the
      // latter double-counts every line.
      var rows = mini.split('log-entry').length - 1;
      eq(rows, FF.ARENA_MINI_LOG_ROWS, 'the mini feed renders exactly its row budget');
      ok(mini.indexOf('>' + (FF.ARENA_MINI_LOG_ROWS + 6) + '<') !== -1, 'the NEWEST line is in the mini feed');
      ok(mini.indexOf('>1<') === -1, 'the oldest line has scrolled out of the mini feed');
      // Same buffer, not a second one: the full feed still holds everything.
      ok(FF.combatLogHtml().indexOf('>1<') !== -1, 'the full Combat feed still has the oldest line');
      eq(FF._clGet().length, FF.ARENA_MINI_LOG_ROWS + 6, 'one ring buffer feeds both');
    } finally { FF._clReset(); FF._clGet().push.apply(FF._clGet(), saved); }
  });

  suite('dungeons: D1 Cave', function(){
    var def = FF.DUNGEON_DEFS.d1;
    ok(def, 'D1 dungeon defined');
    eq(def.category, 'Cave', 'the single category is Cave');
    var en = FF.DUNGEON_D1_ENEMIES;
    eq(en.length, 25, '25 enemies');
    eq(en[0].level, 100, 'first enemy is level 100');
    eq(en[24].level, 125, 'last enemy is level 125');
    ok(en.every(function(e,i){ return i===0 || e.level >= en[i-1].level; }), 'levels rise 100 -> 125 without dropping');
    // boss = 25th, ~10x the 24th's HP
    eq(en[24].isBoss, true, 'the 25th enemy is the boss');
    ok(!en[23].isBoss, 'the 24th is not the boss');
    ok(Math.abs(en[24].hp / en[23].hp - 10) < 0.01, 'boss HP is ~10x the 24th (' + en[24].hp + ' vs ' + en[23].hp + ')');
    // distinct elements across the set
    var elems = {}; en.forEach(function(e){ elems[e.element] = 1; });
    ok(Object.keys(elems).length >= 3, 'enemies span multiple elements (' + Object.keys(elems).join(',') + ')');
    // every enemy: SVG portrait + full combat typing + registered in monsterById
    ok(en.every(function(e){ return typeof e.icon === 'string' && e.icon.indexOf('<svg') === 0; }), 'every enemy has an SVG portrait');
    ok(en.every(function(e){ return e.element && e.armorTypes && e.attackTypes && e.hp > 0 && FF.monsterById(e.id) === e; }), 'every enemy has element/armor/attack/hp and resolves via monsterById');
    // (The legacy D1 Formula is deleted: Blueprints are the drop, v0.0.96.34.)
    eq(FF.ALL_SELLABLE['formula_d1_masterwork'], undefined, 'the D1 Formula item no longer exists');
    // Threat: plate armour draws more than cloth.
    function armorSet(mat){ var b = {}; ['helmet','chest','gauntlets','boots'].forEach(function(s){ b[s] = { material:mat, tier:5, rarity:'normal' }; }); return b; }
    ok(FF.playerThreat({ bodyArmor: armorSet('plate') }) > FF.playerThreat({ bodyArmor: armorSet('tailoring') }), 'plate armour generates more threat than cloth');
    ok(FF.armorThreatWeight('plate') > FF.armorThreatWeight('tailoring'), 'plate threat weight > cloth');
    // Target picker: a lone alive member is always chosen; an all-downed party returns -1.
    eq(FF.dungeonPickTarget([{ alive:true, threat:10 }]), 0, 'solo party targets member 0');
    eq(FF.dungeonPickTarget([{ alive:false, threat:10 }]), -1, 'no alive members -> -1 (no target)');
    // CRITICAL client<->server invariant: the enemy HP curve must match the server (dungeon edge fn)
    // formula exactly -- hp[i]=round(50000*1.05^i), boss=round(hp[23]*10) -- or shared HP desyncs.
    for(var _i = 0; _i < 24; _i++) eq(en[_i].hp, Math.round(50000 * Math.pow(1.05, _i)), 'enemy ' + _i + ' HP matches the server formula');
    eq(en[24].hp, Math.round(en[23].hp * 10), 'boss HP = round(24th * 10) matches the server');
    // Enemy ATTACK curve + cadence must also match the server (dungeon edge fn d1Roster) or enemy
    // damage/timing desyncs in Stage B: atkMin=round(80*1.04^i), atkMax=round(200*1.04^i)
    // (D1 group offense cut 60%, was 200/500), interval_ms = round((2.2 + (i%5)*0.3)*1000).
    for(var _j = 0; _j < 25; _j++){
      eq(en[_j].atkMin, Math.round(80 * Math.pow(1.04, _j)), 'enemy ' + _j + ' atkMin matches server');
      eq(en[_j].atkMax, Math.round(200 * Math.pow(1.04, _j)), 'enemy ' + _j + ' atkMax matches server');
      eq(Math.round(en[_j].attackSpeed * 1000), Math.round((2.2 + (_j % 5) * 0.3) * 1000), 'enemy ' + _j + ' attack interval matches server');
    }
    // Reported proxies are bounded: DPS positive, mitigation 0..85%.
    var pw = FF.dungeonPower(); ok(typeof pw === 'number' && isFinite(pw) && pw >= 1, 'dungeonPower() is a positive finite DPS proxy');
    var mp = FF.dungeonMitPct(); ok(mp >= 0 && mp <= 85, 'dungeonMitPct() is a bounded 0..85% proxy');
  });

