    ok(FF.mastercraftRecipeFor(FF.BLUEPRINT_ITEMS[FF.masterworkBlueprintId('d2','cape')]) !== null, 'D2 Cloak mastercraft is now available (Batch K)');
    // Effect aggregation from an equipped Shroud in the Back slot.
