    ok(FF.isTowerEntrance('all') && FF.isTowerEntrance('pyromancer') && !FF.isTowerEntrance('nope'), 'isTowerEntrance gates real entrances');
    // Floor tier: floor 1 = tier 10, +2 per floor, unbounded.
