  // ---- Quests: completion LATCHES -- once a quest hits its target it stays ready-to-claim (and a claimed
  //      quest stays full) even if a momentary condition later reverses ----
  suite('quests: completion latches until claimed', function(){
    var s = FF._state;
    var q = FF.questById('take_up_arms'); // progress = (scimitar equipped ? 1 : 0), target 1
    ok(!!q, 'the scimitar-equip quest exists');
    var saved = { mh:s.equippedMainhand, quests:s.quests };
    try {
      // Below target, progress tracks the live condition both up AND down.
      s.quests = { claimed:{}, completed:{} };
      s.equippedMainhand = null;
      eq(FF.questProgress(q), 0, 'condition unmet -> 0 while still incomplete');
      s.equippedMainhand = 'scimitar';
      eq(FF.questProgress(q), 1, 'meeting the condition completes the quest');
      ok(FF.questClaimable(q), 'and arms it for claiming');
      // LATCH: unequipping after completion does NOT drain the bar -- it stays ready-to-claim until claimed
      // (the reported bug: complete a gear quest, swap the piece away, then the claim is gone).
      s.equippedMainhand = null;
      eq(FF.questProgress(q), 1, 'once completed, reversing the condition keeps a full, claimable bar');
      ok(FF.questComplete(q) && FF.questClaimable(q), 'still complete and still claimable');
      ok(s.quests.completed && s.quests.completed.take_up_arms === true, 'completion is recorded in state.quests.completed (persists across a reload)');
      // Once CLAIMED, the bar also stays full and is no longer claimable.
      s.quests.claimed.take_up_arms = true;
      s.equippedMainhand = null;
      eq(FF.questProgress(q), 1, 'a CLAIMED quest shows a full bar even with the condition unmet');
      ok(FF.questComplete(q) && !FF.questClaimable(q), 'still complete, and not re-claimable');

      // questScanCompletions latches a satisfied quest even if its bar is never READ while satisfied --
      // so equipping the piece banks the completion off-screen, before the player can swap it away.
      s.quests = { claimed:{}, completed:{} };
      s.equippedMainhand = 'scimitar';       // condition holds, but we never call questProgress here
      ok(FF.questScanCompletions(), 'the scan reports it latched a newly-completed quest');
      ok(s.quests.completed.take_up_arms === true, 'the scan recorded the completion');
      s.equippedMainhand = null;             // condition reverses BEFORE any read
      eq(FF.questProgress(q), 1, 'the scan latched it, so it survives the reversal');
      ok(FF.questClaimable(q), 'still claimable after the off-screen latch');
    } finally {
      s.equippedMainhand = saved.mh; s.quests = saved.quests;
    }
  });

  // ---- Estate Buildings list: workshops with attached-cottage-by-tier counts, cottage links ----
  suite('estate: buildings list groups attached cottages by tier', function(){
    // Build a small grid[x][y] with a workshop at (2,2) and cottages around it.
    function cell(){ return { workshopId:null, cottageId:null, height:0 }; }
    var g = []; for(var x=0;x<6;x++){ g[x]=[]; for(var y=0;y<6;y++){ g[x][y]=cell(); } }
    var wsId = Object.keys(FF.WORKSHOP_ITEMS).filter(function(id){ return FF.WORKSHOP_ITEMS[id].tierIndex===4; })[0];
    var cot1 = Object.keys(FF.COTTAGE_ITEMS).filter(function(id){ return FF.COTTAGE_ITEMS[id].tierIndex===1; })[0];
    var cot3 = Object.keys(FF.COTTAGE_ITEMS).filter(function(id){ return FF.COTTAGE_ITEMS[id].tierIndex===3; })[0];
    var cot1b = cot1;
    g[2][2].workshopId = wsId;         // the workshop
    g[2][1].cottageId = cot1;          // adjacent (orthogonal) -> attaches, tier 1
    g[3][2].cottageId = cot3;          // adjacent -> attaches, tier 3
    g[2][3].cottageId = cot1b;         // adjacent -> attaches, tier 1 (a second T1)
    g[0][0].cottageId = cot3;          // isolated -> unattached
    var data = FF.estateBuildingList(g);
    eq(data.workshops.length, 1, 'one workshop found');
    eq(data.cottages.length, 4, 'four cottages found');
    var w = data.workshops[0];
    eq(w.x, 2, 'workshop x'); eq(w.y, 2, 'workshop y');
    eq(w.attached.total, 3, 'three cottages attach to the workshop');
    eq(w.attached.byTier[1], 2, 'two tier-1 cottages attached');
    eq(w.attached.byTier[3], 1, 'one tier-3 cottage attached');
    var isolated = data.cottages.filter(function(c){ return c.x===0 && c.y===0; })[0];
    eq(isolated.linked, null, 'a cottage with no adjacent workshop is unattached');
    // Fresh grid: a cottage between TWO workshops links to neither (estateAdjacentWorkshop needs exactly one).
    var g2 = []; for(var gx=0;gx<4;gx++){ g2[gx]=[]; for(var gy=0;gy<4;gy++){ g2[gx][gy]=cell(); } }
    g2[1][2].workshopId = wsId; g2[3][2].workshopId = wsId; g2[2][2].cottageId = cot1;
    var between = FF.estateBuildingList(g2).cottages.filter(function(c){ return c.x===2 && c.y===2; })[0];
    eq(between.linked, null, 'a cottage adjacent to two workshops attaches to neither');
  });

  // ---- Miracle cards show the Fantastic chance to four decimals (v0.0.96.8 odds cut: 0.00025% tier steps) ----
  suite('faith cards: Miracle Fantastic chance shows 4 decimals', function(){
    var s = FF._state, saved = { m:s.xp.miracle, d:s.xp.devotion };
    try {
      s.xp.miracle = 1e12; s.xp.devotion = 1e12; // max level so every tier card renders
      var m = FF.renderFaithActivityTab('miracle');
      ok(/\d\.\d{4}% Fantastic/.test(m), 'Miracle cards show four decimals on the Fantastic chance');
      // Rare odds are larger, so Devotion keeps 2 decimals (no needless thousandths).
      var d = FF.renderFaithActivityTab('devotion');
      ok(/\d\.\d{2}% Rare/.test(d) && !/\d\.\d{3}% Rare/.test(d), 'Devotion keeps 2 decimals on the Rare chance');
    } finally { s.xp.miracle = saved.m; s.xp.devotion = saved.d; }
  });

  // ---- Equip: wands & scepters gate on their PROFICIENCY, not the crafting skill (like melee/ranged) ----
  suite('equip: wands & scepters require proficiency for higher tiers', function(){
    var s = FF._state, items = FF.STACKABLE_WEAPON_ITEMS;
    // The resolver maps wands/scepters to their SHARED proficiency; melee keeps its per-type one.
    var wandType = Object.keys(items).map(function(id){ return items[id].typeId; }).filter(function(t){ return FF.isWandWeapon(t); })[0];
    ok(!!wandType, 'a wand type exists');
    eq(FF.weaponEquipProfId(wandType), FF.WANDS_SKILL_ID, 'a wand resolves to the Wands proficiency');
    eq(FF.weaponEquipProfId('scepter'), FF.SCEPTERS_SKILL_ID, 'a scepter resolves to the Scepters proficiency');
    eq(FF.weaponEquipProfId('staff'), FF.STAVES_SKILL_ID, 'a staff resolves to the Staves proficiency (not Arcanism)');
    eq(FF.weaponEquipProfId('sword'), 'sword', 'a melee weapon keeps its per-type proficiency');
    // Lowest tier>=2 wand & scepter (tier gate is a no-op below tierIndex 1).
    function lowest(pred){
      var ids = Object.keys(items).filter(function(id){ return pred(items[id].typeId) && items[id].tierIndex >= 2; });
      ids.sort(function(a,b){ return items[a].tierIndex - items[b].tierIndex; });
      return ids[0];
    }
    var wandId = lowest(FF.isWandWeapon), scepId = lowest(FF.isScepter), staffId = lowest(FF.isStaff);
    ok(!!wandId && !!scepId, 'found a tier 3+ wand and scepter');
    ok(!!staffId, 'found a tier 3+ staff');
    var saved = { w:s.xp[FF.WANDS_SKILL_ID], c:s.xp[FF.SCEPTERS_SKILL_ID], t:s.xp[FF.STAVES_SKILL_ID], a:s.xp.arcanism, r:s.xp.runesmithing };
    try {
      // No proficiency, but MAX crafting skill -> the gate must block on proficiency now, not the craft skill.
      s.xp[FF.WANDS_SKILL_ID] = 0; s.xp[FF.SCEPTERS_SKILL_ID] = 0; s.xp[FF.STAVES_SKILL_ID] = 0; s.xp.arcanism = 1e12; s.xp.runesmithing = 1e12;
      var wg = FF.stackableEquipGate(items[wandId]);
      eq(wg.ok, false, 'a higher-tier wand is locked with no Wands proficiency (even at max Arcanism)');
      eq(wg.label, 'Wands', 'the lock names the Wands proficiency, not Arcanism');
      var sg = FF.stackableEquipGate(items[scepId]);
      eq(sg.ok, false, 'a higher-tier scepter is locked with no Scepters proficiency (even at max Runesmithing)');
      eq(sg.label, 'Scepters', 'the lock names the Scepters proficiency, not Runesmithing');
      // The staff bug: it used to gate on Arcanism (the CRAFT skill), so a crafter could wield any tier.
      // It must now gate on the Staves proficiency like every other weapon (max Arcanism must not unlock it).
      var tg = FF.stackableEquipGate(items[staffId]);
      eq(tg.ok, false, 'a higher-tier staff is locked with no Staves proficiency (even at max Arcanism)');
      eq(tg.label, 'Staves', 'the lock names the Staves proficiency, not Arcanism');
      // Raising the proficiency unlocks them.
      s.xp[FF.WANDS_SKILL_ID] = 1e12; s.xp[FF.SCEPTERS_SKILL_ID] = 1e12; s.xp[FF.STAVES_SKILL_ID] = 1e12;
      ok(FF.stackableEquipGate(items[wandId]).ok, 'Wands proficiency unlocks the wand');
      ok(FF.stackableEquipGate(items[scepId]).ok, 'Scepters proficiency unlocks the scepter');
      ok(FF.stackableEquipGate(items[staffId]).ok, 'Staves proficiency unlocks the staff');
    } finally {
      s.xp[FF.WANDS_SKILL_ID]=saved.w; s.xp[FF.SCEPTERS_SKILL_ID]=saved.c; s.xp[FF.STAVES_SKILL_ID]=saved.t; s.xp.arcanism=saved.a; s.xp.runesmithing=saved.r;
    }
  });

  // ---- Auth identity guard: cross-account write prevention (shared per-origin auth session) ----
  suite('auth: identity-mismatch guard', function(){
    var saved = FF._authBoundUserId();
    // No binding yet -> nothing is a mismatch (an unbound tab never false-fences).
    FF.authBindIdentity(null);
    eq(FF.authIdentityMismatch('user-A'), false, 'an unbound tab never reports a mismatch');
    // Bound to account A: A's own session matches; a foreign id (shared-storage swap) mismatches.
    FF.authBindIdentity('user-A');
    eq(FF.authIdentityMismatch('user-A'), false, 'the bound account is not a mismatch');
    ok(FF.authIdentityMismatch('user-B') === true, 'a different account on the shared session IS a mismatch');
    // A missing session id (mid-refresh) is not treated as a swap.
    eq(FF.authIdentityMismatch(null), false, 'a null session id does not fence');
    eq(FF.authIdentityMismatch(undefined), false, 'an undefined session id does not fence');
    // Deliberate in-tab switch: clearing the binding first means the imminent SIGNED_IN isn't misread.
    FF.authBindIdentity(null);
    eq(FF.authIdentityMismatch('user-B'), false, 'cleared binding: a fresh login is not a foreign swap');
    FF.authBindIdentity(saved || null);
  });

  // ---- Joining a party: Total Level 5000 + the PREVIOUS layer cleared (like starting your own) ----
  suite('dungeons: join requirements + party code', function(){
    var s = FF._state, savedCleared = s.dungeonsCleared, savedXp = s.xp, savedPhys = s.physique;
    // Force the profile over the Total Level gate so the join test isolates the progression rule.
    // (playerTotalLevel sums skill + physique levels; a big fake skill map clears 5000 handily.)
    var bigXp = {}; if (FF.ALL_MAIN_SKILL_IDS) FF.ALL_MAIN_SKILL_IDS.forEach(function(id){ bigXp[id] = 1e12; });
    s.xp = bigXp; s.physique = {};
    ok(FF.playerTotalLevel(s) >= FF.DUNGEON_MIN_TOTAL_LEVEL, 'the boosted profile clears the Total Level gate');
    s.dungeonsCleared = {};
    eq(FF.dungeonJoinBlock('d1'), null, 'the Cave has no prerequisite to join');
    ok(FF.dungeonJoinBlock('d2') !== null, 'joining a Tunnel party requires the Cave cleared first');
    // Beating D1 (solo OR group -- both call dungeonMarkCleared) unlocks joining D2 parties;
    // a prior D2 clear must NOT be required (that locked group progression behind solo play).
    FF.dungeonMarkCleared('d1');
    eq(FF.dungeonJoinBlock('d2'), null, 'clearing the Cave unlocks joining Tunnel parties -- no Tunnel clear needed');
    ok(FF.dungeonJoinBlock('d3') !== null, 'D3 parties still need the Tunnel cleared');
    FF.dungeonMarkCleared('d2');
    eq(FF.dungeonJoinBlock('d3'), null, 'the chain continues: clearing D2 unlocks joining D3 parties');
    ok(FF.dungeonJoinBlock('d4') !== null, '...and D4 parties still need D3 cleared');
    // Below the Total Level gate, even the Cave blocks joining.
    s.xp = {}; s.physique = {};
    ok((FF.dungeonJoinBlock('d1') || '').indexOf('Total Level') === 0, 'below the Total Level gate even the Cave blocks joining');
    s.xp = savedXp; s.physique = savedPhys; s.dungeonsCleared = savedCleared;
    // Party-code parsing: "<layer>:<id>" splits; a bare id yields a null layer.
    var c = FF.parseDungeonCode('d2:abc-123');
    eq(c.layer, 'd2', 'a "d2:<id>" code parses the layer'); eq(c.id, 'abc-123', '...and the session id');
    eq(FF.parseDungeonCode('D3 9f8e').layer, 'd3', 'space + upper-case layer prefixes also parse');
    eq(FF.parseDungeonCode('abc-123').layer, null, 'a bare id has no encoded layer');
    eq(FF.parseDungeonCode('abc-123').id, 'abc-123', 'a bare id passes through as the id');
  });

  // ---- Lumen Oracle (Light Wand): the last wand element gets a caster class -----------------------
  suite('classes: lumen oracle (light wand)', function(){
    function armor(mat,tier){ return {material:mat,tier:tier||5}; }
    function stFor(level, extra){
      var st = { xp:{}, physique:{}, bodyArmor:{}, equippedMainhand:'wandLight', equippedOffhand:'wardLight',
                 bodyArmor:{helmet:armor('leather'),chest:armor('leather'),gauntlets:armor('leather'),boots:armor('leather')},
                 classDebuffs:{enemyDmgUntil:0,enemyArmorUntil:0}, activity:{type:'combat', playerSwungOnce:true,monsterHp:100}, playerHp:55 };
      st.xp['lumen'] = FF.xpFloorForLevel(level);
      if(extra) for(var k in extra) st[k]=extra[k];
      return st;
    }
    var cd = FF.CLASS_DEFS_BY_ID.lumen;
    ok(cd, 'Lumen Oracle is a registered class');
    eq(cd.name, 'Lumen Oracle', 'display name is Lumen Oracle');
    eq(cd.passives.length, 5, 'has 5 perks');
    eq(cd.passives.map(function(p){ return p.level; }).join(','), '1,20,40,60,80', 'perks at Lv 1/20/40/60/80');
    ok(/Light Wand/.test(cd.reqText), 'wields the Light Wand (the last element without a class)');
    // gating: full kit activates; dropping the boots deactivates.
    eq(FF.activeClassId(stFor(80)), 'lumen', 'light wand + ward + full leather => Lumen Oracle');
    eq(FF.activeClassId(stFor(80,{bodyArmor:{helmet:armor('leather'),chest:armor('leather'),gauntlets:armor('leather')}})), null, 'Lumen Oracle needs Leather Boots');
    ok(FF.activeClassId(stFor(80,{equippedMainhand:'wandDark'})) !== 'lumen', 'a Dark Wand does not activate Lumen Oracle (it is the Voidshadow kit)');
    // The Overflow ladder: The Overflow / Everfull / Blinding Light / Brimover / The Second Sun.
    // Reflected Light (the saturation engine -- 15% of ~1e11 damage as healing against a 4-digit HP
    // bar) and Flashbang's RNG stun are retired.
    eq(cd.passives.map(function(p){ return p.name; }).join(','), 'The Overflow,Everfull,Blinding Light,Brimover,The Second Sun', 'Lumen ladder is the Overflow five');
    ok(typeof FF.lumenReflectPct === 'undefined', 'Reflected Light retired (never scale a heal off damage dealt)');
    ok(typeof FF.lumenReflectD2Mult === 'undefined', 'its D2 amplifier went with it');
    eq(FF.newClassDmgMult({hp:100}, stFor(80)), 1, 'Lumen grants no flat damage');
    // Solo, a heal always targets self (no living networked party).
    eq(FF.lumenHealTarget().isSelf, true, 'solo -> Lumen heals cast on self');
    // Live-state mechanics: the Lumen kit must be worn on _state so the bonuses are active.
    var S = FF._state;
    var sv = { mh:S.equippedMainhand, oh:S.equippedOffhand, ba:S.bodyArmor, xp:S.xp.lumen, act:S.activity, hp:S.playerHp, sh:S.lumenShield,
               rad:S.lmRadiance, ba2:S.lmBrimAccum, ma:S.lmMendAccum, sf:S.lmSpillFrac, cd:S.classDebuffs };
    try {
      S.equippedMainhand='wandLight'; S.equippedOffhand='wardLight';
      S.bodyArmor={helmet:armor('leather'),chest:armor('leather'),gauntlets:armor('leather'),boots:armor('leather')};
      S.activity = { type:'combat', playerSwungOnce:true, monsterId:FF.MONSTERS[0].id, monsterHp:1e9, dotHitAvg:1000 };
      S.classDebuffs = { enemyDmgUntil:0, enemyArmorUntil:0 };
      // Everfull (Lv20 now): healing a full-HP target banks the overheal as a Barrier.
      S.xp.lumen = FF.xpFloorForLevel(20); S.lumenShield = 0; S.playerHp = FF.maxHp(S);
      FF.lumenApplyHeal(100);
      ok((S.lumenShield||0) > 0, 'Everfull banks overheal as a Barrier at Lv20');
      S.xp.lumen = FF.xpFloorForLevel(1); S.lumenShield = 0;
      FF.lumenApplyHeal(100);
      eq(S.lumenShield||0, 0, 'no Barrier below Lv20');
      // The shield cap: 30% of max HP.
      S.xp.lumen = FF.xpFloorForLevel(85);
      S.lumenShield = 0; FF.lumenAddShield(1e9); eq(S.lumenShield, FF.lumenShieldCap(S), 'the Barrier caps at 30% of max HP');
      // The pour: radiance gathers +2/s from the clock, +4 per landed hit (lmOnHit).
      S.lmRadiance = 0; S.lmBrimAccum = 0; S.lmMendAccum = 0; S.lmSpillFrac = 1;
      FF.applyLumenMendingTick(1000);
      near(S.lmRadiance, 2, 'one second of combat gathers +2 Radiance', 1e-9);
      FF.lmOnHit(S);
      near(S.lmRadiance, 6, 'a landed swing gathers +4 more', 1e-9);
      // The spill: dotBase x 0.8% x radiance x spillFrac per second, and on a FULL-health capped-Barrier
      // Oracle the mend is all surplus -- spillFrac resolves to 1 (the whole pour burns).
      S.lmRadiance = 100; S.playerHp = FF.maxHp(S); S.lumenShield = FF.lumenShieldCap(S);
      S.activity.dotHitAvg = 1000; S.lmSpillFrac = 1; S.lmMendAccum = 0;
      var hp0 = S.activity.monsterHp;
      FF.applyLumenMendingTick(1000);
      near(hp0 - S.activity.monsterHp, Math.round(1000 * FF.LM_SPILL_PCT * 100 * FF.LM_SUN_MULT), 'one second of the spill at full Radiance = dotBase x 0.8% x radiance x the burning Sun', 30); // (radiance is cap-clamped at 100; Lv85 => the Second Sun doubles the pour)
      eq(S.lmSpillFrac, 1, 'a full-health, full-Barrier target consumes nothing -- everything spills');
      ok((S.classDebuffs.enemyDmgUntil||0) > Date.now(), 'Blinding Light holds the shared -25% window while the spill flows');
      // The honest coupling: a WOUNDED Oracle drinks first and the spill fraction drops.
      S.playerHp = 1; S.lumenShield = 0; S.lmMendAccum = 999; S.lmSpillFrac = 1;
      FF.applyLumenMendingTick(1);
      ok(S.lmSpillFrac < 1, 'a wounded target consumes the mend -- the spill is what mercy does not claim');
      ok(S.playerHp > 1, 'and the mend actually healed');
      // Brimover (Lv60): while the Barrier stands full, a burst every 5s, applied raw.
      S.playerHp = FF.maxHp(S); S.lumenShield = FF.lumenShieldCap(S);
      S.lmRadiance = 100; S.lmBrimAccum = 0; S.lmMendAccum = 0; S.lmSpillFrac = 1; S.activity.dotHitAvg = 1000;
      var hp1 = S.activity.monsterHp;
      FF.applyLumenMendingTick(FF.LM_BRIM_MS);
      var brimTotal = hp1 - S.activity.monsterHp;
      var spillShare = 1000 * FF.LM_SPILL_PCT * 100 * FF.LM_SUN_MULT * (FF.LM_BRIM_MS/1000); // the Sun doubles the spill; the burst itself is NOT sun-scaled by design
      near(brimTotal - spillShare, Math.round(1000 * FF.LM_BRIM_PCT), 'five seconds at a full Barrier = the sunned spill plus ONE Brimover at 150%', 60);
      var rows = FF._combatLog(); var lastRow = rows[rows.length-1];
      ok(lastRow && (lastRow.spName === 'Brimover' || lastRow.spName === 'Searing Light'), 'the burst and the spill are named Combat log rows');
      S.lumenShield = 0; S.lmBrimAccum = 4999;
      FF.applyLumenMendingTick(100);
      eq(S.lmBrimAccum, 0, 'an unfilled Barrier holds no Brimover charge');
      // The Second Sun (Lv80): at full Radiance the pour doubles (spill included).
      S.lumenShield = FF.lumenShieldCap(S); S.lmRadiance = 100;
      ok(FF.lmSunBurning(S), 'the Second Sun burns at full Radiance');
      near(FF.lmSpillDps(S), 1000 * FF.LM_SPILL_PCT * 100 * FF.LM_SUN_MULT, 'the burning sun doubles the spill');
      S.lmRadiance = 50;
      ok(!FF.lmSunBurning(S), 'and gutters below it');
      near(FF.lmSpillDps(S), 1000 * FF.LM_SPILL_PCT * 50, 'the half-gathered pour spills singly');
      // The session reset disperses the light.
      S.lmRadiance = 80; S.lmBrimAccum = 3000; S.lmMendAccum = 500; S.lmSpillFrac = 0.5;
      FF.resetPersistentCombatBuffs();
      ok(!S.lmRadiance && !S.lmBrimAccum && !S.lmMendAccum && S.lmSpillFrac === 1, 'resetPersistentCombatBuffs disperses the gathered light');
    } finally {
      S.equippedMainhand=sv.mh; S.equippedOffhand=sv.oh; S.bodyArmor=sv.ba; S.xp.lumen=sv.xp; S.activity=sv.act; S.playerHp=sv.hp; S.lumenShield=sv.sh;
      S.lmRadiance=sv.rad; S.lmBrimAccum=sv.ba2; S.lmMendAccum=sv.ma; S.lmSpillFrac=sv.sf; S.classDebuffs=sv.cd;
    }
  });

  // ---- Reaver (Half-Moon Axe): the fast 1h axe gets a Bleed-DoT class -----------------------------
  suite("classes: reaver (the Butcher's Count -- bleed as a ledger)", function(){
    function armor(mat){ return {material:mat,tier:5}; }
    function stFor(level, extra){
      var st = { xp:{}, physique:{}, equippedMainhand:'halfmoonaxe', equippedOffhand:'shieldSmall',
                 bodyArmor:{helmet:armor('chain'),chest:armor('chain'),gauntlets:armor('leather'),boots:armor('leather')},
                 activity:{type:'combat', playerSwungOnce:true,monsterHp:100}, playerHp:55 };
      st.xp['reaver'] = FF.xpFloorForLevel(level);
      if(extra) for(var k in extra) st[k]=extra[k];
      return st;
    }
    var cd = FF.CLASS_DEFS_BY_ID.reaver;
    ok(cd, 'Reaver is a registered class');
    eq(cd.passives.length, 5, 'has 5 perks');
    eq(cd.passives.map(function(p){ return p.level; }).join(','), '1,20,40,60,80', 'perks at Lv 1/20/40/60/80');
    ok(/Half-Moon Axe/.test(cd.reqText), 'wields the Half-Moon Axe (previously unclaimed)');
    // gating: full kit activates; dropping the shield or swapping the gloves to chain deactivates.
    eq(FF.activeClassId(stFor(80)), 'reaver', 'half-moon axe + small shield + chain/leather => Reaver');
    eq(FF.activeClassId(stFor(80,{equippedOffhand:null})), null, 'Reaver needs the Small Shield');
    eq(FF.activeClassId(stFor(80,{bodyArmor:{helmet:armor('chain'),chest:armor('chain'),gauntlets:armor('chain'),boots:armor('leather')}})), null, 'Reaver needs Leather Gloves, not chain');
    // The Butcher's Count ladder. Savagery (a bare +25% damage) and Bloodletting retired; Frenzied Rending was
    // PROMOTED to Lv1 as Flensing, because Bleed cannot be a level-forty unlock on the bleed class; Arterial
    // Spray moved onto Bonereaver (as a perk it needed a kill, so it did nothing against a boss); Hemorrhagic
    // Burst was superseded by Harvest, which is the same idea with a resource behind it.
    eq(cd.passives.map(function(p){ return p.name; }).join(','), 'Flensing,The Count,Deep Cuts,Harvest,The Butcher\u2019s Tally', 'Butcher\'s Count ladder');
    eq(FF.newClassCritDmg(stFor(80)), 0, 'Reaver grants no flat crit damage');
    // Savagery is gone: with no Cuts tallied the class adds no damage row at all.
    ok(Math.abs(FF.newClassDmgMult({hp:100}, stFor(1)) - 1) < 1e-9, 'Savagery retired: no flat +25%');
    ok(Math.abs(FF.newClassDmgMult({hp:100}, stFor(80)) - 1) < 1e-9, 'and none at Lv80 with an empty ledger');

    // The Bleed used to tick off summed proficiency LEVELS (a few hundred damage against ~1e11 hits), so the
    // class's identity was invisible at best-in-slot. It now ticks off the recent-hit EMA.
    near(FF.RV_BLEED_PCT, 0.06, 'a Bleed stack ticks for 6% of the recent average hit per second');
    near(FF.RV_SWING_MULT, 0.33, 'the axe channels its raw swings to 33% -- the wounds do the killing (THE band knob, v0.0.96.17 bands)');
    ok(FF.PLAYER_DMG_MODS.some(function(r){ return r.name === 'reaverFlensing'; }), 'the Flensing channel is a named PLAYER_DMG_MODS row');

    // Lv 20 The Count: +0.4% damage per Cut, capped, and it reads the FIGHT's tally off the activity.
    near(FF.RV_COUNT_PCT, 0.004, 'The Count pays +0.4% per Cut');
    near(FF.RV_COUNT_CAP, 1.20, '... capped at +120%');
    var ct = stFor(80); ct.activity = { type:'combat', playerSwungOnce:true, monsterHp:100, rvCuts:100 };
    near(FF.rvCountMult(ct), 1.40, '100 Cuts -> +40% damage');
    ct.activity.rvCuts = 9999; near(FF.rvCountMult(ct), 1 + FF.RV_COUNT_CAP, 'the Count respects its cap');
    var ct1 = stFor(1); ct1.activity = { type:'combat', playerSwungOnce:true, monsterHp:100, rvCuts:100 };
    near(FF.rvCountMult(ct1), 1, 'the Count needs Lv20');

    // Lv 40 Deep Cuts: the cap rises to 8, and because every STACK-second carves a Cut, the cap is ramp SPEED.
    eq(FF.reaverBleedCap(stFor(1)), FF.REAVER_BLEED_MAX, 'Lv1: base Bleed cap of 5');
    eq(FF.reaverBleedCap(stFor(40)), 8, 'Deep Cuts (Lv40): the cap rises to 8');

    // Flensing's max-stack haste now lands at Lv1 (it moved down with the Bleed).
    var frMax = stFor(1); frMax.activity = { type:'combat', playerSwungOnce:true, monsterHp:100, bleedStacks:5, bleedUntil:Date.now()+5000 };
    near(FF.classAttackSpeedMult(frMax), 0.85, 'Flensing: +15% attack speed at max Bleed stacks', 1e-9);
    var frLow = stFor(40); frLow.activity = { type:'combat', playerSwungOnce:true, monsterHp:100, bleedStacks:2, bleedUntil:Date.now()+5000 };
    eq(FF.classAttackSpeedMult(frLow), 1, 'no frenzy haste below max stacks');

    // Carving Cuts: fractional stack-seconds accumulate, so the tally is tick-rate independent -- a per-tick
    // count would pay out differently at different frame rates.
    var cv = stFor(80); cv.activity = { type:'combat', playerSwungOnce:true, monsterHp:100 };
    eq(FF.rvCarveCuts(0.4, cv), 0, 'a fraction of a stack-second carves nothing yet');
    eq(FF.rvCarveCuts(0.7, cv), 1, 'but it accumulates and carves on the way past 1');
    eq(cv.activity.rvCuts, 1, 'the tally took the Cut');
    eq(cv.activity.rvBank, 1, 'and so did the harvestable bank');
    FF.rvCarveCuts(9999, cv);
    eq(cv.activity.rvCuts, FF.RV_CUT_MAX, 'the tally has a ceiling');

    // Lv 60 Harvest: it cashes the BANK. Two numbers on purpose -- with one, a capstone tally that never
    // drops would sit permanently above the threshold and Harvest on every crit.
    eq(FF.RV_HARVEST_AT, 60, 'a Harvest arms at 60 banked Cuts');
    var hv = stFor(60); hv.activity = { type:'combat', playerSwungOnce:true, monsterHp:1e9, rvCuts:100, rvBank:100, rvBleedHitAvg:1000 };
    eq(FF.rvHarvestArmed(hv), true, '100 banked Cuts arms the Harvest');
    near(FF.rvHarvestDamage(hv), 100 * FF.RV_HARVEST_PCT * 1000, 'Harvest = banked Cuts x 5% x the recent average hit');
    hv.activity.rvBank = 10; eq(FF.rvHarvestArmed(hv), false, 'and disarms below the threshold');
    var hv20 = stFor(20); hv20.activity = { type:'combat', playerSwungOnce:true, monsterHp:1e9, rvBank:100, rvBleedHitAvg:1000 };
    eq(FF.rvHarvestArmed(hv20), false, 'Harvest needs Lv60');
    // Bleed tick: it reads the global _state.activity. Snapshot the fields we touch, then restore.
    // With no Reaver kit equipped on _state, reaverBonus(60/80) are off, so we exercise the base tick:
    // it chips the enemy (no floor -- a Bleed can finish a foe), and an expired Bleed does nothing.
    var S = FF._state;
    var save = { act:S.activity, hp:S.playerHp, mh:S.equippedMainhand, oh:S.equippedOffhand };
    try {
      S.equippedMainhand=null; S.equippedOffhand=null;
      S.activity = { type:'combat', playerSwungOnce:true, monsterId:null, monsterHp:100, bleedDps:20, bleedUntil:Date.now()+5000 };
      FF.applyReaverBleedTick(1000);
      ok(Math.abs(S.activity.monsterHp - 80) < 1e-6, 'Bleed chips 20 damage over 1s (20 dps)');
      S.activity.monsterHp = 5; S.activity.bleedDps = 999;
      FF.applyReaverBleedTick(1000);
      ok(S.activity.monsterHp <= 0, 'Bleed CAN land the killing blow (no 1 HP floor)');
      S.activity.monsterHp = 100; S.activity.bleedUntil = Date.now()-1;
      FF.applyReaverBleedTick(1000);
      eq(S.activity.monsterHp, 100, 'an expired Bleed deals no damage');
    } finally {
      S.activity=save.act; S.playerHp=save.hp; S.equippedMainhand=save.mh; S.equippedOffhand=save.oh;
    }
    // Behavioral (live state): the Bleed is re-based on the recent hit, every stack-second carves a Cut, and a
    // Harvest cashes the bank. Bloodletting retired -- Bloodsupper carries the heal now, so a bare kit no
    // longer lifesteals from its own Bleed.
    var bl = { mh:S.equippedMainhand, mht:S.equippedMainhandTier, oh:S.equippedOffhand, oht:S.equippedOffhandTier,
               ba:S.bodyArmor, ui:S.uniqueItems, xp:S.xp.reaver, act:S.activity, hp:S.playerHp, hh:S.reaverHarvestHasteUntil };
    var svRnd = Math.random;
    try {
      S.equippedMainhand='halfmoonaxe'; S.equippedMainhandTier=6; S.equippedMainhandRarity='normal'; S.equippedMainhandUid=null;
      S.equippedOffhand='shieldSmall'; S.equippedOffhandTier=6;
      S.bodyArmor={helmet:armor('chain'),chest:armor('chain'),gauntlets:armor('leather'),boots:armor('leather'),back:{tier:0,rarity:'normal',material:null}};
      S.uniqueItems={}; S.xp.reaver = FF.xpFloorForLevel(85);
      eq(FF.activeClassId(S), 'reaver', 'behavioral setup activates the Reaver');
      // A landed swing banks the hit and opens the wound off it -- not off a level-scaled trickle.
      S.activity = { type:'combat', playerSwungOnce:true, monsterId:FF.MONSTERS[0].id, monsterHp:1e12, tickAccum:0, monsterTickAccum:0, duelStartedAt:Date.now() };
      S.playerHp = FF.maxHp(S);
      Math.random = function(){ return 0; };
      FF.playerAttackTick(false, 1, false);
      ok((S.activity.rvBleedHitAvg||0) > 0, 'the swing banked into the Bleed base');
      ok((S.activity.bleedStacks||0) > 0, 'and opened a Bleed');
      near(S.activity.bleedDps, S.activity.bleedStacks * FF.RV_BLEED_PCT * S.activity.rvBleedHitAvg, 'the Bleed ticks off the recent hit, not off proficiency levels');
      // A second of that Bleed carves Cuts equal to the stack count, and chips the foe for real damage.
      S.activity.rvCuts = 0; S.activity.rvBank = 0; S.activity.rvCutAccum = 0;
      var stacks = S.activity.bleedStacks, hpBefore = S.activity.monsterHp;
      FF.applyReaverBleedTick(1000);
      eq(S.activity.rvCuts, stacks, 'one second of bleeding carves one Cut per stack');
      ok(S.activity.monsterHp < hpBefore, 'and the tick chipped the foe');
      // A bare kit no longer heals from its own Bleed (that is Bloodsupper's job now).
      S.playerHp = 10; FF.applyReaverBleedTick(1000);
      eq(S.playerHp, 10, 'Bloodletting retired: no lifesteal without Bloodsupper');
      // Harvest: it spends the BANK, and pre-capstone it also pays the Count back down.
      S.xp.reaver = FF.xpFloorForLevel(61); // Lv 61: Harvest, but not the Butcher's Tally
      S.activity.rvCuts = 100; S.activity.rvBank = 100; S.activity.rvBleedHitAvg = 1000;
      var hHp = S.activity.monsterHp;
      var dealt = FF.rvHarvestFire(S.activity, FF.MONSTERS[0], S);
      eq(dealt, Math.round(100 * FF.RV_HARVEST_PCT * 1000), 'the Harvest cashed the bank');
      ok(S.activity.monsterHp < hHp, 'and struck the foe');
      eq(S.activity.rvBank, 0, 'the bank is spent');
      eq(S.activity.rvCuts, 0, 'pre-capstone the ramp pays for the burst');
      // Lv 80 The Butcher's Tally: the Harvest stops spending the Count, so the ramp never reverses.
      S.xp.reaver = FF.xpFloorForLevel(85);
      S.activity.rvCuts = 100; S.activity.rvBank = 100;
      FF.rvHarvestFire(S.activity, FF.MONSTERS[0], S);
      eq(S.activity.rvBank, 0, 'the capstone still spends the bank');
      eq(S.activity.rvCuts, 100, "the Butcher's Tally leaves the Count standing");
    } finally {
      Math.random = svRnd;
      S.equippedMainhand=bl.mh; S.equippedMainhandTier=bl.mht; S.equippedOffhand=bl.oh; S.equippedOffhandTier=bl.oht;
      S.bodyArmor=bl.ba; S.uniqueItems=bl.ui; S.xp.reaver=bl.xp; S.activity=bl.act; S.playerHp=bl.hp; S.reaverHarvestHasteUntil=bl.hh;
    }
  });

  // ---- The Ronin: the Draw-Cut cycle, end to end on live state ---------------------------------------
  // The rework's whole point is that the draw REPEATS. Before it, five effects keyed off a once-per-foe flag
  // and First Blood's 8s Bleed was never re-applied, so Crimson Edge -- the Lv40 passive -- was dark for the
  // rest of every fight. These assertions are about the cycle, not the numbers.
  suite('samurai: the Draw-Cut cycle (behavioral)', function(){
    var S = FF._state;
    function armor(mat){ return { material:mat, tier:5 }; }
    var bl = { mh:S.equippedMainhand, mht:S.equippedMainhandTier, mr:S.equippedMainhandRarity, mu:S.equippedMainhandUid,
               oh:S.equippedOffhand, oht:S.equippedOffhandTier, ba:S.bodyArmor, ui:S.uniqueItems,
               xp:S.xp.samurai, act:S.activity, hp:S.playerHp, fl:S.samuraiFlowUntil };
    var svRnd = Math.random;
    try {
      S.equippedMainhand='falchion'; S.equippedMainhandTier=6; S.equippedMainhandRarity='normal'; S.equippedMainhandUid=null;
      S.equippedOffhand=null;
      S.bodyArmor={helmet:armor('leather'),chest:armor('leather'),gauntlets:armor('leather'),boots:armor('leather'),back:{tier:0,rarity:'normal',material:null}};
      S.uniqueItems={}; S.xp.samurai = FF.xpFloorForLevel(85);
      eq(FF.activeClassId(S), 'samurai', 'behavioral setup activates the Samurai');
      S.activity = { type:'combat', playerSwungOnce:true, monsterId:FF.MONSTERS[0].id, monsterHp:1e12, tickAccum:0, monsterTickAccum:0,
                     duelStartedAt:Date.now(), samuraiFocus:0, smFocusAccum:0 };
      S.playerHp = FF.maxHp(S);
      Math.random = function(){ return 0; };   // land every swing, crit every swing

      // Half of the build is the swing.
      FF.playerAttackTick(false, 1, false);
      ok((S.activity.dotHitAvg||0) > 0, 'the swing banked into the shared recent-hit base');
      eq(S.activity.samuraiFocus, FF.SM_FOCUS_PER_HIT, 'and built a stack of stance');

      // The other half is the CLOCK, and it is the reason this class functions at all: the katana swings every
      // 5s, so a hits-only stance of ten would have taken fifty seconds to fill -- one Cut per fight.
      S.activity.samuraiFocus = 0; S.activity.smFocusAccum = 0;
      FF.applySamuraiFocusTick(1000);
      eq(S.activity.samuraiFocus, Math.floor(FF.SM_FOCUS_PER_SEC), 'one second of the duel builds stance with no swing at all');
      FF.applySamuraiFocusTick(30000);
      eq(S.activity.samuraiFocus, FF.samuraiFocusCap(S), 'and it fills to a full stance');
      ok(FF.smSheathed(S), 'a full stance is sheathed -- the next strike draws');

      // The draw. It strikes, it re-sinks the Bleed, and it spends the stance down to the Zanshin refund.
      var hp0 = S.activity.monsterHp;
      var expect = Math.round(FF.smCutDamage(S) * FF.SM_CUT_CRIT_MULT);
      var dealt = FF.smDrawCutFire(S.activity, FF.MONSTERS[0], S);
      eq(dealt, expect, 'the Cut lands stance x SM_CUT_PCT x recent hit, with a FLAT x2 crit');
      ok(S.activity.monsterHp < hp0, 'and it struck the foe for real');
      eq(S.activity.samuraiFocus, FF.smCutRefund(S), 'the stance is spent down to the refund');
      ok(!FF.smSheathed(S), 'so the next strike is not another Cut -- the cycle has to be rebuilt');
      ok((S.activity.bleedStacks||0) > 0 && (S.activity.bleedUntil||0) > Date.now(), 'First Blood: every Cut re-sinks the Bleed');
      near(S.activity.bleedDps, S.activity.bleedStacks * S.activity.dotHitAvg * FF.SAMURAI_BLEED_PCT,
           'and the Bleed ticks off the recent hit, not off a sum of proficiency levels');
      ok(FF.enemyBleeding(S), 'which is what keeps Crimson Edge live for the whole fight');

      // A Cut with an empty stance is a no-op, not a free strike.
      S.activity.samuraiFocus = 0; S.activity.smFocusAccum = 0;
      eq(FF.smDrawCutFire(S.activity, FF.MONSTERS[0], S), 0, 'no stance, no Cut');

      // MANDATORY (CLAUDE.md): every damage source must be NAMED in the Combat log. The buffer is a 200-row
      // ring and is already full by the time the suite runs, so assert on the TAIL -- never on the length.
      var log = FF._combatLog();
      var found = false;
      for(var i = Math.max(0, log.length - 16); i < log.length; i++){
        if(log[i] && log[i].dir === 'skill' && /Draw-Cut/.test(log[i].spName || '')) found = true;
      }
      ok(found, 'the Draw-Cut appears in the Combat log under its own name');
    } finally {
      Math.random = svRnd;
      S.equippedMainhand=bl.mh; S.equippedMainhandTier=bl.mht; S.equippedMainhandRarity=bl.mr; S.equippedMainhandUid=bl.mu;
      S.equippedOffhand=bl.oh; S.equippedOffhandTier=bl.oht;
      S.bodyArmor=bl.ba; S.uniqueItems=bl.ui; S.xp.samurai=bl.xp; S.activity=bl.act; S.playerHp=bl.hp; S.samuraiFlowUntil=bl.fl;
    }
  });

  // ---- A failed forge must SAY SO: it already spent the materials ------------------------------------
  // Reported as "crafted rings aren't showing as material for the next tier". They were: the Chronicle logged
  // "You forged Cobalt Ring of Blunt" (that line only fires for a NORMAL roll, so the ring was the right
  // rarity), and seconds later the next tier read "1x Cobalt Ring of Blunt (0 owned)". The ring was genuinely
  // gone -- processCraftActivity consumes inputs BEFORE the success roll, and a ~24% failure destroyed it while
  // writing nothing anywhere but a toast that fades. The economy is unchanged by design (owner's call); the
  // silence is the bug.
  suite('crafting: a failed forge is never silent', function(){
    // The ladder input is the one worth naming -- it is itself the product of a whole chain of forges.
    var ringKey = 'ring_blunt_t4_normal';
    var ringName = (FF.RING_ITEMS[ringKey] || {}).name;
    ok(ringName, 'the t4 Normal Ring of Blunt exists to be named');
    var withLadder = {}; withLadder['twine_t4'] = 3; withLadder[ringKey] = 1;
    eq(FF.craftLadderInputName(withLadder), ringName, 'the previous-tier ring is picked out of the input list');
    eq(FF.craftLadderInputName({ twine_t4:3, ruby:1 }), '', 'a recipe with no ladder input names nothing');
    eq(FF.craftLadderInputName(null), '', 'and a missing input map is handled');
    // Body armour, belts and weapons ladder the same way, so the helper must cover them too.
    ok(FF.craftLadderInputName({ stweapon_falchion_t3_normal:1 }) !== '', 'weapons ladder too');
    ok(FF.craftLadderInputName({ belt_t3_normal:1 }) !== '', 'belts ladder too');

    // The behavioural half: the failure reaches the LOG, not just a floating toast.
    var S = FF._state;
    var save = S.log;
    try {
      S.log = [];
      FF.logForgeFailure('Cupronickel Ring of Blunt', withLadder);
      eq(S.log.length, 1, 'a failed forge writes exactly one log line');
      var row = S.log[0];
      eq(row.cls, 'danger', 'and it is flagged as bad news');
      ok(/Forge failed/.test(row.msg), 'it says the forge failed');
      ok(/Cupronickel Ring of Blunt/.test(row.msg), 'it names what was being forged');
      ok(new RegExp(ringName).test(row.msg), 'and it names the ladder piece that was consumed');
      // No ladder input -> still logged, just without the "including" clause.
      S.log = [];
      FF.logForgeFailure('Elephant Twine', { hide_t4:2 });
      eq(S.log.length, 1, 'a non-ladder craft still logs its failure');
      ok(!/including/.test(S.log[0].msg), 'without claiming a ladder piece was lost');
    } finally { S.log = save; }
  });

  // ---- Painted class art: additive, per class, and never leaves a hole ------------------------------
  suite('class art: the painted icons are additive only', function(){
    var ids = Object.keys(FF.CLASS_ART);
    ok(ids.length > 0, 'at least one class carries painted art');
    // A typo in a key would silently do nothing forever, so every key must be a real class id and every
    // path must live under art/ with the id in its filename.
    ids.forEach(function(cid){
      ok(!!FF.CLASS_DEFS_BY_ID[cid], 'CLASS_ART key "'+cid+'" is a real class id');
      ok(/^art\/[a-zA-Z]+\.(png|webp)$/.test(FF.CLASS_ART[cid]), cid+' art path is a relative art/ file');
      // The file is named after the class's player-facing NAME (lowercased), which is what an artist
      // delivers -- the Nightblade's art is voidshadow.png. Accept either that or the raw id, so a real
      // typo still fails but a legitimate name/id mismatch does not.
      var base = FF.CLASS_ART[cid].replace(/^art\//, '').replace(/\.(png|webp)$/, '').toLowerCase();
      var want = [cid.toLowerCase(), String(FF.CLASS_DEFS_BY_ID[cid].name || '').toLowerCase().replace(/[^a-z]/g, '')];
      ok(want.indexOf(base) !== -1, cid+' art filename ("'+base+'") matches its id or its class name');
    });
    var ready = FF._classArtReady();
    var cid0 = ids[0];
    var svSt = ready[cid0];
    try {
      // NOT loaded (the suite runs headless, so nothing has decoded): every surface keeps its SVG.
      delete ready[cid0];
      eq(FF.classArtHtml(cid0), '', 'unloaded art contributes nothing');
      var svg = FF.classPortraitFor(cid0);
      ok(/^<svg/.test(svg), 'the leaderboard falls back to the authored SVG portrait');
      var cd = FF.CLASS_DEFS_BY_ID[cid0];
      eq(FF.classCardIcon(cd), cd.icon, 'the Classes card falls back to its small crest');
      // LOADED: the same three surfaces swap to the painted icon.
      ready[cid0] = true;
      var art = FF.classArtHtml(cid0);
      ok(/^<img /.test(art), 'loaded art renders an img');
      ok(/class="game-icon cls-art"/.test(art), 'it carries .game-icon so every container sizes it already');
      ok(art.indexOf(FF.CLASS_ART[cid0]) !== -1, 'and points at the declared file');
      eq(FF.classPortraitFor(cid0), art, 'the leaderboard now shows the painted icon');
      eq(FF.classCardIcon(cd), art, 'and so does the Classes card');
      // A class with no art is untouched either way -- this is the "never leaves a hole" guarantee.
      var other = FF.CLASS_DEFS.filter(function(c){ return !FF.CLASS_ART[c.id]; })[0];
      if(other){
        eq(FF.classArtHtml(other.id), '', 'a class without art contributes nothing');
        ok(/^<svg/.test(FF.classPortraitFor(other.id)), 'and keeps its authored portrait');
        eq(FF.classCardIcon(other), other.icon, 'and its card keeps its crest');
      }
    } finally { if(svSt === undefined) delete ready[cid0]; else ready[cid0] = svSt; }
  });

  // ---- Tooltip coverage: every skill that renders a (?) info button must carry a SKILL_INFO blurb ---
  // (The info button only shows when SKILL_INFO[id] exists, so a missing entry silently drops the tooltip.)
  suite('skill info: every skill has a tooltip', function(){
    var INFO = FF.SKILL_INFO;
    ok(INFO && typeof INFO === 'object', 'SKILL_INFO is exposed');
    var cats = {
      classes: FF.CLASS_SKILL_IDS,
      gathering: FF.GATHER_SKILL_IDS,
      crafting: FF.CRAFT_SKILL_IDS,
      weapons: FF.WEAPON_STYLE_IDS,
      offhands: FF.OFFHAND_STYLE_IDS,
      'armor proficiencies': FF.ARMOR_PROFICIENCY_IDS,
      faith: FF.FAITH_SKILL_IDS
    };
    Object.keys(cats).forEach(function(cat){
      var ids = cats[cat] || [];
      var missing = ids.filter(function(id){ return !INFO[id]; });
      ok(missing.length === 0, cat + ': all have a SKILL_INFO tooltip' + (missing.length ? ' (missing: ' + missing.join(', ') + ')' : ''));
    });
    // Spot-check the classes that had been missing before this pass.
    ['frostwarden','plaguebearer','berserker','sentinel','spellblade','pyromancer','sharpshooter','juggernaut','nightblade','executioner','lumen','reaver'].forEach(function(id){
      ok(typeof INFO[id] === 'string' && INFO[id].length > 20, id + ' has a class tooltip');
    });
  });

  // ---- Gadgets: Salvaging -> Tinkering (Bombs) + Pyrotechnics (Flash Bombs) --------------------
  suite('skills: salvaging / tinkering / pyrotechnics', function(){
    ok(FF.GATHERING_SKILLS.salvaging, 'salvaging is a gathering skill');
    ok(FF.CRAFTING_SKILLS.tinkering, 'tinkering is a crafting skill');
    ok(FF.CRAFTING_SKILLS.pyrotechnics, 'pyrotechnics is a crafting skill');
    eq(FF.GATHERING_SKILLS.salvaging.items.length, FF.TIER_COUNT, 'salvaging has 21 scrap tiers');
    eq(FF.CRAFTING_SKILLS.tinkering.recipes.length, FF.TIER_COUNT, 'tinkering has 21 bomb tiers');
    eq(FF.CRAFTING_SKILLS.pyrotechnics.recipes.length, FF.TIER_COUNT, 'pyrotechnics has 21 flash tiers');
    eq(FF.ALL_GATHER_ITEMS['salvaging_t0'].name, 'Rusty Scrap', 'salvaging sifts Scrap');
    // Tinkering bombs need scrap + metal (no glass bottle); Pyrotechnics needs powder + scrap.
    var bomb5 = FF.ALL_CRAFT_RECIPES['bomb_t5'];
    ok(bomb5.inputs['salvaging_t5'] && bomb5.inputs['metallurgy_t5'] && !bomb5.inputs['metallurgy_glass'], 'bomb = scrap + metal, no glass bottle');
    var flash5 = FF.ALL_CRAFT_RECIPES['flash_t5'];
    ok(flash5.inputs['powder_t5'] && flash5.inputs['salvaging_t5'], 'flash bomb = powder + scrap');
    // Both are 5th/6th... two new combat-consumable lines.
    ok(FF.POTION_TYPE_IDS.indexOf('bomb') !== -1 && FF.POTION_TYPE_IDS.indexOf('flash') !== -1, 'bomb + flash are combat-consumable lines');
    eq(bomb5.potionType, 'bomb', 'bomb recipe carries potionType');
    eq(flash5.potionType, 'flash', 'flash recipe carries potionType');
    // Bomb: burst damage that scales and beats a Firebomb; Flash: stun chance that scales.
    var b0 = FF.potionEffect('bomb_t0'), b20 = FF.potionEffect('bomb_t20');
    ok(b0.type==='bomb' && b20.dmg > b0.dmg, 'bomb burst scales with tier');
    // Bomb is still a FLAT number (10 at t0 to 350 at t20) and is therefore still ~9 orders of magnitude
    // under a best-in-slot hit of ~1e11. The Firebomb was fixed to a share of the recent hit; Bomb was
    // DELIBERATELY left alone, because it belongs to Tinkering and the owner asked for the Firebomb only.
    // This assertion exists so the deferral is recorded rather than forgotten: when Bomb is fixed, it will
    // fail, and that is the reminder to delete it.
    ok(typeof b20.dmg === 'number' && b20.dmg < 1000, 'Bomb is still the flat, dead burst line (Tinkering, deferred on purpose)');
    ok(FF.potionEffect('firebomb_t20').dmg === undefined, 'the Firebomb no longer carries a flat damage number');
    var f0 = FF.potionEffect('flash_t0'), f20 = FF.potionEffect('flash_t20');
    ok(f0.type==='flash' && f20.stun > f0.stun && f20.stun <= 0.20 + 1e-9, 'flash stun chance scales with tier (cap 20%)');
    ok(/burst damage/.test(FF.potionEffectDesc('bomb_t10')), 'bomb describes its burst');
    ok(/stun/.test(FF.potionEffectDesc('flash_t10')), 'flash describes its stun');
    ok(FF.GATHER_PHYSIQUE.salvaging && FF.CRAFT_PHYSIQUE.tinkering && FF.CRAFT_PHYSIQUE.pyrotechnics, 'physique tables include the new skills');
  });

  // ---- Arcane: Essence Harvesting -> Inscription + the Scroll (ward) buff ----------------------
  suite('skills: essence / inscription', function(){
    ok(FF.GATHERING_SKILLS.essence, 'essence harvesting is a gathering skill');
    ok(FF.CRAFTING_SKILLS.inscription, 'inscription is a crafting skill');
    eq(FF.GATHERING_SKILLS.essence.items.length, FF.TIER_COUNT, 'essence has 21 tiers');
    eq(FF.CRAFTING_SKILLS.inscription.recipes.length, FF.TIER_COUNT, 'inscription has 21 scroll tiers');
    eq(FF.ALL_GATHER_ITEMS['essence_t0'].name, 'Faint Mote', 'essence taps Aether/Motes');
    // Chain: Essence + Paper (from Papermaking) -> Scroll.
    var scr5 = FF.ALL_CRAFT_RECIPES['scroll_t5'];
    ok(scr5.inputs['essence_t5'] && scr5.inputs['paper_t5'], 'scroll binds Essence + Paper (interlocks Papermaking)');
    // Scroll = a timed damage-reduction ward -- its own channel.
    ok(scr5.scrollBonus > 0 && scr5.scrollDurationMs > 0, 'scrolls carry a timed ward buff');
    var s0 = FF.ALL_CRAFT_RECIPES['scroll_t0'], s20 = FF.ALL_CRAFT_RECIPES['scroll_t20'];
    ok(s20.scrollBonus > s0.scrollBonus && s20.scrollBonus <= 0.30 + 1e-9, 'ward scales with tier (cap 30%)');
    // Reading a scroll reduces incoming damage; none by default.
    eq(FF.scrollDamageReduction(), 0, 'no ward by default');
    FF._state.inventory['scroll_t10'] = 1;
    FF.readScroll('scroll_t10');
    ok(FF.isScrollActive(), 'reading a scroll activates the ward');
    ok(FF.scrollDamageReduction() > 0 && FF.scrollDamageReduction() <= 0.30 + 1e-9, 'active ward reduces incoming damage');
    ok(FF.CRAFT_PHYSIQUE.inscription && FF.GATHER_PHYSIQUE.essence, 'physique tables include the new skills');
  });

  // ---- Inventory grid: rarity parsing for cell accents / detail tag ----------------------
  suite('inventory rarity', function(){
    eq(FF.itemRarityId('bodyarmor_chain_chest_t20_normal'), 'normal', 'normal suffix');
    eq(FF.itemRarityId('stweapon_rapier_t5_rare'), 'rare', 'rare suffix');
    eq(FF.itemRarityId('relic_t8_supreme'), 'supreme', 'supreme suffix');
    eq(FF.itemRarityId('amulet_t3_fantastic'), 'fantastic', 'fantastic suffix');
    eq(FF.itemRarityId('mining_t7'), 'normal', 'no rarity suffix -> normal');
  });

  // ---- Chat system announcements: only supreme/fantastic crafts echo into global chat ----
  suite('craft chat announce', function(){
    eq(FF.craftBodyRarity('Fantastic Steel Axe'), 'fantastic', 'fantastic craft body -> fantastic');
    eq(FF.craftBodyRarity('Supreme Iron Sword'), 'supreme', 'supreme craft body -> supreme');
    eq(FF.craftBodyRarity('Rare Bronze Dagger'), null, 'rare craft body -> null (chronicle only)');
    eq(FF.craftBodyRarity('Oak Plank'), null, 'normal craft body -> null');
    eq(FF.craftBodyRarity(''), null, 'empty body -> null');
  });

  // ---- Classes: Plaguebearer (the Plague -- poison with a severity) --------------------
  suite('classes: plaguebearer (the Plague)', function(){
    function arm(mat){ return {material:mat,tier:5}; }
    function pbSt(level, extra){
      var st = { xp:{}, physique:{}, equippedMainhand:'hatchet', equippedOffhand:'shieldSmall',
                 bodyArmor:{helmet:arm('leather'),chest:arm('leather'),gauntlets:arm('tailoring'),boots:arm('leather')},
                 activity:{type:'combat', playerSwungOnce:true,monsterHp:1e9,dotHitAvg:1000}, playerHp:100, uniqueItems:{} };
      st.xp.plaguebearer = FF.xpFloorForLevel(level);
      if(extra) for(var k in extra) st[k]=extra[k];
      return st;
    }
    eq(FF.activeClassId(pbSt(85)), 'plaguebearer', 'hatchet + small shield + leather/cloth => Plaguebearer');
    var cd = FF.CLASS_DEFS_BY_ID.plaguebearer;
    eq(cd.passives.map(function(p){ return p.name; }).join(','), 'Septic,Contagion,Toxic Blood,Incubation,Pandemic', 'the Plague ladder');

    // Severity: raised by hits, capped, and LOST if the Plague lapses.
    var p = pbSt(85);
    eq(FF.pbSeverity(p), 0, 'a fresh foe is uninfected');
    FF.pbPlagueAdd(3, p);
    ok(FF.pbSeverity(p) > 0, 'hits raise severity');
    FF.pbPlagueAdd(999, p);
    eq(FF.pbSeverity(p), FF.pbSevCap(p), 'severity has a cap');
    p.activity.pbUntil = Date.now() - 1;
    FF.pbPlagueAdd(1, p);
    ok(FF.pbSeverity(p) < FF.pbSevCap(p), 'a LAPSED Plague starts over -- the cost of dropping uptime');

    // The tick derives from severity x the recent hit, and is never REPLACED into the shared channel.
    var d = pbSt(85); FF.pbPlagueAdd(10, d);
    near(FF.pbPlagueDps(d), FF.PB_TICK_PCT * FF.pbSeverity(d) * 1000, 'the Plague ticks off severity x the recent average hit');
    ok((d.activity.potionPoisonDps||0) > 0, 'and it DERIVES the shared poison channel so every reader still works');
    ok((d.activity.potionPoisonUntil||0) > Date.now(), 'including the duration every reader checks');
    // A stronger foreign poison is not weakened by the sync (max wins).
    var f = pbSt(85); f.activity.potionPoisonDps = 1e9; f.activity.potionPoisonUntil = Date.now()+9999;
    FF.pbPlagueAdd(1, f);
    eq(f.activity.potionPoisonDps, 1e9, 'a stronger foreign poison survives the sync');

    // Contagion scales with severity (was a flat +15%).
    var c = pbSt(85); FF.pbPlagueAdd(10, c);
    near(FF.pbContagionMult(c), 1 + FF.PB_CONTAGION_PCT * FF.pbSeverity(c), 'Contagion scales with severity');
    var c1 = pbSt(1); FF.pbPlagueAdd(10, c1);
    near(FF.pbContagionMult(c1), 1, 'Contagion needs Lv20');

    // Blightfang raises the CAP -- strong here because this engine SUSTAINS at the cap rather than cycling.
    var bf = pbSt(85, { uniqueItems:{ L:{ uid:'L', leg:'blightfang', kind:'weapon', base:'stweapon_hatchet_t20_rare', tier:20, rarity:'rare', enchants:[], enhance:0 } }, equippedMainhandUid:'L' });
    eq(FF.pbSevCap(bf), Math.round(FF.PB_SEV_MAX * FF.PB_SEV_CAP_BLIGHTFANG), 'Blightfang: the severity cap rises by half');
    // Wasting Curse raises the RATE.
    // Wasting Curse acts on eruption FREQUENCY, not severity rate: a rate bonus is near-worthless in a
    // SUSTAINED engine, where severity already sits at its cap so filling it faster does nothing. It measured
    // LAST of the four hatchets on the rate axis (61.4B against a 79.6B pack mean).
    near(FF.PB_ERUPT_MS_WASTING, 0.5, 'Wasting Curse halves the eruption cadence');

    // Pandemic only erupts at MAX severity, and it does not spend it (the engine sustains).
    var e = pbSt(85); FF.pbPlagueAdd(999, e);
    eq(FF.pbSeverity(e), FF.pbSevCap(e), 'terminal at the cap');
    var svR = Math.random;
    try { Math.random = function(){ return 0.999; };
      var before = FF.pbSeverity(e);
      FF.pbEruptFire(e.activity, e);
      eq(FF.pbSeverity(e), before, 'an eruption does NOT spend severity');
    } finally { Math.random = svR; }
    var ne = pbSt(85); FF.pbPlagueAdd(1, ne);
    eq(FF.pbEruptFire(ne.activity, ne), 0, 'and nothing erupts below the cap');

    // The band knob + its damage row.
    near(FF.PB_SWING_MULT, FF.PB_SWING_MULT, 'the Septic channel is the band knob');
    ok(FF.PLAYER_DMG_MODS.some(function(r){ return r.name === 'plaguebearerSeptic'; }), 'the Septic channel is a named PLAYER_DMG_MODS row');
  });

  // ---- The shared damage-over-time base (dotBase) -------------------------------------
  // Every DoT in the game used to tick for a fraction of combatLevelEquivalent() -- a SUM OF PROFICIENCY
  // LEVELS, ~600 at max -- so at best-in-slot, where hits are ~1e11, a fully stacked Burn dealt about 150
  // damage a second: eight to nine orders of magnitude too small to matter. Weapon coatings fed a mechanic
  // that did nothing at all. Everything now ticks off the recent-hit EMA instead.
  suite('dots: every ailment scales off the recent hit, not proficiency levels', function(){
    var S = FF._state;
    var sv = { act:S.activity, mh:S.equippedMainhand, oh:S.equippedOffhand };
    try {
      // With a banked hit average, dotBase reads it -- and it is enormous next to a level sum.
      S.activity = { type:'combat', playerSwungOnce:true, monsterHp:1e12, dotHitAvg: 1e9 };
      eq(FF.dotBase(S), 1e9, 'dotBase reads the fight\'s banked hit average');
      // Fallback: a DoT applied before your first landed hit (a reflect, a Block, an opening ailment) still
      // does something rather than nothing.
      S.activity = { type:'combat', playerSwungOnce:true, monsterHp:1e12, dotHitAvg: 0 };
      ok(FF.dotBase(S) >= 1, 'with no hit banked yet it falls back to the old level-based figure');
      ok(FF.dotBase(S) < 1e6, 'and that fallback is the small, level-scaled number');

      // Decay: applied by ~20 sources and lands on already-banded classes, so its coefficient is deliberately
      // small -- at the 10-stack cap it is worth ~6% of a hit per second.
      near(FF.DECAY_PCT, 0.010, 'Decay pays 1% of a hit per stack per second (retuned for the real applier count, v0.0.96.31)');
      eq(FF.DECAY_MAX_STACKS, 10, 'Decay caps at 10 stacks');
      near(FF.DECAY_PCT * FF.DECAY_MAX_STACKS, 0.10, 'so a fully stacked Decay is ~10% of a hit per second');
      // Rotshell's block-poison is incidental too, and scaled to match.
      near(FF.LEG_ROTSHELL_PCT, 0.03, 'Rotshell poisons for 3% of a hit per second');

      // Behavioral: a real Decay application now scales with the banked hit, and a bigger hit means a bigger
      // Decay -- the property that was completely absent before.
      S.equippedMainhand = null; S.equippedOffhand = null;
      S.activity = { type:'combat', playerSwungOnce:true, monsterHp:1e12, dotHitAvg: 1e6 };
      FF.decayApply(S.activity, FF.DECAY_MAX_STACKS);
      var small = S.activity.decayDps;
      S.activity = { type:'combat', playerSwungOnce:true, monsterHp:1e12, dotHitAvg: 1e9 };
      FF.decayApply(S.activity, FF.DECAY_MAX_STACKS);
      ok(S.activity.decayDps > small * 900, 'a thousand-fold bigger hit means a ~thousand-fold bigger Decay');
      near(S.activity.decayDps, FF.DECAY_MAX_STACKS * 1e9 * FF.DECAY_PCT, 'Decay = stacks x hit average x 0.6%');
    } finally {
      S.activity = sv.act; S.equippedMainhand = sv.mh; S.equippedOffhand = sv.oh;
    }
  });

  // ---- Alchemy combat potions: 4 types, linear t0->t20 effect scaling ----
  suite('alchemy potions', function(){
    // Poison is now a share of the RECENT AVERAGE HIT per second, not of summed proficiency levels (see the
    // dotBase suite below) -- so the coefficients came down hard while the actual damage went up enormously.
    near(FF.potionEffect('toxin_t0').pct, 0.003, 'toxin t0 = 0.3% of a hit/s');
    near(FF.potionEffect('toxin_t20').pct, 0.03, 'toxin t20 = 3% of a hit/s');
    eq(FF.potionEffect('coating_t20'), null, 'coatings no longer resolve as potions (removed v0.0.96.34)');
    // THE FIREBOMB IS THE OPENER now. It used to deal a FLAT 5 at t0 rising to 210 at t20, against
    // best-in-slot hits of ~1e11 -- two parts per billion, the dead-scale bug in burst form. It now pays a
    // share of the recent landed hit, hugely on the first strike against a fresh foe and almost nothing
    // afterwards, which makes it the farming flask to the clocked Toxin's sustain.
    var fb0 = FF.potionEffect('firebomb_t0'), fb20 = FF.potionEffect('firebomb_t20');
    near(fb0.opener, 0.15, 'firebomb t0 opens for 15% of a hit');
    near(fb20.opener, 1.50, 'firebomb t20 opens for 150% of a hit');
    ok(fb20.opener > fb0.opener && fb20.smoulder > fb0.smoulder, 'both halves scale with tier');
    ok(fb20.smoulder * 20 < fb20.opener, 'the smoulder is an order of magnitude under the opener, so it stays the OPENER');
    ok(fb20.opener > FF.potionEffect('toxin_t20').pct, 'and the opener dwarfs a toxin tick, which is the point of the split');    eq(Math.round(FF.potionEffect('elixir_t0').crit*100), 5, 'elixir t0 = +5% crit dmg');
    eq(Math.round(FF.potionEffect('elixir_t20').crit*100), 110, 'elixir t20 = +110% crit dmg');
    eq(Math.round(FF.potionEffect('catalyst_t0').fam*100), 5, 'catalyst t0 = +5% familiar');
    eq(Math.round(FF.potionEffect('catalyst_t20').fam*100), 110, 'catalyst t20 = +110% familiar');
    eq(FF.potionEffect('mining_t0'), null, 'non-potion id -> null');
    // every alchemy recipe requires the matching-tier Glassblowing glass (Metallurgy's flat Glass
    // Bottle side-recipe is retired) + covers its 4 types x tiers (enchant is a separate Enchanting line)
    var alc = FF.CRAFTING_SKILLS_ALCHEMY.recipes;
    ok(alc.every(function(r){ return !r.inputs['metallurgy_glass']; }), 'no alchemy recipe still uses the retired metallurgy_glass');
    ok(alc.every(function(r){ var m=/_t(\d+)$/.exec(r.id); return m && r.inputs['glassblowing_t'+m[1]] === 1; }), 'every alchemy recipe needs 1 tier-matched Glassblowing glass');
    ['toxin','firebomb','elixir','catalyst'].forEach(function(t){
      ok(alc.some(function(r){ return r.id===t+'_t0'; }) && alc.some(function(r){ return r.id===t+'_t20'; }), t+' alchemy line spans t0..t20');
    });
  });

  // ---- Faith XP reworked from exponential to the linear Crafting curve ----
  suite('faith xp linear', function(){
    var P = FF.PRAYER_TIERS;
    eq(P[0].xp, FF.craftXp(0), 'prayer t0 xp = craftXp(0) = 25');
    eq(P[20].xp, FF.craftXp(20), 'prayer t20 xp = craftXp(20) = 325');
    eq(P[5].xp - P[4].xp, P[15].xp - P[14].xp, 'prayer xp step is constant (linear, not exponential)');
    // channeled faith activities: xp/s ramps linearly, not by 1.25^i
    var D = FF.FAITH_ACTIVITY_TIERS.devotion;
    eq(D[0].xpPerSec, 2, 'devotion t0 xp/s = base 2');
    eq(D[20].xpPerSec, 26, 'devotion t20 xp/s = 2*(1+0.6*20) = 26');
    eq(Math.round((D[10].xpPerSec - D[9].xpPerSec)*100), Math.round((D[20].xpPerSec - D[19].xpPerSec)*100), 'devotion xp/s step is constant (linear)');
  });

  // ---- Familiar spell kits: every familiar has a unique 4-spell kit, all describable ----
  suite('familiar kits', function(){
    var ids = Object.keys(FF.FAMILIAR_DATA);
    var sigs = {}, dupe = null, allFour = true, allDesc = true;
    ids.forEach(function(id){
      var sp = FF.FAMILIAR_DATA[id].spells || [];
      if(sp.length !== 4) allFour = false;
      sp.forEach(function(s){ if(!FF.describeSpell(s, 5)) allDesc = false; });
      var sig = sp.map(function(s){ return s.type + (s.kind?(':'+s.kind):'') + (s.dmgType?(':'+s.dmgType):''); }).sort().join('|');
      if(sigs[sig]) dupe = sigs[sig] + ' & ' + id; else sigs[sig] = id;
    });
    ok(allFour, 'every familiar has exactly 4 spells');
    ok(allDesc, 'every spell produces a non-empty description');
    ok(!dupe, 'every familiar kit is a unique effect combination' + (dupe ? ' -- dupe: ' + dupe : ''));
    // spot-check a couple of new spell types describe sensibly
    ok(/damage/.test(FF.describeSpell({type:'hit',dmgType:'piercing',amount:14}, 1)), 'hit spell describes damage');
    ok(/HP \/ 5s/.test(FF.describeSpell({type:'regen',hps:4,durationMs:6000}, 1)), 'regen spell describes HP per 5s');
    // Familiar Haste text is capped at -50% attack time (matching the 200% attack-speed combat cap).
    var hasteHi = FF.describeSpell({type:'timedBuff',kind:'haste',val:0.18,durationMs:8000}, 100); // Lv100 potency inflates the raw value far past 50%
    ok(/-50% attack time \(capped\)/.test(hasteHi), 'an over-cap Haste spell shows -50% (capped), not the raw value');
    var hasteLo = FF.describeSpell({type:'timedBuff',kind:'haste',val:0.10,durationMs:8000}, 1);
    var _hlm = /-(\d+)% attack time/.exec(hasteLo);
    ok(_hlm && parseInt(_hlm[1],10) <= 50, 'the displayed Haste never exceeds -50% attack time');
    ok(/killing blow/.test(FF.describeSpell({type:'bubble',durSec:3}, 1)), 'bubble spell describes killing blow');
    // Familiar regen rework: base value doubled, buff duration tripled (regenSpell('Patch Job',4,6)).
    var patch = FF.FAMILIAR_SPELLS.salvaging.filter(function(s){ return s.type==='regen'; })[0];
    ok(patch, 'salvaging familiar has a regen spell');
    eq(patch.hps, 8, 'familiar regen base value doubled (4 -> 8 HP per 5s)');
    eq(patch.durationMs, 18000, 'familiar regen buff duration tripled (6s -> 18s)');
  });

  // ---- Content rebuilds keep inner scrollers in place (Marketplace Sell picker snapped to top) -------
  suite('render: inner scrollers survive a content rebuild', function(){
    ok(typeof FF.scrollSnapshot === 'function' && typeof FF.scrollRestore === 'function', 'scroll snapshot helpers exported');
    var host = document.createElement('div');
    var panel = '<div id="ssTestPanel" style="height:60px;overflow:auto"><div style="height:600px"></div></div>';
    host.innerHTML = panel;
    document.body.appendChild(host);
    try {
      document.getElementById('ssTestPanel').scrollTop = 150;
      var snap = FF.scrollSnapshot(host);
      ok(snap && snap.ssTestPanel && snap.ssTestPanel[0] === 150, 'scrollSnapshot records a scrolled panel by id');
      host.innerHTML = panel;                       // simulate the full innerHTML rebuild render() does
      eq(document.getElementById('ssTestPanel').scrollTop, 0, 'a rebuild really does reset the scroller (the bug)');
      FF.scrollRestore(snap);
      eq(document.getElementById('ssTestPanel').scrollTop, 150, 'scrollRestore puts the rebuilt panel back where the player was');
      ok(FF.scrollSnapshot(document.createElement('div')) === null, 'an unscrolled tree snapshots to null (no work on restore)');
      FF.scrollRestore(null);                       // must be a safe no-op
      ok(true, 'scrollRestore(null) is a safe no-op');
    } finally { document.body.removeChild(host); }
  });

  // ---- A rebuilt <select> keeps the player's choice (guild-bank deposit picker reset to top) ----------
  suite('render: select pickers survive a content rebuild', function(){
    var host = document.createElement('div');
    // A read-on-submit picker (no baked `selected`, like guildBankDepositItem) and a stateful one (baked).
    var markup = '<select id="ssSel"><option value="a">A</option><option value="b">B</option><option value="c">C</option></select>'
               + '<select id="ssBaked"><option value="x">X</option><option value="y" selected>Y</option></select>';
    host.innerHTML = markup;
    document.body.appendChild(host);
    try {
      document.getElementById('ssSel').value = 'c';           // the player picked the 3rd item
      var snap = FF.inputSnapshot(host);
      ok(snap && snap.ssSel && snap.ssSel.v === 'c', 'inputSnapshot records the select choice by id');
      host.innerHTML = markup;                                // the rebuild resets it to the first option
      eq(document.getElementById('ssSel').value, 'a', 'a rebuild really does snap the select to the top (the bug)');
      FF.inputRestore(snap);
      eq(document.getElementById('ssSel').value, 'c', 'inputRestore puts the choice back');
      // A select whose markup bakes its own `selected` state is the render's to control -- left alone.
      document.getElementById('ssBaked').value = 'x';
      var snap2 = FF.inputSnapshot(host);
      host.innerHTML = markup;
      FF.inputRestore(snap2);
      eq(document.getElementById('ssBaked').value, 'y', 'a select with a baked selected attribute is never clobbered');
      // A choice whose option vanished in the rebuild (e.g. the stack was fully deposited) stays on a valid option.
      host.innerHTML = markup;
      document.getElementById('ssSel').value = 'c';
      var snap3 = FF.inputSnapshot(host);
      host.innerHTML = '<select id="ssSel"><option value="a">A</option><option value="b">B</option></select>'; // "c" is gone
      FF.inputRestore(snap3);
      eq(document.getElementById('ssSel').value, 'a', 'a vanished choice falls back to the first option instead of an invalid value');
    } finally { document.body.removeChild(host); }
  });

  suite('familiars: direct-damage spells scale from a T2 weapon (Lv1) to a Rare top weapon (Lv100)', function(){
    var wl = FF.STACKABLE_WEAPON_ITEMS;
    var t2 = wl['stweapon_rapier_t2_normal'], topRare = wl['stweapon_rapier_t19_rare']; // rapier: clean 1h, no dmgMult
    ok(t2 && topRare, 'reference rapier tiers resolve (Tier-2 normal + Rare top tier)');
    // A reference spell (amount 15) reads like a Tier-2 weapon at Lv1 and a Rare top-tier weapon at Lv100.
    var l1 = FF.familiarHitLevelDamage(1, FF.FAM_HIT_REF_AMOUNT), l100 = FF.familiarHitLevelDamage(100, FF.FAM_HIT_REF_AMOUNT);
    ok(l1 >= t2.dmgMin && l1 <= t2.dmgMax, 'Lv1 reference spell sits in the Tier-2 weapon raw range ('+t2.dmgMin+'-'+t2.dmgMax+'), got '+Math.round(l1*10)/10);
    ok(l100 >= topRare.dmgMin && l100 <= topRare.dmgMax, 'Lv100 reference spell sits in the Rare top-tier weapon raw range ('+topRare.dmgMin+'-'+topRare.dmgMax+'), got '+Math.round(l100));
    // Monotonic climb, and far steeper than the old +5%/lvl linear potency (~6x) it replaced.
    var prev = -1, mono = true; for(var lv=1; lv<=100; lv++){ var d = FF.familiarHitLevelDamage(lv, 15); if(d < prev) mono = false; prev = d; }
    ok(mono, 'familiar hit damage climbs monotonically from Lv1 to Lv100');
    ok(l100 / l1 > 8, 'the Lv1 -> Lv100 climb is ~10x (the v0.0.96.6 linear weapon ladder compresses the anchors; still steeper than the ~6x linear potency)');
    // Per-spell weighting preserved: a higher-amount spell hits harder at the same level.
    ok(FF.familiarHitLevelDamage(50,16) > FF.familiarHitLevelDamage(50,13), 'a higher-amount spell hits harder at the same level');
    // Heals/buffs keep the gentle linear potency (unchanged) -- only direct damage got the steep curve.
    ok(Math.abs(FF.familiarPotencyMult(100) / FF.familiarPotencyMult(1) - 5.95) < 0.5, 'non-damage potency still ~6x at Lv100 (linear, unchanged)');
    // Every hit/siphon spell across every familiar lands in the weapon bands at both ends.
    var bad1 = [], bad100 = [];
    Object.keys(FF.FAMILIAR_SPELLS).forEach(function(k){
      FF.FAMILIAR_SPELLS[k].forEach(function(s){
        if(s.type!=='hit' && s.type!=='siphon') return;
        var d1 = FF.familiarHitLevelDamage(1, s.amount), d100 = FF.familiarHitLevelDamage(100, s.amount);
        if(!(d1 >= t2.dmgMin && d1 <= t2.dmgMax)) bad1.push(k+':'+s.name+'='+(Math.round(d1*10)/10));
        if(!(d100 >= topRare.dmgMin && d100 <= topRare.dmgMax)) bad100.push(k+':'+s.name+'='+Math.round(d100));
      });
    });
    ok(bad1.length===0, 'every hit/siphon at Lv1 lands in the Tier-2 weapon raw range' + (bad1.length?': '+bad1.slice(0,5).join(', '):''));
    ok(bad100.length===0, 'every hit/siphon at Lv100 lands in the Rare top-tier weapon raw range' + (bad100.length?': '+bad100.slice(0,5).join(', '):''));
    // Poison DoT familiars ride the SAME steep curve: a poison's per-application total (dps*duration) is
    // weighted through familiarHitLevelDamage, so poison keeps pace at Lv100 instead of falling behind.
    var pL1 = FF.familiarHitLevelDamage(1, 6*6), pL100 = FF.familiarHitLevelDamage(100, 6*6);
    ok(pL100 / pL1 > 8, 'poison per-application total climbs on the same ~10x curve as direct hits');
  });

  // ---- Familiar companion avatars: every familiar has a bespoke avatar with its skill crest ----
  suite('familiar avatars', function(){
    var ids = Object.keys(FF.FAMILIAR_DATA);
    var missing = ids.filter(function(id){ return !FF.FAM_SKIN[id]; });
    eq(missing.length, 0, 'every familiar has an avatar skin' + (missing.length?': missing '+missing.join(','):''));
    var svgOk = ids.every(function(id){ var s = FF.familiarAvatar(id); return typeof s==='string' && s.indexOf('<svg')===0 && s.indexOf('fam-avatar')>-1; });
    ok(svgOk, 'familiarAvatar returns a fam-avatar svg for every familiar');
    // each avatar embeds its skill emblem shape
    var emblemOk = ids.every(function(id){ return FF.familiarAvatar(id).indexOf('#shape-'+FF.FAM_SKIN[id].s) > -1; });
    ok(emblemOk, 'each avatar holds its skill emblem shape');
    eq(FF.familiarAvatar('mining').indexOf('#shape-ore') > -1, true, 'mining familiar holds the ore crest');
    // Every familiar-eligible skill (gathering/crafting/farming/faith/physique) has a COMPLETE familiar:
    // a 4-spell kit, an avatar skin, and a channelled element. Guards the "a familiar for every skill" fill.
    var missingFam = FF.FAMILIAR_SKILL_IDS.filter(function(id){ var f=FF.FAMILIAR_DATA[id]; return !(f && f.spells && f.spells.length===4 && FF.FAM_SKIN[id] && FF.FAMILIAR_ELEMENT[id]); });
    eq(missingFam.length, 0, 'every skill has a complete familiar' + (missingFam.length?': missing '+missingFam.join(','):''));
    // spot-check a couple of the newly-filled utility-physique familiars
    ok(FF.FAMILIAR_DATA.merchantsSavvy && FF.FAMILIAR_DATA.merchantsSavvy.spells.length===4, "Merchant's Savvy has a familiar");
    ok(FF.FAMILIAR_DATA.zealotry && FF.FAMILIAR_DATA.zealotry.spells.length===4, 'Zealotry has a familiar');
    // famMix midpoint of black and white is grey
    eq(FF.famMix('#000000','#ffffff',0.5), '#808080', 'famMix 50% black/white -> grey');
  });

  // ---- Inventory category sort: group each item's tiers by family, then order by tier -----
  suite('inventory family sort', function(){
    eq(FF.invFamilyKey('digging_t2'), 'digging', 'strips tier -> family');
    eq(FF.invFamilyKey('bodyarmor_chain_chest_t5_rare'), 'bodyarmor_chain_chest', 'strips tier+rarity -> family');
    eq(FF.invFamilyKey('coal'), 'coal', 'no tier -> whole id');
    var ids = ['forestry_t1','digging_t2','digging_t0','forestry_t0'];
    var sorted = ids.slice().sort(function(a,b){
      return FF.invFamilyKey(a).localeCompare(FF.invFamilyKey(b)) || (FF.itemTierFromId(a)-FF.itemTierFromId(b));
    });
    eq(sorted.join(','), 'digging_t0,digging_t2,forestry_t0,forestry_t1', 'family then tier ordering');
  });

  // ---- Inventory accordions: fine-grained groups replace the category filter chips ----
  suite('inventory: accordion groups (weapons by family, armour by material)', function(){
    ok(typeof FF.invGroupFor === 'function' && Array.isArray(FF.INV_GROUPS), 'accordion group helpers exported');
    // Weapons split by family.
    eq(FF.invGroupFor('stweapon_greatsword_t5_rare'), 'w_swords', 'greatsword -> Swords');
    eq(FF.invGroupFor('stweapon_sledge_t3_normal'),   'w_hammers','sledge -> Hammers');
    eq(FF.invGroupFor('stweapon_hatchet_t3_normal'),  'w_axes',   'hatchet -> Axes');
    eq(FF.invGroupFor('stweapon_bowLong_t3_normal'),  'w_bows',   'long bow -> Bows');
    eq(FF.invGroupFor('stweapon_wandFire_t3_normal'), 'w_wands',  'fire wand -> Wands');
    eq(FF.invGroupFor('stweapon_claw_t3_normal'),     'w_claws',  'claws -> Claws');
    // Armour split by material.
    eq(FF.invGroupFor('bodyarmor_plate_chest_t5_rare'),     'a_plate',     'plate -> Plate Armor');
    eq(FF.invGroupFor('bodyarmor_tailoring_chest_t5_normal'),'a_tailoring','cloth -> Cloth Armor');
    eq(FF.invGroupFor('bodyarmor_leather_boots_t5_normal'), 'a_leather',   'leather -> Leather Armor');
    // Jewelry / offhands / tools each their own group; raw materials fall to the broad buckets.
    // Shields split by size and wards by element, matching their equip pickers.
    eq(FF.invGroupFor('stshield_shieldMedium_t5_normal'), 'sh_shieldMedium', 'medium shield -> Medium Shields');
    eq(FF.invGroupFor('stshield_shieldSmall_t0_normal'),  'sh_shieldSmall',  'small shield -> Small Shields');
    eq(FF.invGroupFor('stward_wardFire_t5_rare'),         'wd_wardFire',     'fire ward -> Fire Wards');
    // Unrecognised subtypes keep their catch-all rather than vanishing from the inventory entirely.
    eq(FF.invGroupFor('stshield_medium_t5_normal'), 'shields', 'an unknown shield typeId falls back to Other Shields');
    eq(FF.invGroupFor('stward_nosuch_t5_normal'),   'wards',   'an unknown ward typeId falls back to Other Wards');
    FF.STACKABLE_SHIELD_TYPES.forEach(function(t){
      ok(FF.INV_GROUPS.some(function(g){ return g.id === 'sh_' + t.id; }), 'a container exists for shield size ' + t.id);
      eq(FF.invGroupFor('stshield_' + t.id + '_t3_normal'), 'sh_' + t.id, t.id + ' routes to its own container');
    });
    FF.WARD_TYPES.forEach(function(t){
      ok(FF.INV_GROUPS.some(function(g){ return g.id === 'wd_' + t.id; }), 'a container exists for ward element ' + t.id);
      eq(FF.invGroupFor('stward_' + t.id + '_t3_normal'), 'wd_' + t.id, t.id + ' routes to its own container');
    });
    // Rings bucket PER TYPE now (ticket, Valuren) -- the single 'rings' bucket is gone.
    eq(FF.invGroupFor('ring_fire_t5_rare'),      'r_fire',      'fire ring -> Fire Rings');
    eq(FF.invGroupFor('ring_blunt_t0_normal'),   'r_blunt',     'blunt ring -> Blunt Rings');
    eq(FF.invGroupFor('ring_communion_t20_fantastic'), 'r_communion', 'communion ring -> Communion Rings');
    eq(FF.invGroupFor('legring_plunder_rare'),   'r_signet',    'legendary signet -> Signets');
    eq(FF.invGroupFor('ring_notatype_t5_rare'),  'r_signet',    'an unknown ring type falls back to Signets, never dropped');
    ok(!FF.INV_GROUPS.some(function(g){ return g.id === 'rings'; }), 'the single Rings bucket is gone');
    // One container per ring type, each with its own label + icon, and all reachable from invGroupFor.
    FF.RING_TYPES.forEach(function(rt){
      var g = FF.INV_GROUPS.filter(function(x){ return x.id === 'r_' + rt.id; })[0];
      ok(!!g, 'a container exists for ring type ' + rt.id);
      ok(g && /Rings$/.test(g.label) && g.label.indexOf('Ring of ') === -1, 'ring group label reads "X Rings": ' + (g && g.label));
      eq(FF.invGroupFor('ring_' + rt.id + '_t3_normal'), 'r_' + rt.id, rt.id + ' ring routes to its own container');
    });
    eq(FF.invGroupFor('amulet_t5_rare'),      'amulets', 'amulet -> Amulets');
    eq(FF.invGroupFor('relic_t5_rare'),       'relics',  'relic -> Relics');
    eq(FF.invGroupFor('tool_mining_t5_normal'),'tools',  'tool -> Tools');
    eq(FF.invGroupFor('digging_t5'),          'gathering','raw material -> Gathering');
    eq(FF.invGroupFor('metallurgy_t5'),       'crafting', 'refined bar -> Crafting');
    // Unique items get their own per-type container, keyed off the unique's kind (not the old single bucket).
    eq(FF.uniqueInvGroupId({kind:'weapon'}),    'u_weapon',    'unique weapon -> Unique Weapons');
    eq(FF.uniqueInvGroupId({kind:'bodyarmor'}), 'u_bodyarmor', 'unique armour -> Unique Armor');
    eq(FF.uniqueInvGroupId({kind:'offhand'}),   'u_offhand',   'unique shield -> Unique Shields');
    eq(FF.uniqueInvGroupId({kind:'ring'}),      'u_ring',      'unique ring -> Unique Rings');
    eq(FF.uniqueInvGroupId({kind:'amulet'}),    'u_amulet',    'unique amulet -> Unique Amulets');
    eq(FF.uniqueInvGroupId({kind:'belt'}),      'u_belt',      'unique belt -> Unique Belts');
    eq(FF.uniqueInvGroupId({kind:'relic'}),     'u_relic',     'unique relic -> Unique Relics');
    eq(FF.uniqueInvGroupId({kind:'??'}),        'u_weapon',    'an unmapped kind falls back to Unique Weapons');
    ok(FF.INV_GROUPS.filter(function(g){ return g.unique; }).length === 7 && !FF.INV_GROUPS.filter(function(g){ return g.id==='unique'; }).length, 'seven unique containers replace the single Unique bucket');
    // Render: the panel emits collapsible accordions + keeps the search box; the old chips are gone.
    var S = FF._state, savedInv = S.inventory, savedCat = FF.currentCategoryId();
    try {
      var wid = Object.keys(FF.ALL_SELLABLE).filter(function(id){ return id.indexOf('stweapon_greatsword_')===0; })[0];
      var aid = Object.keys(FF.ALL_SELLABLE).filter(function(id){ return id.indexOf('bodyarmor_plate_chest_')===0; })[0];
      ok(wid && aid, 'sample weapon + armour ids resolve in ALL_SELLABLE');
      var inv = { digging_t5:20 }; inv[wid] = 1; inv[aid] = 1;
      S.inventory = inv;
      FF.navPickCat('inventory');
      var h = document.getElementById('inventoryPanel').innerHTML;
      ok(/inv-acc-bar/.test(h) && /data-action="invAccToggle"/.test(h), 'items render inside collapsible accordions');
      ok(/Swords/.test(h) && /Plate Armor/.test(h) && /Gathering/.test(h), 'weapons/armour/materials each get their own group');
      ok(/id="invSearchInput"/.test(h), 'the search box is preserved');
      ok(/data-action="invExpandAll"/.test(h) && /data-action="invCollapseAll"/.test(h), 'expand/collapse-all controls exist');
      ok(!/data-action="invFilterCat"/.test(h), 'the old category filter chips are gone');
    } finally { S.inventory = savedInv; if(savedCat) FF.navPickCat(savedCat); }
  });

  // ---- Offhand picker: shields grouped by size, wards grouped by element ----
