  // ---- Guild bank: legendary / set uniques keep their real name + effect through the vault ----
  suite('guild bank: legendary uniques survive the vault round-trip', function(){
    var def = FF.D1_LEG_GEAR_DEFS.filter(function(d){ return d.slot==='mainhand'; })[0];
    ok(def, 'a D1 mainhand legendary exists to test with');
    var top = FF.legGearBaseTopTier(def.base);
    var base = 'stweapon_'+def.base+'_t'+top+'_rare';
    var legName = FF.LEGENDARY_GEAR_ITEMS[FF.legGearItemId(def.key,'rare')].name;
    var u = { base:base, kind:'weapon', tier:top, rarity:'rare', enhance:0, enchants:[{mod:'critDamage',roll:20}], leg:def.key };
    // The bug: without carrying leg, the item names by its plain base, not its legendary.
    ok(FF.uniqueBaseName(u) === legName && legName !== (FF.ALL_SELLABLE[base]||{}).name, 'a legendary unique names by its legendary, not its base');
    var blob = FF.bankUniqueBlob(u);
    eq(blob.leg, def.key, 'the deposit blob carries the legendary key');
    eq(blob.enchants.length, 1, '...and its enchants');
    var revived = FF.bankUniqueRevive({ base:blob.base, kind:blob.kind, tier:blob.tier, rarity:blob.rarity, enhance:blob.enhance, enchants:blob.enchants, leg:blob.leg });
    eq(revived.leg, def.key, 'a withdrawn legendary re-mints with its leg (effect restored, not just the name)');
    eq(FF.uniqueBaseName(revived), legName, '...and reads back as its legendary name');
    eq(revived.enchants[0].roll, 20, 'enchants survive the round-trip');
    // A plain unique carries a null leg -> unaffected.
    eq(FF.bankUniqueBlob({ base:base, kind:'weapon', tier:top, rarity:'rare', enhance:0, enchants:[] }).leg, null, 'a plain unique carries a null leg');
    // Armor-set piece: set/setLayer round-trip too.
    var sblob = FF.bankUniqueBlob({ base:'bodyarmor_plate_chest_t9_rare', kind:'bodyarmor', tier:9, rarity:'rare', enhance:0, enchants:[], set:'knight', setLayer:'d2' });
    ok(sblob.set==='knight' && sblob.setLayer==='d2', 'a set piece carries its set key + layer');
    var sr = FF.bankUniqueRevive({ base:sblob.base, kind:sblob.kind, tier:sblob.tier, rarity:sblob.rarity, enhance:0, enchants:[], set:sblob.set, setLayer:sblob.setLayer });
    ok(sr.set==='knight' && sr.setLayer==='d2', 'a withdrawn set piece keeps its set + layer');
  });

  suite('equip picker: best-first, grouped, filterable candidate list', function(){
    ok(typeof FF.sortEquipCandidates==='function' && typeof FF.renderEquipCandidatePicker==='function', 'equip picker helpers exported');
    // Sort: equipped pinned to the top, usable by score desc, locked sunk to the bottom.
    var srt = FF.sortEquipCandidates([
      {name:'weak',  score:5,   canEquip:true,  equipped:false},
      {name:'strong',score:9,   canEquip:true,  equipped:false},
      {name:'locked',score:100, canEquip:false, equipped:false},
      {name:'worn',  score:1,   canEquip:true,  equipped:true}
    ]);
    eq(srt[0].name,'worn',   'equipped pinned first');
    eq(srt[1].name,'strong', 'then the strongest usable');
    eq(srt[2].name,'weak',   'then the next usable');
    eq(srt[3].name,'locked', 'locked (even if higher score) sinks to the bottom');
    // Render: Equip best points at the strongest USABLE piece (never the locked one), hide-locked toggle
    // appears when a locked candidate exists, and the toggle actually filters the locked row out.
    var groups = [{ key:'g', title:'G', candidates:[
      { icon:'', name:'Weak',   qty:1, score:2,  statHtml:'', deltaHtml:'', equipped:false, canEquip:true,  lockHtml:'', action:'equipX', data:'data-item="weak"' },
      { icon:'', name:'Strong', qty:1, score:9,  statHtml:'', deltaHtml:'', equipped:false, canEquip:true,  lockHtml:'', action:'equipX', data:'data-item="strong"' },
      { icon:'', name:'Locked', qty:1, score:99, statHtml:'', deltaHtml:'', equipped:false, canEquip:false, lockHtml:'', action:'equipX', data:'data-item="locked"' }
    ]}];
    var savedHL = FF.getEquipHideLocked();
    try {
      FF.setEquipHideLocked(false);
      var h = FF.renderEquipCandidatePicker(groups, {flat:true, bestLabel:'Equip best'});
      var toolbar = (h.match(/<div class="equip-picker-tools">[\s\S]*?<\/div>/) || [''])[0];
      ok(/data-item="strong"/.test(toolbar) && !/data-item="locked"/.test(toolbar), 'Equip best targets the strongest usable piece, not the locked higher-score one');
      ok(/data-action="equipHideLockedToggle"/.test(h), 'the hide-locked toggle shows when a locked candidate exists');
      ok(h.indexOf('data-item="strong"') < h.indexOf('data-item="weak"'), 'rows render strongest-first');
      FF.setEquipHideLocked(true);
      var h2 = FF.renderEquipCandidatePicker(groups, {flat:true});
      ok(!/data-item="locked"/.test(h2), 'hide-locked filters the locked candidate out of the list');
      ok(/data-item="strong"/.test(h2), '...but keeps the usable ones');
    } finally { FF.setEquipHideLocked(savedHL); }

    // Regression (reported): a rare and a normal cloak of the SAME tier have identical defense -- cloth
    // rarity pumps a familiar bonus, not armor -- so their `score` ties. "Equip best" (which skips the worn
    // piece) used to keep flipping between them. Rarity, then tier, breaks the tie.
    ok(typeof FF.candBetter === 'function', 'candBetter exported');
    ok(FF.candBetter({score:12,rarityRank:1,tier:3},{score:12,rarityRank:0,tier:3}), 'same defense: higher rarity wins');
    ok(!FF.candBetter({score:12,rarityRank:0,tier:3},{score:12,rarityRank:1,tier:3}), 'lower rarity is NOT better than the equal-defense higher rarity');
    ok(FF.candBetter({score:20,rarityRank:0,tier:5},{score:12,rarityRank:1,tier:3}), 'a strictly higher defense still wins regardless of rarity');
    ok(FF.candBetter({score:12,rarityRank:1,tier:4},{score:12,rarityRank:1,tier:3}), 'same defense + rarity: higher tier breaks the tie');
    var cloak = function(worn){ return [{ key:'back', title:'Back', candidates:[
      { icon:'', name:'Rare Cloak',   qty:1, score:12, rarityRank:1, tier:3, statHtml:'', deltaHtml:'', equipped:(worn==='rare'),   canEquip:true, lockHtml:'', action:'equipBodyArmor', data:'data-item="cloak_rare"' },
      { icon:'', name:'Normal Cloak', qty:1, score:12, rarityRank:0, tier:3, statHtml:'', deltaHtml:'', equipped:(worn==='normal'), canEquip:true, lockHtml:'', action:'equipBodyArmor', data:'data-item="cloak_normal"' }
    ]}]; };
    // Rare worn: the normal is equal defense but lower rarity -> not strictly better -> no Equip best at all
    // (so no flip-flop / downgrade).
    ok(!/equip-picker-tools/.test(FF.renderEquipCandidatePicker(cloak('rare'), {flat:true, bestLabel:'Equip best'})), 'rare worn: Equip best is not offered (the normal is not an upgrade)');
    // Normal worn: the rare IS strictly better -> Equip best offered, targeting the rare.
    var tbN = (FF.renderEquipCandidatePicker(cloak('normal'), {flat:true, bestLabel:'Equip best'}).match(/<div class="equip-picker-tools">[\s\S]*?<\/div>/) || [''])[0];
    ok(/data-item="cloak_rare"/.test(tbN) && !/data-item="cloak_normal"/.test(tbN), 'normal worn: Equip best upgrades to the same-tier rare');

    // Body-armour picker is scoped to the tapped slot and groups owned pieces by material accordion.
    var S = FF._state, savedInv=S.inventory, savedBody=S.bodyArmor, savedXp=S.xp, savedUniq=S.uniqueItems;
    try {
      var chestId = Object.keys(FF.ALL_SELLABLE).filter(function(id){ return id.indexOf('bodyarmor_plate_chest_t0_')===0 && /_normal$/.test(id); })[0];
      var helmId  = Object.keys(FF.ALL_SELLABLE).filter(function(id){ return id.indexOf('bodyarmor_plate_helmet_t0_')===0 && /_normal$/.test(id); })[0];
      ok(chestId && helmId, 'sample plate chest + helmet ids resolve');
      S.xp = { chainmailarmor:1e9, platearmor:1e9, leatherarmor:1e9, clotharmor:1e9 };
      S.bodyArmor = {}; S.uniqueItems = {};
      var invA = {}; invA[chestId] = 1; invA[helmId] = 1; S.inventory = invA;
      var ch = FF.renderEquipBodyArmorSection('chest');
      ok(ch.indexOf(chestId) !== -1, 'the chest picker offers the owned chest piece');
      ok(ch.indexOf(helmId) === -1, 'the chest picker is scoped to the chest slot (no helmet pieces leak in)');
      ok(/inv-acc-bar/.test(ch) && /Plate/.test(ch), 'owned pieces are grouped into a Plate material accordion');
    } finally { S.inventory=savedInv; S.bodyArmor=savedBody; S.xp=savedXp; S.uniqueItems=savedUniq; }

    // Mainhand weapon picker nests a per-type sub-accordion when a family holds more than one owned type,
    // so a 100+ item melee list stops being one flat wall.
    var mSaved = { mh:S.equippedMainhand, mht:S.equippedMainhandTier, mhr:S.equippedMainhandRarity, inv:S.inventory, xp:S.xp, uniq:S.uniqueItems };
    try {
      S.xp = { rapier:1e9, greatsword:1e9, weaponsmithing:1e9 };
      var rap = 'stweapon_rapier_t4_normal', rap2 = 'stweapon_rapier_t2_normal', gs = 'stweapon_greatsword_t4_normal';
      ok(FF.STACKABLE_WEAPON_ITEMS[rap] && FF.STACKABLE_WEAPON_ITEMS[gs], 'sample rapier + greatsword ids resolve');
      // Equip a rapier so the Rapier nest opens by default; the Greatsword nest stays collapsed.
      S.equippedMainhand = 'rapier'; S.equippedMainhandTier = 5; S.equippedMainhandRarity = 'normal'; S.uniqueItems = {};
      var inv = {}; inv[rap]=1; inv[rap2]=1; inv[gs]=1; S.inventory = inv;
      var h = FF.renderMainhandEquipSection();
      ok(/Melee Weapons/.test(h), 'the Melee Weapons family accordion renders');
      ok(/inv-acc-sub/.test(h), 'multiple owned weapon types nest into per-type sub-accordions');
      ok(/>Rapier<\/span>/.test(h) && />Greatsword<\/span>/.test(h), 'each owned weapon type gets its own nested accordion title');
      ok(h.indexOf('data-item="'+rap2+'"')!==-1, 'the equipped type nest opens by default, showing its other items');
      ok(/data-key="[^"]*_greatsword" data-open="0"/.test(h), 'a non-equipped type nest (Greatsword) is collapsed by default');
      // A single owned weapon type skips the redundant second nest.
      var inv2 = {}; inv2[rap]=1; inv2[rap2]=1; S.inventory = inv2;
      var h1 = FF.renderMainhandEquipSection();
      ok(/Melee Weapons/.test(h1) && !/inv-acc-sub/.test(h1), 'a single owned weapon type skips the redundant sub-nest');
    } finally { S.equippedMainhand=mSaved.mh; S.equippedMainhandTier=mSaved.mht; S.equippedMainhandRarity=mSaved.mhr; S.inventory=mSaved.inv; S.xp=mSaved.xp; S.uniqueItems=mSaved.uniq; }
  });

  // ---- Marketplace pricing helpers (must match the server RPC's tax math) --------------
  suite('marketplace pricing', function(){
    eq(FF.MARKET_TAX, 0.05, 'market tax is 5%');
    eq(FF.marketTax(1000), 50, '5% of 1000 = 50');
    eq(FF.marketTax(999), 49, 'tax floors (999 -> 49, not 49.95)');
    eq(FF.marketBuyCost(7, 9), 63, 'buy cost = price*qty');
    eq(FF.marketSellNet(100, 10), 950, 'sell net = gross - 5% tax (1000 -> 950)');
    eq(FF.marketSellNet(1, 1), 1, 'tiny sale: floor(0.05)=0 tax, net = 1');
    ok(FF.marketSellNet(50, 3) === 50*3 - FF.marketTax(50*3), 'sell net stays consistent with marketTax');
  });

  // ---- Marketplace category filter: quick-nav buckets each map every tradeable item to one category ----
  suite('marketplace categories', function(){
    eq(FF.MARKET_CATEGORIES[0].id, 'all', 'the first category is "All"');
    eq(FF.marketItemCategory('stweapon_scimitar_t0_normal'), 'weapons', 'a stackable weapon -> Weapons');
    eq(FF.marketItemCategory('tool_mining_t0_normal'), 'tools', 'a gather tool -> Tools');
    eq(FF.marketItemCategory('relic_t0_normal'), 'relics', 'a relic -> Relics');
    eq(FF.marketItemCategory('ring_slash_t0_normal'), 'accessories', 'a ring -> Accessories');
    eq(FF.marketItemCategory('bodyarmor_leather_chest_t0_normal'), 'armor', 'a body-armor piece -> Armor');
    eq(FF.marketItemCategory('workshop_mining_t0'), 'other', 'a workshop building -> Other');
    eq(FF.marketItemCategory('powder_t0'), 'materials', 'a gathered material -> Materials');
    eq(FF.marketItemCategory('metallurgy_t0'), 'refined', 'a refined bar (metallurgy) -> Refined');
    eq(FF.marketItemCategory('tanning_t0'), 'refined', 'refined leather (tanning) -> Refined');
    eq(FF.marketItemCategory('twine_t0'), 'refined', 'weaving twine (alias prefix) -> Refined');
    eq(FF.marketItemCategory('mining_t0'), 'materials', 'a raw gathered ore -> Materials');
    eq(FF.marketItemCategory('cooking_t0'), 'consumables', 'cooked food -> Consumables');
    eq(FF.marketItemCategory('mixology_t0'), 'consumables', 'a tea (mixology) -> Consumables');
    eq(FF.marketItemCategory('tome_t0'), 'consumables', 'a tome/book (bookbinding) -> Consumables');
    eq(FF.marketItemCategory('scroll_t0'), 'consumables', 'a scroll (inscription) -> Consumables');
    eq(FF.marketItemCategory('draught_t0'), 'consumables', 'an Apothecary draught -> Consumables');
    // Tier chip: 1-based, tier-less items show nothing.
    ok(/T6/.test(FF.marketItemTierHtml('metallurgy_t5')), 'the tier chip is 1-based (t5 -> T6)');
    eq(FF.marketItemTierHtml('meat'), '', 'a tier-less item shows no tier chip');
    // Subcategory = producing skill (alias prefixes resolve to their skill).
    eq(FF.marketItemSubcategory('herbalism_t0'), 'herbalism', 'raw material subcategory is its gather skill');
    eq(FF.marketItemSubcategory('twine_t0'), 'weaving', 'an alias prefix (twine) resolves to its skill (weaving)');
    eq(FF.marketItemSubcategory('metallurgy_t3'), 'metallurgy', 'a refined subcategory is its refining skill');
    ok(FF.marketSubLabel('forestry').toLowerCase().indexOf('forest') !== -1, 'subcategory labels are human-readable skill names');
    // Every tradeable id resolves to one of the defined buckets (no item is uncategorized).
    var cats = {}; FF.MARKET_CATEGORIES.forEach(function(c){ cats[c.id] = true; });
    ok(Object.keys(FF.ALL_SELLABLE).slice(0, 400).every(function(id){ return id==='gold' || cats[FF.marketItemCategory(id)]; }), 'every sellable item maps to a known category');
  });

  // ---- Item catalog (server allowlist) -- buildItemCatalog covers the whole inventory-key universe ----
  // This map is dumped to the server (item_catalog) and GATES the item ledger + marketplace. If it ever
  // misses a legit inventory key, that item becomes un-ledgerable/un-sellable, so completeness is load-
  // bearing: every ALL_SELLABLE key must be tradeable(1), every Legendary key must be present (ledger-only,
  // 0), and nothing made-up may appear.
  suite('item catalog: allowlist covers every inventory key', function(){
    var cat = FF.buildItemCatalog();
    var keys = Object.keys(cat);
    ok(keys.length > 1000, 'catalog is populated (' + keys.length + ' keys)');
    // Charset: every catalog key is a legal item key (the server enforces the same regex).
    var re = /^[A-Za-z0-9_]{1,64}$/;
    ok(keys.every(function(k){ return re.test(k); }), 'every catalog key matches the item-key charset');
    ok(keys.every(function(k){ return cat[k] === 1 || cat[k] === 0; }), 'every entry is a 1/0 tradeable flag');

    // Every market-tradeable item (ALL_SELLABLE, minus gold, charset-valid) is present AND tradeable.
    var sellable = Object.keys(FF.ALL_SELLABLE).filter(function(k){ return k !== 'gold' && re.test(k); });
    var missingSellable = sellable.filter(function(k){ return cat[k] !== 1; });
    eq(missingSellable.length, 0, 'all ALL_SELLABLE keys are catalogued as tradeable (missing: ' + missingSellable.slice(0,5).join(',') + ')');

    // Every Legendary key (in inventory but NOT tradeable) is present so item_sync never drops it.
    var legMaps = [FF.LEGENDARY_GEAR_ITEMS, FF.LEGENDARY_GEAR_ITEMS_D2, FF.LEGENDARY_GEAR_ITEMS_D3, FF.LEGENDARY_GEAR_ITEMS_D4,
                   FF.LEGENDARY_RING_ITEMS, FF.LEGENDARY_CLOAK_ITEMS, FF.LEGENDARY_AMULET_ITEMS];
    var legKeys = [];
    legMaps.forEach(function(m){ if(m) Object.keys(m).forEach(function(k){ if(re.test(k)) legKeys.push(k); }); });
    ok(legKeys.length > 0, 'there are Legendary item keys to catalog');
    var missingLeg = legKeys.filter(function(k){ return !(k in cat); });
    eq(missingLeg.length, 0, 'every Legendary key is catalogued (missing: ' + missingLeg.slice(0,5).join(',') + ')');
    // A Legendary that isn't ALL_SELLABLE must be ledger-only (tradeable 0), so the market rejects it.
    var pureLeg = legKeys.filter(function(k){ return sellable.indexOf(k) === -1; });
    ok(pureLeg.length === 0 || pureLeg.every(function(k){ return cat[k] === 0; }), 'non-sellable Legendaries are catalogued as ledger-only (untradeable)');

    // A made-up key is never in the catalog -> the server rejects orders/ledger entries for it.
    ok(!('fake_item_does_not_exist' in cat), 'a made-up item key is absent from the catalog');
  });

  // ---- Item catalog: the MINTED-UNIQUE base keys (the half the suite above never covered) --------------
  // The suite above proves every INVENTORY key is catalogued. A unique's `base` is a second, disjoint
  // universe: a Masterwork armour set piece and a legendary weapon/shield/ward are MINTED straight into
  // state.uniqueItems and never sit in inventory at all. save_game's forged-unique audit reads item_catalog
  // as the allowlist for that base key, so an uncatalogued base reads as an INVENTED item.
  //
  // This shipped broken and was firing: the set-tier armour (t21 D1 / t22 D2 / t23 D3 / t24 D4) is generated
  // after `Object.assign(ALL_SELLABLE, BODY_ARMOR_ITEMS)`, so buildItemCatalog missed the whole family at
  // every rarity and every honest owner of a set was reported hourly as base_not_in_catalog. Enforcement
  // being off is the only reason it cost noise rather than somebody's gear.
  //
  // Mint through the REAL path (mintSetPiece / the craftMastercraft base construction), never a hand-built
  // string: the string is what the bug already agreed with. The keys must also stay UNTRADEABLE, or a minted
  // unique becomes listable on the market.
  suite('item catalog: every minted unique base is on the allowlist', function(){
    var cat = FF.buildItemCatalog(), S = FF._state;
    var RARS = ['normal','rare','supreme','fantastic'];
    var bases = [], missing = [], tradeableMinted = [];
    var keptUniques = S.uniqueItems;
    S.uniqueItems = {};

    // 1. Armour set pieces: every layer x class x slot x rarity the game can forge.
    var defsByLayer = { d1: FF.D1_SET_DEFS, d2: FF.D2_SET_DEFS, d3: FF.D3_SET_DEFS, d4: FF.D4_SET_DEFS };
    ['d1','d2','d3','d4'].forEach(function(L){
      var defs = defsByLayer[L];
      ok(!!defs && Object.keys(defs).length > 0, 'set defs are on the seam for ' + L);
      Object.keys(defs || {}).forEach(function(cls){
        Object.keys(defs[cls].pieces).forEach(function(slot){
          RARS.forEach(function(r){
            var uid = FF.mintSetPiece(cls, slot, r, L);
            ok(!!uid, 'mintSetPiece forged ' + [L,cls,slot,r].join('/'));
            if(!uid) return;
            var base = S.uniqueItems[uid].base;
            bases.push(base);
            if(!(base in cat)) missing.push(base);
            if(cat[base] === 1) tradeableMinted.push(base);
            delete S.uniqueItems[uid];
          });
        });
      });
    });
    var setPieceCount = bases.length;
    ok(setPieceCount > 1000, 'minted every set piece through the real path (' + setPieceCount + ' forged)');

    // 2. Legendary weapon/shield/ward bases, built exactly as craftMastercraft builds them.
    var legMaps = { d1: FF.D1_LEG_GEAR_MAP, d2: FF.D2_LEG_GEAR_MAP, d3: FF.D3_LEG_GEAR_MAP, d4: FF.D4_LEG_GEAR_MAP };
    ['d1','d2','d3','d4'].forEach(function(L){
      var map = legMaps[L];
      ok(!!map && Object.keys(map).length > 0, 'legendary gear map is on the seam for ' + L);
      Object.keys(map || {}).forEach(function(k){
        var g = map[k], top = FF.legGearBaseTopTier(g.base);
        var isShield = (FF.STACKABLE_SHIELD_TYPES || []).some(function(o){ return o.id === g.base; });
        var prefix = FF.WARD_TYPE_MAP[g.base] ? 'stward_' : (isShield ? 'stshield_' : 'stweapon_');
        RARS.forEach(function(r){
          var base = prefix + g.base + '_t' + top + '_' + r;
          bases.push(base);
          if(!(base in cat)) missing.push(base);
        });
      });
    });
    ok(bases.length - setPieceCount > 100, 'built every legendary gear base (' + (bases.length - setPieceCount) + ' keys)');

    S.uniqueItems = keptUniques;

    eq(missing.length, 0, 'every minted unique base is catalogued (missing ' + missing.length +
       ', e.g. ' + missing.slice(0,3).join(', ') + ')');
    eq(tradeableMinted.length, 0, 'no minted set-piece base is market-tradeable (' + tradeableMinted.slice(0,3).join(', ') + ')');
    // The specific key the live digest reported, named so a regression is unmistakable.
    ok('bodyarmor_chain_helmet_t21_rare' in cat, 'the D1 chain helmet from the false-positive signal is catalogued');
    eq(cat['bodyarmor_chain_helmet_t21_rare'], 0, 'and it is ledger-only, not tradeable');
  });

  // ---- Combat damage-type advantage triangle --------------------------------------------
  suite('weaponAdvantage', function(){
    FF.DAMAGE_TYPES.forEach(function(t){ eq(FF.weaponAdvantageMultiplier(t, t), 1.0, 'same type is neutral: ' + t); });
    FF.DAMAGE_TYPES.forEach(function(w){
      var mults = FF.DAMAGE_TYPES.map(function(d){ return FF.weaponAdvantageMultiplier(w, d); }).sort();
      eq(mults[0], 0.8, w + ' has one weak matchup');
      eq(mults[1], 1.0, w + ' is neutral vs itself');
      eq(mults[2], 1.25, w + ' has one strong matchup');
    });
    eq(FF.weightedAdvantage({ slashing: 1 }, { slashing: 1 }), 1.0, 'pure self matchup = 1.0');
    var s = 'slashing', p = 'piercing';
    var expected = 0.5 * FF.weaponAdvantageMultiplier(s, s) + 0.5 * FF.weaponAdvantageMultiplier(p, s);
    near(FF.weightedAdvantage({ slashing: 0.5, piercing: 0.5 }, { slashing: 1 }), expected, 'weightedAdvantage weights by attacker mix');
  });

  // ---- Accuracy vs Dodge ----------------------------------------------------------------
  suite('accuracy vs dodge', function(){
    // Enemy dodge scales monotonically with tier, low at t0 and high at the top tier.
    var wildlife = FF.MONSTERS.filter(function(m){ return m.category==='wildlife'; })
      .sort(function(a,b){ return a.tierIndex - b.tierIndex; });
    ok(wildlife.length >= 21, 'wildlife spans all tiers');
    var t0 = FF.monsterDodge(wildlife[0]);
    var tTop = FF.monsterDodge(wildlife[wildlife.length-1]);
    ok(t0 >= 0 && t0 < 30, 't0 dodge is low (' + t0 + ')');
    ok(tTop > 400, 'top-tier dodge is high (' + tTop + ')');
    for(var i=1;i<wildlife.length;i++){
      ok(FF.monsterDodge(wildlife[i]) >= FF.monsterDodge(wildlife[i-1]), 'dodge is non-decreasing by tier at ' + i);
    }

    // hitChanceVs: accuracy >= dodge always hits; deficits erode toward the floor; clamped to [floor,1].
    eq(FF.hitChanceVs(700, 700), 1, 'accuracy meeting dodge => guaranteed hit');
    eq(FF.hitChanceVs(1000, 700), 1, 'accuracy above dodge => guaranteed hit');
    ok(FF.hitChanceVs(0, 700) >= 0.15 - 1e-9, 'huge deficit never drops below the 15% floor');
    ok(FF.hitChanceVs(0, 700) <= 0.16, 'huge deficit sits at the floor');
    near(FF.hitChanceVs(400, 500), 1 - 100/500, 'partial deficit erodes linearly');
    ok(FF.hitChanceVs(400, 500) > FF.hitChanceVs(300, 500), 'more accuracy => higher hit chance vs same dodge');

    // The accuracy physiques are a fixed, Claude-chosen combat-reflex set (not player-selected).
    eq(FF.ACCURACY_PHYSIQUES.length, FF.ACCURACY_PHYS_SLOTS, 'exactly '+FF.ACCURACY_PHYS_SLOTS+' fixed accuracy physiques');
    FF.ACCURACY_PHYSIQUES.forEach(function(id){ ok(FF.PHYSIQUE_SKILL_MAP[id], id+' is a real physique'); });
    // accuracyPhysiques() always returns the fixed set and ignores any state override.
    eq(FF.accuracyPhysiques().join(','), FF.ACCURACY_PHYSIQUES.join(','), 'accuracyPhysiques returns the fixed set');
    eq(FF.accuracyPhysiques({ accuracyPhysiques:['a','b','c'] }).join(','), FF.ACCURACY_PHYSIQUES.join(','), 'a legacy state override is ignored');

    // playerAccuracy is driven by the fixed physiques + weapon proficiency (heavier on physiques).
    var base = { physique:{}, xp:{}, equippedMainhand:null };
    FF.ACCURACY_PHYSIQUES.forEach(function(id){ base.physique[id] = 0; });
    var accWithout = FF.playerAccuracy(base);
    base.physique[FF.ACCURACY_PHYSIQUES[0]] = 100*100;   // getLevel(xp)=~101; large so the weighting is visible
    var accWith = FF.playerAccuracy(base);
    ok(accWith > accWithout, 'leveling a fixed accuracy physique raises accuracy');
  });

  // ---- Elemental affinities (magic damage triangle + light/dark rivalry) ----------------
  suite('elements', function(){
    // Triangle: water > fire > earth > water, each a +20% beat; everything else neutral.
    eq(FF.elementAdvantage('water','fire'), FF.ELEMENT_ADVANTAGE_MULT, 'water beats fire');
    eq(FF.elementAdvantage('fire','earth'), FF.ELEMENT_ADVANTAGE_MULT, 'fire beats earth');
    eq(FF.elementAdvantage('earth','water'), FF.ELEMENT_ADVANTAGE_MULT, 'earth beats water');
    eq(FF.elementAdvantage('fire','water'), 1, 'fire is neutral into water (reverse of a beat)');
    eq(FF.elementAdvantage('water','earth'), 1, 'water neutral into earth');
    eq(FF.elementAdvantage('fire','fire'), 1, 'same element is neutral');
    // Light/dark rival each other but are neutral to the triangle.
    eq(FF.elementAdvantage('light','dark'), FF.ELEMENT_ADVANTAGE_MULT, 'light beats dark');
    eq(FF.elementAdvantage('dark','light'), FF.ELEMENT_ADVANTAGE_MULT, 'dark beats light');
    eq(FF.elementAdvantage('light','fire'), 1, 'light neutral to fire');
    eq(FF.elementAdvantage('fire','light'), 1, 'fire neutral to light');
    eq(FF.elementAdvantage('earth','dark'), 1, 'earth neutral to dark');
    eq(FF.elementAdvantage(null,'fire'), 1, 'no attacker element => neutral');

    // ELEMENT_WEAKNESS is the reverse of ELEMENT_BEATS (the element that beats each).
    Object.keys(FF.ELEMENT_BEATS).forEach(function(atk){
      var def = FF.ELEMENT_BEATS[atk];
      eq(FF.ELEMENT_WEAKNESS[def], atk, def + "'s weakness is " + atk);
    });

    // Base category identities.
    eq(FF.monsterElement('wildlife', 5), 'earth', 'wildlife is earth');
    eq(FF.monsterElement('demonspawn', 5), 'fire', 'demonspawn is fire');
    eq(FF.monsterElement('kinsworn', 5), 'water', 'kinsworn is water');
    ok(['fire','water','earth'].indexOf(FF.monsterElement('elemental', 4)) !== -1, 'elementals are one of the triangle');
    // Wildlife (earth) is weak to fire, exactly what the brief asked for.
    eq(FF.ELEMENT_WEAKNESS[FF.monsterElement('wildlife', 3)], 'fire', 'wildlife weak to fire');
    eq(FF.ELEMENT_WEAKNESS[FF.monsterElement('demonspawn', 3)], 'water', 'demonspawn weak to water');
    eq(FF.ELEMENT_WEAKNESS[FF.monsterElement('kinsworn', 3)], 'earth', 'kinsworn weak to earth');
    // Light/dark are sprinkled into the top tiers.
    var topEls = [16,17,18,19,20].map(function(t){ return FF.monsterElement('wildlife', t); });
    ok(topEls.indexOf('light') !== -1 && topEls.indexOf('dark') !== -1, 'light and dark appear in the top tiers');

    // Every monster carries a valid element with known metadata.
    ok(FF.MONSTERS.every(function(m){ return m.element && FF.ELEMENT_META[m.element]; }), 'every monster has a valid element');
  });

  // ---- Elemental loot: Elementals drop ONLY Glyphs (no raw-material burst) ----------------------
  suite('loot: elementals drop only glyphs', function(){
    // Loot preview stays in sync with the drop logic: chance = the glyph chance, label = 'Glyph'.
    var fake = { category:'elemental', tierIndex:5, element:'fire', name:'Fire Elemental' };
    eq(FF.getMonsterLootChance(fake), Math.round(FF.GLYPH_DROP_CHANCE*100), 'elemental loot chance = the Glyph drop chance');
    eq(FF.getMonsterLootLabel(fake), 'Glyph', 'elemental loot label is Glyph');
    // The category blurb no longer promises raw material.
    var cat = FF.MONSTER_CATEGORIES.filter(function(c){ return c.id==='elemental'; })[0];
    ok(cat && /Glyph/.test(cat.desc) && !/raw material/i.test(cat.desc), 'Elementals category describes Glyphs, not raw material');
    // Functional: run the loot many times across every element -- the only items an Elemental can ever
    // add are Glyphs (this fails loudly if a raw-material burst is ever re-introduced).
    var S = FF._state; var saveInv = S.inventory;
    var bad = {}, sawGlyph = false;
    try {
      ['fire','water','earth','light','dark'].forEach(function(el){
        var mon = { category:'elemental', tierIndex:8, element:el, name:'Test Elemental' };
        for(var n=0; n<60; n++){
          S.inventory = {};
          FF.applyMonsterCategoryLoot(mon);
          Object.keys(S.inventory).forEach(function(id){ if(id.indexOf('glyph_')===0) sawGlyph = true; else bad[id] = true; });
        }
      });
    } finally { S.inventory = saveInv; }
    ok(Object.keys(bad).length === 0, 'across 300 kills the only drops are Glyphs' + (Object.keys(bad).length ? ' (leaked: '+Object.keys(bad).join(', ')+')' : ''));
    ok(sawGlyph, 'Glyphs still drop (~50% of kills)');
  });

  // ---- Kill-loot floating text: what dropped, over the PLAYER, at 1.5x size ---------------------
  suite('loot: kill-loot floats report the drops', function(){
    var S = FF._state, saveInv = S.inventory;
    try {
      // applyMonsterCategoryLoot REPORTS its drops so defeatMonster can float them.
      S.inventory = {};
      var wild = { category:'wildlife', tierIndex:3, element:'earth', name:'Test Rabbit' };
      var drops = FF.applyMonsterCategoryLoot(wild);
      ok(Array.isArray(drops), 'applyMonsterCategoryLoot returns a drop list');
      eq(drops.length, 1, 'wildlife always yields exactly one drop entry (the corpse)');
      ok(drops[0].qty >= 1 && typeof drops[0].name === 'string' && drops[0].name.length > 0, 'the entry carries a quantity and an item name');
      // A category that rolls a chance can legitimately report NOTHING -- that is the "No Loot Dropped" case.
      S.inventory = {};
      var sawEmpty = false, sawFilled = false;
      for(var n = 0; n < 200 && !(sawEmpty && sawFilled); n++){
        S.inventory = {};
        var d = FF.applyMonsterCategoryLoot({ category:'kinsworn', tierIndex:5, element:'water', name:'Test Kinsman' });
        if(d.length === 0) sawEmpty = true; else sawFilled = true;
      }
      ok(sawEmpty, 'a 5% category reports an empty drop list on most kills (the No-Loot case)');
      ok(sawFilled, '...and a populated one when it does drop');
      // floatKillLoot must never throw on either shape (it no-ops without a live arena/float layer).
      FF.floatKillLoot([]);
      FF.floatKillLoot([{ qty:2, name:'Test Item' }]);
      ok(true, 'floatKillLoot handles both the empty and populated cases');
    } finally { S.inventory = saveInv; }
  });

  // ---- ticket-0117 follow-up: a recovered Blueprint gets the Mastercraft celebration ---------------
  suite('dungeons: Blueprint drops are celebrated, not listed', function(){
    var bpId = Object.keys(FF.BLUEPRINT_ITEMS)[0], bp = FF.BLUEPRINT_ITEMS[bpId];
    ok(!!bp, 'there is a Blueprint to test with');
    // A clear WITH a Blueprint reuses the Mastercraft result card (banner + the prize itself).
    var withBp = FF.dungeonResultPopupHtml('Nest of the Depths', [bp]);
    ok(/mc-result-card/.test(withBp), 'a Blueprint clear uses the Mastercraft celebration card');
    ok(/Blueprints? Recovered!/.test(withBp), '...with its own banner');
    ok(/bp-prize-name/.test(withBp), '...showing the prize large');
    ok(withBp.indexOf(bp.name) !== -1, '...naming the Blueprint');
    ok(/Resources &rarr; Blueprints/.test(withBp), '...and pointing at where to forge it');
    // A clear with NOTHING must stay modest -- the celebration has to mean something.
    var noBp = FF.dungeonResultPopupHtml('Nest of the Depths', []);
    ok(!/mc-result-card/.test(noBp), 'an empty clear does NOT use the celebration card');
    ok(!/Blueprint Recovered!/.test(noBp), '...and does not claim a Blueprint');
    ok(/Cleared!/.test(noBp), '...but still reports the clear');
  });

  // ---- ticket-0110: Auto Requeue re-descends a cleared dungeon (solo) -----------------------------
  suite('dungeons: Auto Requeue re-descends after a clear', function(){
    var S = FF._state;
    var snap = { xp:S.xp, hp:S.playerHp, act:S.activity, rq:S.dungeonAutoRequeue, cl:S.dungeonsCleared };
    try {
      var d1 = FF.DUNGEON_ORDER[0], def = FF.DUNGEON_DEFS[d1];
      // Meet the entry gate (Total Level; d1 has no previous layer to clear).
      S.xp = JSON.parse(JSON.stringify(S.xp));
      var floor = FF.xpFloorForLevel(60);
      Object.keys(S.xp).forEach(function(k){ S.xp[k] = Math.max(S.xp[k]||0, floor); });
      eq(FF.dungeonEntryBlock(def), null, 'the test fixture can enter the first dungeon');
      S.playerHp = FF.maxHp(S);

      // OFF: clearing must leave you out of combat, on the result screen.
      S.dungeonAutoRequeue = false;
      FF.dungeonBegin(d1);
      eq(S.activity.dungeon, d1, 'Begin Descent starts the run');
      FF.dungeonComplete();
      eq(S.activity.type, null, 'with Auto Requeue off, a clear ends the run');

      // ON: clearing rolls straight into a fresh descent of the same layer, from the first foe.
      S.dungeonAutoRequeue = true;
      FF.dungeonBegin(d1);
      FF.dungeonComplete();
      eq(S.activity.type, 'combat', 'with Auto Requeue on, a clear starts another run');
      eq(S.activity.dungeon, d1, '...of the same layer');
      eq(S.activity.dungeonIndex, 0, '...starting from the first foe');

      // A dead player must NEVER be re-descended (death goes through dungeonEndRun, but guard anyway).
      S.playerHp = 0;
      eq(FF.dungeonAutoRequeue(def), false, 'a dead player is never re-descended');
      S.playerHp = FF.maxHp(S);
      // A layer you cannot enter stops the loop and says why, instead of silently spinning.
      var locked = FF.DUNGEON_ORDER[FF.DUNGEON_ORDER.length - 1];
      var lockedDef = FF.DUNGEON_DEFS[locked];
      ok(!!FF.dungeonEntryBlock(lockedDef), 'the last layer is gated for this fixture');
      var toast = document.getElementById('gameToast'); if(toast && toast.parentNode) toast.parentNode.removeChild(toast);
      eq(FF.dungeonAutoRequeue(lockedDef), false, 'a gated layer is not re-entered');
      var t2 = document.getElementById('gameToast');
      ok(t2 && /Auto Requeue stopped/.test(t2.textContent), '...and the player is told why');
      if(t2 && t2.parentNode) t2.parentNode.removeChild(t2);
      // The toggle is off by default for existing saves.
      S.dungeonAutoRequeue = false;
      eq(FF.dungeonAutoRequeue(def), false, 'the toggle gates the whole behaviour');

      // ---- ticket-0117: tabbing off must not freeze a SOLO run (that made the toggle pointless) ----
      // A solo descent still locks player ACTIONS (no crafting mid-fight)...
      S.dungeonAutoRequeue = true;
      FF.dungeonBegin(d1);
      eq(FF.dungeonLocksActions(), true, 'a solo descent still locks other actions');
      // ...but it must NOT be treated as attended for the away fast-forward.
      eq(FF.dungeonPartyLocksAway(), false, 'a solo descent does NOT freeze the away catch-up (ticket-0117)');
      // An away window fast-forwards the fight AND chains the next descent.
      var idxBefore = S.activity.dungeonIndex;
      FF.applyOfflineProgress(30 * 60 * 1000);
      eq(S.activity.type, 'combat', 'the run is still going after an away window');
      eq(S.activity.dungeon, d1, '...in the same layer');
      ok(S.activity.dungeonIndex !== idxBefore || FF.dungeonBossCleared(d1), '...and it actually progressed while hidden');
    } finally {
      // dungeonRun is MODULE-scoped, so restoring `state` alone would leave an active run behind --
      // dungeonLocksActions() would then short-circuit every later suite's Tower/Guild-Boss entry.
      FF.dungeonEndRun('retreat');
      S.xp=snap.xp; S.playerHp=snap.hp; S.activity=snap.act; S.dungeonAutoRequeue=snap.rq; S.dungeonsCleared=snap.cl;
    }
  });

  // ---- ticket-0111: a saved loadout must follow an equipped piece through its upgrade --------------
  suite('loadouts: upgrading an equipped piece keeps it in saved kits', function(){
    var S = FF._state;
    var snap = { ba:S.bodyArmor, ui:S.uniqueItems, inv:S.inventory, lo:S.loadouts };
    try {
      var BASE = 'bodyarmor_tailoring_gauntlets_t' + (FF.TIER_COUNT - 2) + '_rare'; // one below top, a normal craft
      var TIER = FF.TIER_COUNT - 1; // slot tiers are 1-based against the base id's 0-based index

      // --- The reported case: no spare copy in the bag ---
      S.uniqueItems = {}; S.inventory = {};
      S.bodyArmor = { gauntlets:{ material:'tailoring', tier:TIER, rarity:'rare' } };
      FF.ensureLoadouts();
      FF.saveLoadoutPreset(0);
      eq(!!S.loadouts[0].gear.gauntlets.uid, false, 'the preset saved a plain stackable (no uid)');
      var uid = FF.convertEquippedToUnique('armor:gauntlets');
      ok(!!uid, 'enhancing the equipped piece mints a unique');
      eq(S.loadouts[0].gear.gauntlets.uid, uid, 'the saved preset now tracks that unique (ticket-0111)');
      // Swap away and back: the piece must come back, and it must be the UPGRADED one.
      FF.applyCombatLoadout({});
      var res = FF.applyCombatLoadout(S.loadouts[0].gear);
      eq(res.dropped, 0, 'nothing is dropped on the way back');
      eq(res.restored, 1, '...the slot is restored');
      eq(S.bodyArmor.gauntlets.uid, uid, '...and it is the upgraded unique, not a fresh stackable');

      // --- The guard: a spare stackable of the same base is still owned ---
      S.uniqueItems = {}; S.inventory = {}; S.inventory[BASE] = 1;
      S.bodyArmor = { gauntlets:{ material:'tailoring', tier:TIER, rarity:'rare' } };
      FF.saveLoadoutPreset(0);
      var uid2 = FF.convertEquippedToUnique('armor:gauntlets');
      ok(!!uid2, 'the spare-copy scenario still mints a unique');
      eq(!!S.loadouts[0].gear.gauntlets.uid, false, 'the preset is left alone while a spare stackable exists');
      FF.applyCombatLoadout({});
      var res2 = FF.applyCombatLoadout(S.loadouts[0].gear);
      eq(res2.restored, 1, 'the preset still resolves, using the spare');
      eq(!!S.bodyArmor.gauntlets.uid, false, '...and it did NOT hijack the upgraded copy');

      // --- Only the matching slot/item is rewritten ---
      S.uniqueItems = {}; S.inventory = {};
      S.bodyArmor = { gauntlets:{ material:'tailoring', tier:TIER, rarity:'rare' }, boots:{ material:'tailoring', tier:TIER, rarity:'rare' } };
      FF.saveLoadoutPreset(0);
      var uid3 = FF.convertEquippedToUnique('armor:gauntlets');
      eq(S.loadouts[0].gear.gauntlets.uid, uid3, 'the upgraded slot is re-pointed');
      eq(!!S.loadouts[0].gear.boots.uid, false, '...and an identical piece in ANOTHER slot is untouched');
      // A no-op for junk input.
      eq(FF.loadoutsFollowUpgrade('armor:gauntlets', null, BASE), 0, 'no uid -> no rewrite');
      eq(FF.loadoutsFollowUpgrade('nonsense:slot', 'u1', BASE), 0, 'an unknown slot key is a safe no-op');
    } finally { S.bodyArmor=snap.ba; S.uniqueItems=snap.ui; S.inventory=snap.inv; S.loadouts=snap.lo; }
  });

  // ---- ticket-0109 sweep: every refused gesture toasts, combat narration does not -----------------
  suite('ui: refused gestures surface a toast', function(){
    function toastEl(){ return document.getElementById('gameToast'); }
    function clearToast(){ var e = toastEl(); if(e && e.parentNode) e.parentNode.removeChild(e); }
    try {
      // blockedNotice is the shared "your gesture was refused" channel: log AND top-centre toast.
      clearToast();
      FF.blockedNotice('Test refusal message.');
      var el = toastEl();
      ok(!!el, 'blockedNotice raises a toast');
      ok(/Test refusal message\./.test(el.textContent), '...carrying the message');
      ok(/toast-error/.test(el.className), '...styled as an error');
      // The dungeon block -- the pattern this sweep was named for (7 call sites route through it).
      clearToast();
      FF.dungeonActionBlockedNotice();
      ok(toastEl() && /in a dungeon/.test(toastEl().textContent), 'the dungeon block toasts (was log-only)');
      // CRITICAL: combat narration also logs as 'danger'. It must NOT toast, or a fight would spam popups.
      // addLog isn't on the seam, so assert the separation structurally: the toast channel is a distinct
      // function, and plain logging cannot reach it (only blockedNotice/combatGearLockNotice pair them).
      clearToast();
      ok(typeof FF.showGameToast === 'function', 'the toast channel is its own function');
      ok(!toastEl(), 'nothing toasts until something explicitly asks it to');
      // The toast lives on <body>, so the re-render that follows a click cannot wipe it.
      clearToast();
      FF.blockedNotice('Survives a render.');
      var node = toastEl();
      ok(node && node.parentNode === document.body, 'the toast is parented to <body>, not #app');
    } finally { clearToast(); }
  });

  // ---- ticket-0109: blocked entry must show ON the UI, not only in the Chronicle ------------------
  suite('combat: blocked Tower / Guild Boss entry is visible', function(){
    var S = FF._state;
    var snap = { act:S.activity };
    var gs = FF._guildBossState(), gst = FF._guildState();
    var gsnap = { err:gs.error, guild:gst.guild };
    try {
      var EN = 'all'; // the All-Classes Tower entrance (no class requirement to trip first)
      // --- Tower: entering while in an ordinary fight ---
      S.activity = { type:'combat', playerSwungOnce:true, monsterId:FF.MONSTERS[0].id, monsterHp:100, tickAccum:0, monsterTickAccum:0, duelStartedAt:Date.now() };
      FF._setTowerPreview(EN);
      eq(FF._towerEntryError(), '', 'the preview opens with no error');
      FF.towerEnter(EN);
      ok(/Finish your current fight/.test(FF._towerEntryError()), 'a blocked Tower entry sets a visible notice');
      ok(!(S.activity && S.activity.tower), '...and does NOT start the climb');
      // The notice has to appear in the card the player is actually looking at, styled as an error.
      var card = FF.towerPreviewCardHtml(EN);
      ok(card.indexOf(FF._towerEntryError()) !== -1, 'the notice renders inside the Tower preview card');
      ok(/border-color:var\(--hp-bad\)/.test(card), '...styled as an error');
      // --- Tower: already climbing gets its own wording ---
      S.activity = { type:'combat', playerSwungOnce:true, tower:{ entrance:EN, floor:3 }, monsterId:FF.MONSTERS[0].id, monsterHp:100 };
      FF._setTowerPreview(EN); FF.towerEnter(EN);
      ok(/already climbing/.test(FF._towerEntryError()), 'already climbing reports a distinct message');
      // Reopening the preview starts clean again.
      FF._setTowerPreview(EN);
      eq(FF._towerEntryError(), '', 'reopening the preview clears the stale notice');
      // --- Guild Boss: the reported case ---
      gst.guild = { id:'g1', name:'Test Guild' };
      gs.error = '';
      S.activity = { type:'combat', playerSwungOnce:true, monsterId:FF.MONSTERS[0].id, monsterHp:100, tickAccum:0, monsterTickAccum:0, duelStartedAt:Date.now() };
      FF.guildBossEnter(0);
      ok(/Finish your current fight/.test(gs.error), 'a blocked Guild Boss entry sets the panel error (ticket-0109)');
      ok(!(S.activity && S.activity.guildBoss), '...and does NOT pull the boss');
      // Already on a boss reads differently.
      gs.error = '';
      S.activity = { type:'combat', playerSwungOnce:true, guildBoss:{ idx:1 }, monsterId:FF.MONSTERS[0].id, monsterHp:100 };
      FF.guildBossEnter(0);
      ok(/already fighting a Guild Boss/.test(gs.error), 'already on a boss reports a distinct message');
    } finally {
      S.activity = snap.act; gs.error = gsnap.err; gst.guild = gsnap.guild;
    }
  });

  // ---- ticket-0108: scrollable popups must survive the loop's re-renders --------------------------
  suite('ui: overlay writes never rebuild an unchanged popup', function(){
    // The game loop renders several times a second. Any overlay that blindly re-assigned innerHTML
    // destroyed its own DOM, so a scrolled card snapped back to the top -- the skill tracker and the
    // offline loot/familiar summaries. setOverlayHtml() is the guard: identical markup is a no-op.
    var host = document.createElement('div');
    document.body.appendChild(host);
    try {
      var wrote1 = FF.setOverlayHtml(host, '<div class="card">alpha</div>', 'ov');
      eq(wrote1, true, 'the first write lands');
      eq(host.className, 'ov', '...and sets the class');
      var node1 = host.firstElementChild;
      var wrote2 = FF.setOverlayHtml(host, '<div class="card">alpha</div>', 'ov');
      eq(wrote2, false, 'an identical re-write is skipped entirely');
      ok(host.firstElementChild === node1, '...and the DOM node is untouched (so its scroll survives)');
      // A real content change still lands, and carries the scrolled offset across the rebuild.
      node1.style.height = '40px'; node1.style.overflow = 'auto';
      node1.innerHTML = '<div style="height:400px"></div>';
      node1.scrollTop = 90;
      var kept = node1.scrollTop; // the browser may clamp; compare against what it actually took
      var wrote3 = FF.setOverlayHtml(host, '<div class="card" style="height:40px;overflow:auto"><div style="height:400px"></div>beta</div>', 'ov');
      eq(wrote3, true, 'changed markup does write');
      if(kept > 0) eq(host.firstElementChild.scrollTop, kept, '...and the scroll offset is carried across the rebuild');
      // Clearing works through the same path.
      FF.setOverlayHtml(host, '', '');
      eq(host.innerHTML, '', 'clearing an overlay goes through the same guard');
      eq(FF.setOverlayHtml(null, 'x'), false, 'a missing element is a safe no-op');
      // HARDENING: if a close path clears the DOM directly (bypassing the guard), the memo would be stale
      // and an identical re-open would be skipped -- leaving an empty modal. The child-count sanity check
      // must force the write instead. This is a real pattern in the codebase (the death report did it).
      FF.setOverlayHtml(host, '<div class="card">gamma</div>', 'ov');
      host.innerHTML = '';                                    // simulate a bypassing close
      var reopened = FF.setOverlayHtml(host, '<div class="card">gamma</div>', 'ov');
      eq(reopened, true, 'an identical re-open after a direct clear still writes');
      ok(/gamma/.test(host.innerHTML), '...so the popup is actually populated, not blank');
    } finally { if(host.parentNode) host.parentNode.removeChild(host); }
  });

  // ---- Enemy swap fade: a kill must visibly change the portrait, even for an identical next foe ----
  suite('combat: enemy defeat fades the portrait', function(){
    eq(FF.ENEMY_SWAP_MS, 550, 'the swap window matches the enemySwapFade animation duration');
    var S = FF._state;
    var snap = { act:S.activity, swap:S._enemySwapAt, inv:S.inventory };
    try {
      var mon = FF.MONSTERS[0];
      S.inventory = {};
      S._enemySwapAt = 0;
      S.activity = { type:'combat', playerSwungOnce:true, monsterId:mon.id, monsterHp:0, tickAccum:0, monsterTickAccum:0, duelStartedAt:Date.now() };
      FF.defeatMonster(mon);
      ok(S._enemySwapAt > 0, 'defeatMonster stamps the swap so the arena can play the fade');
      eq(S.activity.monsterHp, mon.hp, '...and the next foe of the same type arrives at full HP');
      // The chain re-engages the SAME monster, which is exactly why the fade matters: without it the
      // portrait never changes and a kill is invisible.
      eq(S.activity.monsterId, mon.id, 'a grind chain re-engages the same monster id');
      // The portrait carries the id the live-patch loop drives the animation through.
      var markup = FF.renderCombatTab();
      ok(/id="arenaMonsterPortrait"/.test(markup), 'the arena renders the monster portrait with its animation hook id');
    } finally { S.activity = snap.act; S._enemySwapAt = snap.swap; S.inventory = snap.inv; }
  });

  // ---- Kin-sworn loot: drop Inscription Scrolls at 5% (no more equipment) ------------------------
  suite('loot: kinsworn drop inscription scrolls', function(){
    var fake = { category:'kinsworn', tierIndex:5, element:'water', name:'Test Kinsman' };
    eq(FF.getMonsterLootChance(fake), 5, 'kinsworn loot chance is 5%');
    eq(FF.getMonsterLootLabel(fake), 'Inscription', 'kinsworn loot label is Inscription');
    var cat = FF.MONSTER_CATEGORIES.filter(function(c){ return c.id==='kinsworn'; })[0];
    ok(cat && /Inscription|Scroll/.test(cat.desc) && !/equipment/i.test(cat.desc), 'Kin-sworn category describes Inscriptions, not equipment');
    // Functional: the only thing a Kin-sworn can ever add is a tier-matched Inscription Scroll.
    var S = FF._state; var saveInv = S.inventory;
    var bad = {}, sawScroll = false, tier = 7;
    try {
      var mon = { category:'kinsworn', tierIndex:tier, element:'water', name:'Test Kinsman' };
      for(var n=0; n<400; n++){
        S.inventory = {};
        FF.applyMonsterCategoryLoot(mon);
        Object.keys(S.inventory).forEach(function(id){ if(id==='scroll_t'+tier) sawScroll = true; else bad[id] = true; });
      }
    } finally { S.inventory = saveInv; }
    ok(Object.keys(bad).length === 0, 'kin-sworn drop only tier-matched Inscription Scrolls' + (Object.keys(bad).length ? ' (leaked: '+Object.keys(bad).join(', ')+')' : ''));
    ok(sawScroll, 'Inscription Scrolls do drop (~5% of kills)');
  });

  // ---- Demonspawn loot: drop Enchant Crystals at 5% (no more Broken Relics) ----------------------
